	e.p("\t\t\t// engine hands back an ordinary object: the initializer is")
	e.p("\t\t\t// never called and var_dump prints no label.")
	e.p("\t\t\tphp.DropLazy(ctx, ghost)")
	e.p("\t\t\tphp.DropDynamicProperties(ghost)")
	e.p("\t\t}")
	e.p("\t\tphp.ApplyLazyFlags(ghost, options)")
	e.p("\t\treturn php.Obj(ghost), nil")
	e.p("\tcase \"newinstancewithoutconstructor\":")
	e.p("\t\tif r.kind != \"ReflectionClass\" && r.kind != \"ReflectionObject\" {")
	e.p("\t\t\tbreak")
	e.p("\t\t}")
	e.p("\t\t// The constructor helper is exactly this: it declares and defaults")
	e.p("\t\t// every slot before any `__construct` runs, so an instance built")
	e.p("\t\t// from it and nothing else is what the engine produces -- a typed")
	e.p("\t\t// property with no default staying *uninitialized* rather than null.")
	e.p("\t\tif err := instantiableErr(r.subject); err != nil {")
	e.p("\t\t\treturn php.Value{}, err")
	e.p("\t\t}")
	e.p("\t\tbuilt, made, err := ctx.NewInstance(r.subject)")
	e.p("\t\tif err != nil || !made {")
	e.p("\t\t\treturn php.Value{}, err")
	e.p("\t\t}")
	e.p("\t\treturn php.Obj(built), nil")
	e.p("\tcase \"newinstanceargs\":")
	e.p("\t\tif r.kind != \"ReflectionClass\" && r.kind != \"ReflectionObject\" {")
	e.p("\t\t\tbreak")
	e.p("\t\t}")
	e.p("\t\tlist, err := reflectSpreadArgs(ctx, php.Arg(args, 0))")
	e.p("\t\tif err != nil {")
	e.p("\t\t\treturn php.Value{}, err")
	e.p("\t\t}")
	e.p("\t\treturn constructReflected(ctx, r.subject, list)")
	e.p("\tcase \"isrepeated\":")
	e.p("\t\tif r.kind == \"ReflectionAttribute\" {")
	e.p("\t\t\treturn php.Bool(r.repeated), nil")
	e.p("\t\t}")
	e.p("\tcase \"gettarget\":")
	e.p("\t\t// Where the attribute was written, as an Attribute::TARGET_*")
	e.p("\t\t// constant: the reflector that produced it.")
	e.p("\t\tif r.kind != \"ReflectionAttribute\" {")
	e.p("\t\t\tbreak")
	e.p("\t\t}")
	e.p("\t\tswitch r.origin {")
	e.p("\t\tcase \"ReflectionClass\", \"ReflectionObject\":")
	e.p("\t\t\treturn php.Int(attrTargetClass), nil")
	e.p("\t\tcase \"ReflectionFunction\":")
	e.p("\t\t\treturn php.Int(attrTargetFunction), nil")
	e.p("\t\tcase \"ReflectionMethod\":")
	e.p("\t\t\treturn php.Int(attrTargetMethod), nil")
	e.p("\t\tcase \"ReflectionProperty\":")
	e.p("\t\t\treturn php.Int(attrTargetProperty), nil")
	e.p("\t\tcase \"ReflectionClassConstant\":")
	e.p("\t\t\treturn php.Int(attrTargetClassConstant), nil")
	e.p("\t\tcase \"ReflectionParameter\":")
	e.p("\t\t\treturn php.Int(attrTargetParameter), nil")
	e.p("\t\t}")
	e.p("\tcase \"newinstance\":")
	e.p("\t\tif r.kind == \"ReflectionClass\" || r.kind == \"ReflectionObject\" {")
	e.p("\t\t\treturn constructReflected(ctx, r.subject, args)")
	e.p("\t\t}")
	e.p("\t\tif r.kind != \"ReflectionAttribute\" {")
	e.p("\t\t\tbreak")
	e.p("\t\t}")
	e.p("\t\t// **Now** the constructor runs: an attribute is a declaration")
	e.p("\t\t// until something asks for an instance of it.")
	e.p("\t\tclass := resolveAlias(r.attr.name)")
	e.p("\t\t// An engine attribute class this output does not model --")
	e.p("\t\t// Override, SensitiveParameter -- exists: a gap, not `not found`.")
	e.p("\t\tif !declaredClasses[strings.ToLower(class)] && engineClassKind[strings.ToLower(class)] {")
	e.p("\t\t\treturn php.Value{}, php.Unsupported(\"newInstance of engine attribute class %%s\", engineSpelling(class))")
	e.p("\t\t}")
	e.p("\t\tif !declaredClasses[strings.ToLower(class)] {")
	e.p("\t\t\treturn php.Value{}, php.RaiseAt(ctx, \"Error\", \"%%s\", \"Attribute class \\\"\"+r.attr.name+\"\\\" not found\")")
	e.p("\t\t}")
	e.p("\t\t// **Where it was written has to be allowed.** `#[Attribute(...)]`")
	e.p("\t\t// on the attribute class restricts its targets, and using it")
	e.p("\t\t// elsewhere is an Error raised *here* -- at newInstance(), not at")
	e.p("\t\t// the declaration, because an attribute is only checked when")
	e.p("\t\t// something asks for an instance of it.")
	e.p("\t\tif err := checkAttributeTarget(ctx, class, r.attr.name, r.origin); err != nil {")
	e.p("\t\t\treturn php.Value{}, err")
	e.p("\t\t}")
	e.p("\t\t// **Written twice on one target, it has to allow it**: without")
	e.p("\t\t// IS_REPEATABLE that is `Attribute \"A1\" must not be repeated`,")
	e.p("\t\t// asked after the target (020_userland_attribute_validation).")
	e.p("\t\tif r.repeated {")
	e.p("\t\t\tflags, err := attributeTargets(ctx, class)")
	e.p("\t\t\tif err != nil {")
	e.p("\t\t\t\treturn php.Value{}, err")
	e.p("\t\t\t}")
	e.p("\t\t\tif flags&64 == 0 {")
	e.p("\t\t\t\treturn php.Value{}, php.RaiseAt(ctx, \"Error\", \"%%s\", \"Attribute \\\"\"+r.attr.name+\"\\\" must not be repeated\")")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\tbuilt, made, err := ctx.NewInstance(class)")
	e.p("\t\tif err != nil || !made {")
	e.p("\t\t\treturn php.Value{}, err")
	e.p("\t\t}")
	e.p("\t\t// **Names cover the trailing arguments only.** PHP requires named")
	e.p("\t\t// arguments after positional ones, and an attribute is written the")
	e.p("\t\t// same way, so the split preserves the order as written. Passing a")
	e.p("\t\t// name for every argument -- empty string for the positional ones --")
	e.p("\t\t// made the binder look for a parameter called `$`.")
	e.p("\t\tvar ctorArgs []php.Value")
	e.p("\t\tvar names []string")
	e.p("\t\tfor _, a := range r.attr.args {")
	e.p("\t\t\tctorArgs = append(ctorArgs, a.get(ctx))")
	e.p("\t\t\tif err := ctx.TakePendingError(); err != nil {")
	e.p("\t\t\t\treturn php.Value{}, err")
	e.p("\t\t\t}")
	e.p("\t\t\tif a.name != \"\" {")
	e.p("\t\t\t\tnames = append(names, a.name)")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\tif len(names) > 0 {")
	e.p("\t\t\tctx.SetArgNames(names)")
	e.p("\t\t}")
	e.p("\t\t// **The constructor is called from where the attribute is")
	e.p("\t\t// written**: its frame's call site is the `#[...]` line, not")
	e.p("\t\t// newInstance()'s and not `[internal function]`.")
	e.p("\t\t// An attribute written in an included file is called from that")
	e.p("\t\t// file, whose strict_types binds the arguments (030_strict_types).")
	e.p("\t\tif r.attr.line > 0 {")
	e.p("\t\t\tsite := srcFile")
	e.p("\t\t\tif r.attr.file != \"\" {")
	e.p("\t\t\t\tsite = r.attr.file")
	e.p("\t\t\t}")
	e.p("\t\t\trestore := ctx.SetCallSite(&php.StackFrame{File: site, Line: r.attr.line})")
	e.p("\t\t\tdefer restore()")
	e.p("\t\t}")
	e.p("\t\t// Constructed from no class's scope: a private constructor is")
	e.p("\t\t// `Call to private A3::__construct() from global scope`.")
	e.p("\t\tif err := ctorAccess(ctx, php.Obj(built), \"\"); err != nil {")
	e.p("\t\t\treturn php.Value{}, err")
	e.p("\t\t}")
	e.p("\t\tif _, err := callCtor(ctx, php.Obj(built), ctorArgs); err != nil {")
	e.p("\t\t\treturn php.Value{}, err")
	e.p("\t\t}")
	e.p("\t\treturn php.Obj(built), nil")
	e.p("\t}")
	e.p("\treturn php.Value{}, php.Unsupported(\"internal method %%s::%%s\", self.ClassName, name)")
	e.p("}")
	e.p("")
	e.p("// reflectAttributes wraps a declaration's attribute list in")
	e.p("// ReflectionAttribute objects, honouring the one filter flag.")
	e.p("func reflectAttributes(ctx *php.Ctx, r *reflector, args []php.Value) (php.Value, error) {")
	e.p("\tvar list []attrRecord")
	e.p("\tswitch r.kind {")
	e.p("\t// **ReflectionObject is a ReflectionClass** and reads the same list;")
	e.p("\t// it answered none (020_userland_attribute_validation).")
	e.p("\tcase \"ReflectionClass\", \"ReflectionObject\":")
	e.p("\t\tlist = classAttributes[strings.ToLower(r.subject)]")
	e.p("\tcase \"ReflectionFunction\":")
	e.p("\t\tlist = functionAttributes[strings.ToLower(r.subject)]")
	e.p("\t\tif o := r.callable.Deref().Object(); o != nil {")
	e.p("\t\t\tif b, ok := o.Internal.(*closureBody); ok {")
	e.p("\t\t\t\tlist = inClosureScope(list, b.scope)")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\tcase \"ReflectionMethod\":")
	e.p("\t\t// **An inherited method's attributes are its declaration's**:")
	e.p("\t\t// `C3::foo` from `C1` reads C1's `#[A1]` (011_inheritance).")
	e.p("\t\tkey := strings.ToLower(r.subject) + \"::\" + strings.ToLower(r.member)")
	e.p("\t\tif _, own := methodAttributes[key]; !own {")
	e.p("\t\t\tif owner, _, _, ok := methodOwnerOf(r.subject, strings.ToLower(r.member)); ok {")
	e.p("\t\t\t\tkey = strings.ToLower(owner) + \"::\" + strings.ToLower(r.member)")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\tlist = methodAttributes[key]")
	e.p("\tcase \"ReflectionProperty\":")
	e.p("\t\tlist = propertyAttributes[strings.ToLower(r.subject)+\"::\"+strings.ToLower(r.member)]")
	e.p("\tcase \"ReflectionClassConstant\":")
	e.p("\t\tlist = constAttributes[strings.ToLower(r.subject)+\"::\"+r.member]")
	e.p("\tcase \"ReflectionParameter\":")
	e.p("\t\t// Keyed as reflectParams is: a closure under its Go name.")
	e.p("\t\tlist = paramAttributes[fmt.Sprintf(\"%%s#%%d\", r.subject, r.index)]")
	e.p("\t\tif o := r.callable.Deref().Object(); o != nil {")
	e.p("\t\t\tif b, ok := o.Internal.(*closureBody); ok {")
	e.p("\t\t\t\tlist = inClosureScope(list, b.scope)")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tfilter := \"\"")
	e.p("\tif len(args) > 0 && args[0].Deref().Kind() != php.KindNull {")
	e.p("\t\tfilter = args[0].Deref().String()")
	e.p("\t}")
	e.p("\t// **The flags are 0 or IS_INSTANCEOF**, anything else a ValueError")
	e.p("\t// named after the method's declaring reflector; and an IS_INSTANCEOF")
	e.p("\t// filter must name a class that exists (006_filter).")
	e.p("\tif len(args) > 1 {")
	e.p("\t\tif f := args[1].Deref().Int(); f != 0 && f != 2 {")
	e.p("\t\t\towner := r.kind")
	e.p("\t\t\tswitch r.kind {")
	e.p("\t\t\tcase \"ReflectionFunction\", \"ReflectionMethod\":")
	e.p("\t\t\t\towner = \"ReflectionFunctionAbstract\"")
	e.p("\t\t\tcase \"ReflectionObject\":")
	e.p("\t\t\t\towner = \"ReflectionClass\"")
	e.p("\t\t\t}")
	e.p("\t\t\treturn php.Value{}, php.RaiseAt(ctx, \"ValueError\", \"%%s::getAttributes(): Argument #2 ($flags) must be a valid attribute filter flag\", owner)")
	e.p("\t\t}")
	e.p("\t\tif args[1].Deref().Int() == 2 && filter != \"\" {")
	e.p("\t\t\tif found, err := knownClass(ctx, filter); err != nil {")
	e.p("\t\t\t\treturn php.Value{}, err")
	e.p("\t\t\t} else if found == \"\" && !engineClassKind[strings.ToLower(filter)] && !engineInterfaceKind[strings.ToLower(filter)] {")
	e.p("\t\t\t\treturn php.Value{}, php.RaiseAt(ctx, \"Error\", \"Class \\\"%%s\\\" not found\", filter)")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tinstanceOfFilter := len(args) > 1 && args[1].Deref().Int() == 2")
	e.p("\tout := php.NewArray()")
	e.p("\t// isRepeated is about the target, not the filtered list: the same")
	e.p("\t// name written twice on it.")
	e.p("\tcounts := map[string]int{}")
	e.p("\tfor _, rec := range list {")
	e.p("\t\tcounts[strings.ToLower(rec.name)]++")
	e.p("\t}")
	e.p("\tfor _, rec := range list {")
	e.p("\t\tswitch {")
	e.p("\t\tcase filter == \"\":")
	e.p("\t\tcase instanceOfFilter:")
	e.p("\t\t\tif !extendsClass(rec.name, filter) {")
	e.p("\t\t\t\tcontinue")
	e.p("\t\t\t}")
	e.p("\t\tdefault:")
	e.p("\t\t\tif !strings.EqualFold(rec.name, filter) {")
	e.p("\t\t\t\tcontinue")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\tattr := newReflectionAttribute(rec, r.kind)")
	e.p("\t\tattr.Internal.(*reflector).repeated = counts[strings.ToLower(rec.name)] > 1")
	e.p("\t\tout.Append(php.Obj(attr))")
	e.p("\t}")
	e.p("\treturn php.Arr(out), nil")
	e.p("}")
	e.p("")
	e.p("// fiberRaise turns a driver sentinel into the FiberError a program can")
	e.p("// catch. `runtime/php` reports conditions rather than exceptions because")
	e.p("// constructing one needs a class table, which is here and not there.")
	e.p("func fiberRaise(ctx *php.Ctx, err error) error {")
	e.p("\tif err == nil {")
	e.p("\t\treturn nil")
	e.p("\t}")
	e.p("\tif msg, ok := php.FiberErrorMessage(err); ok {")
	e.p("\t\treturn php.RaiseAt(ctx, \"FiberError\", \"%%s\", msg)")
	e.p("\t}")
	e.p("\treturn err")
	e.p("}")
	e.p("")
	e.p("// fiberMethod is the instance side of Fiber. The driver in runtime/php")
	e.p("// owns the protocol; what is here is turning a callable into the frame")
	e.p("// it drives, which needs this program's own bodies.")
	e.p("func fiberMethod(ctx *php.Ctx, self *php.Object, h *php.FiberHandle, name string, args []php.Value) (php.Value, error) {")
	e.p("\targs = php.UnboxArgs(args)")
	e.p("\targument := func(i int) php.Value {")
	e.p("\t\tif i < len(args) {")
	e.p("\t\t\treturn args[i].Deref()")
	e.p("\t\t}")
	e.p("\t\treturn php.Null()")
	e.p("\t}")
	e.p("\tswitch name {")
	e.p("\tcase \"__construct\":")
	e.p("\t\t// A Fiber is constructed once, whatever state it is in")
	e.p("\t\t// (fibers/multiple-calls-to-ctor, call-to-ctor-of-terminated-fiber).")
	e.p("\t\treturn php.Value{}, php.RaiseAt(ctx, \"FiberError\", \"%%s\", \"Cannot call constructor twice\")")
	e.p("\tcase \"start\":")
	e.p("\t\t// **A tick function may not switch fibers** (zend_fiber_switch_block")
	e.p("\t\t// around ZEND_TICKS), checked before the fiber's own state but")
	e.p("\t\t// after the arguments (probed): a fiber that never suspends runs")
	e.p("\t\t// as a plain call below and would otherwise skip the driver's check.")
	e.p("\t\tif ctx.FiberSwitchBlocked() {")
	e.p("\t\t\treturn php.Value{}, php.ErrFiberSwitchBlocked")
	e.p("\t\t}")
	e.p("\t\tif h.Driver != nil {")
	e.p("\t\t\treturn php.Value{}, php.ErrFiberAlreadyStarted")
	e.p("\t\t}")
	e.p("\t\t// **The arguments belong to start(), not to the constructor.**")
	e.p("\t\t// They are the callable's own parameters, bound into the frame by")
	e.p("\t\t// the `recv`s in its first state, which is why the frame cannot be")
	e.p("\t\t// built before now.")
	e.p("\t\tframe, made, err := ctx.ResumableOf(h.Callable, args)")
	e.p("\t\tif err != nil {")
	e.p("\t\t\treturn php.Value{}, err")
	e.p("\t\t}")
	e.p("\t\t// **`@` belongs to the fiber it is written in**: the body starts")
	e.p("\t\t// at the caller's level without the caller's `@`, and whatever it")
	e.p("\t\t// is inside when it suspends is its own, handed back on resume")
	e.p("\t\t// (silence-operator-inside-fiber, -outside-fiber).")
	e.p("\t\touterSilence := ctx.SwapSilence(ctx.FreshSilence())")
	e.p("\t\tdefer func() { h.Silence = ctx.SwapSilence(outerSilence) }()")
	e.p("\t\tif !made {")
	e.p("\t\t\t// A callable with no `Fiber::suspend()` in it. It cannot")
	e.p("\t\t\t// suspend, so the whole fiber is one call that runs to its end")
	e.p("\t\t\t// -- which is what the engine does too, and `start()` answers")
	e.p("\t\t\t// NULL because nothing suspended.")
	e.p("\t\t\t// **It is still the current fiber while it runs**:")
	e.p("\t\t\t// `Fiber::getCurrent()` inside answers it, and resuming it from")
	e.p("\t\t\t// inside is `Cannot resume a fiber that is not suspended`")
	e.p("\t\t\t// (resume-running-fiber) rather than a call on null.")
	e.p("\t\t\tleave := ctx.EnterFiber(self)")
	e.p("\t\t\tv, callErr := ctx.Call(h.Callable, args)")
	e.p("\t\t\tleave()")
	e.p("\t\t\tif callErr != nil {")
	e.p("\t\t\t\th.Driver = php.ThrewFiber()")
	e.p("\t\t\t\treturn php.Value{}, callErr")
	e.p("\t\t\t}")
	e.p("\t\t\th.Driver = php.ReturnedFiber(v)")
	e.p("\t\t\treturn php.Null(), nil")
	e.p("\t\t}")
	e.p("\t\th.Driver = php.NewFiber(frame)")
	e.p("\t\tdone := ctx.EnterFiber(self)")
	e.p("\t\tdefer done()")
	e.p("\t\t// The callable's own frame -- `[internal function]: {closure}()`,")
	e.p("\t\t// the engine made this call -- is the driver's root frame, which")
	e.p("\t\t// it pushes on every entry; pushing it here as well put it in")
	e.p("\t\t// every trace from a first start twice (start-arguments).")
	e.p("\t\treturn h.Driver.Start(ctx)")
	e.p("\tcase \"resume\":")
	e.p("\t\tif ctx.FiberSwitchBlocked() {")
	e.p("\t\t\treturn php.Value{}, php.ErrFiberSwitchBlocked")
	e.p("\t\t}")
	e.p("\t\tif h.Driver == nil {")
	e.p("\t\t\treturn php.Value{}, php.ErrFiberNotSuspended")
	e.p("\t\t}")
	e.p("\t\touterSilence := ctx.SwapSilence(h.Silence)")
	e.p("\t\tdefer func() { h.Silence = ctx.SwapSilence(outerSilence) }()")
	e.p("\t\tdone := ctx.EnterFiber(self)")
	e.p("\t\tdefer done()")
	e.p("\t\treturn h.Driver.Resume(ctx, argument(0))")
	e.p("\tcase \"throw\":")
	e.p("\t\t// The argument is checked first, then the switch, then the")
	e.p("\t\t// fiber's state, as the engine orders them (probed).")
	e.p("\t\tthrown := argument(0)")
	e.p("\t\tif thrown.Kind() != php.KindObject || !instanceOf(thrown, \"Throwable\") {")
	e.p("\t\t\treturn php.Value{}, php.RaiseAt(ctx, \"TypeError\", \"Fiber::throw(): Argument #1 ($exception) must be of type Throwable, %%s given\", php.ValueName(thrown))")
	e.p("\t\t}")
	e.p("\t\tif ctx.FiberSwitchBlocked() {")
	e.p("\t\t\treturn php.Value{}, php.ErrFiberSwitchBlocked")
	e.p("\t\t}")
	e.p("\t\tif h.Driver == nil {")
	e.p("\t\t\treturn php.Value{}, php.ErrFiberNotSuspended")
	e.p("\t\t}")
	e.p("\t\touterSilence := ctx.SwapSilence(h.Silence)")
	e.p("\t\tdefer func() { h.Silence = ctx.SwapSilence(outerSilence) }()")
	e.p("\t\tdone := ctx.EnterFiber(self)")
	e.p("\t\tdefer done()")
	e.p("\t\treturn h.Driver.Throw(ctx, php.Throw(thrown.Object()))")
	e.p("\tcase \"getreturn\":")
	e.p("\t\tif h.Driver == nil {")
	e.p("\t\t\treturn php.Value{}, php.ErrFiberNotStarted")
	e.p("\t\t}")
	e.p("\t\treturn h.Driver.GetReturn()")
	e.p("\tcase \"isstarted\":")
	e.p("\t\treturn php.Bool(h.Driver != nil), nil")
	e.p("\tcase \"issuspended\":")
	e.p("\t\treturn php.Bool(h.Driver != nil && h.Driver.IsSuspended()), nil")
	e.p("\tcase \"isrunning\":")
	e.p("\t\treturn php.Bool(h.Driver != nil && h.Driver.IsRunning()), nil")
	e.p("\tcase \"isterminated\":")
	e.p("\t\treturn php.Bool(h.Driver != nil && h.Driver.IsTerminated()), nil")
	e.p("\t}")
	e.p("\treturn php.Value{}, php.Unsupported(\"internal method Fiber::%%s\", name)")
	e.p("}")
	e.p("")
	e.p("// newSuspendingClosure is newClosure for a body that suspends into its")
	e.p("// caller: the same object, carrying the frame constructor a Fiber needs.")
	e.p("func newSuspendingClosure(fn func(*php.Ctx, *php.Object, map[string]*php.Value, string, []php.Value) (php.Value, error), frame func(*php.Ctx, *php.Object, map[string]*php.Value, string, []php.Value) php.Resumable, this *php.Object, meta closureMeta, scope string) *php.Object {")
	e.p("\to := newClosure(fn, this, meta, scope)")
	e.p("\to.Internal.(*closureBody).frame = frame")
	e.p("\treturn o")
	e.p("}")
	e.p("")
	e.p("// resumableOf builds the frame behind a callable without running it,")
	e.p("// which is what `Fiber::start()` drives.")
	e.p("//")
	e.p("// handled=false for a callable that exists but was not compiled as a")
	e.p("// state machine. That is the ordinary case and not an error: a body with")
	e.p("// no `Fiber::suspend()` in it runs to completion on the first start, so")
	e.p("// the caller does a plain call instead.")
	e.p("func resumableOf(ctx *php.Ctx, callee php.Value, args []php.Value) (php.Resumable, bool, error) {")
	e.p("\tv := callee.Deref()")
	e.p("\tif o := v.Object(); o != nil {")
	e.p("\t\tif b, ok := o.Internal.(*closureBody); ok {")
	e.p("\t\t\tif b.frame == nil {")
	e.p("\t\t\t\treturn nil, false, nil")
	e.p("\t\t\t}")
	e.p("\t\t\treturn b.frame(ctx, b.this, b.bound, b.scope, args), true, nil")
	e.p("\t\t}")
	e.p("\t\t// **An object with `__invoke` is a callable**, and `new Fiber($obj)`")
	e.p("\t\t// is ordinary PHP. The frame is the method's, found the way any")
	e.p("\t\t// method call finds one -- from the receiver's class chain --")
	e.p("\t\t// because which `__invoke` runs is a run-time fact.")
	e.p("\t\tfor c := o.ClassName; c != \"\"; c = parentOf[c] {")
	e.p("\t\t\tif make, ok := methodFrames[c][\"__invoke\"]; ok {")
	e.p("\t\t\t\treturn make(ctx, o, args), true, nil")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\treturn nil, false, nil")
	e.p("\t}")
	e.p("\tif mk, ok := suspendFrames[strings.ToLower(v.String())]; ok {")
	e.p("\t\treturn mk(ctx, args), true, nil")
	e.p("\t}")
	e.p("\treturn nil, false, nil")
	e.p("}")
	e.p("")
	e.p("// rebind is `bindTo`: a **new** Closure over the same body, receiver and")
	e.p("// captures replaced. The capture boxes are shared rather than copied, so")
	e.p("// a `use (&$x)` still writes through to the same variable.")
	e.p("// A **static** closure refuses an instance: `Warning: Cannot bind an")
	e.p("// instance to a static closure`, and the result is null rather than a")
	e.p("// new Closure. Binding only a *scope* to one is still allowed, which is")
	e.p("// why the refusal asks about the receiver and not about being static.")
	e.p("// internalScopeRefused is the engine's refusal to give a closure the scope")
	e.p("// of an **engine** class it did not already have: `Warning: Cannot bind")
	e.p("// closure to scope of internal class stdClass`, and the operation")
	e.p("// answers null. `Closure` itself is the dummy scope an object bound with")
	e.p("// no scope gets, never a refusal.")
	e.p("func (b *closureBody) internalScopeRefused(ctx *php.Ctx, scope string) (bool, error) {")
	e.p("\tif scope == \"\" || strings.EqualFold(scope, b.scope) || strings.EqualFold(scope, \"Closure\") ||")
	e.p("\t\t!engineClassKind[strings.ToLower(scope)] {")
	e.p("\t\treturn false, nil")
	e.p("\t}")
	e.p("\tctx.Warn(\"Cannot bind closure to scope of internal class %%s\", php.DisplayName(engineSpelling(scope)))")
	e.p("\treturn true, ctx.TakePendingError()")
	e.p("}")
	e.p("")
	e.p("// methodBindingRefused applies the rules a closure made from a **method**")
	e.p("// keeps (probed): it takes no object that is not of the method's class,")
	e.p("// a static one takes none at all, a non-static one cannot lose its")
	e.p("// `$this`, and its scope is the method's class for good. Each is a")
	e.p("// warning and a null answer.")
	e.p("func (b *closureBody) methodBindingRefused(ctx *php.Ctx, this *php.Object, scope string) (bool, error) {")
	e.p("\tclass, method, isMethod := strings.Cut(b.meta.function, \"::\")")
	e.p("\t// Only a closure made from something already named is a \"fake\"")
	e.p("\t// closure; a literal's rules are rebind's own.")
	e.p("\tif b.meta.function == \"\" || b.meta.name != b.meta.function {")
	e.p("\t\treturn false, nil")
	e.p("\t}")
	e.p("\t// funcScope is the function's own class: none for a function.")
	e.p("\tfuncScope, isStatic := \"\", false")
	e.p("\tif isMethod {")
	e.p("\t\t_, _, st, known := methodOwnerOf(realClassOr(strings.ToLower(class)), strings.ToLower(method))")
	e.p("\t\tif !known {")
	e.p("\t\t\t// An engine class's method, from the harvested table.")
	e.p("\t\t\tif c := engineChainClass(class); c != nil {")
	e.p("\t\t\t\tif m, ok := c.methods[strings.ToLower(method)]; ok {")
	e.p("\t\t\t\t\tst, known = m.static, true")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\tif !known {")
	e.p("\t\t\treturn false, nil")
	e.p("\t\t}")
	e.p("\t\tfuncScope, isStatic = class, st")
	e.p("\t}")
	e.p("\t// **The engine's order** (zend_valid_closure_binding, probed): the")
	e.p("\t// object first, then an engine-class scope, then any other change of")
	e.p("\t// scope. A scope left as it was -- bindTo with none given, which a")
	e.p("\t// closure holding no scope of its own turns into the `Closure` dummy")
	e.p("\t// -- is no change.")
	e.p("\t// The closure's own scope counts as unchanged too: `bindTo($o)` keeps")
	e.p("\t// it, whichever class it was made in.")
	e.p("\tsame := strings.EqualFold(scope, funcScope) || strings.EqualFold(scope, b.scope) ||")
	e.p("\t\t(b.scope == \"\" && strings.EqualFold(scope, \"Closure\"))")
	e.p("\tswitch {")
	e.p("\tcase this != nil && isStatic:")
	e.p("\t\tctx.Warn(\"Cannot bind an instance to a static closure\")")
	e.p("\tcase this != nil && funcScope != \"\" && !extendsClass(this.ClassName, realClassOr(strings.ToLower(class))):")
	e.p("\t\tctx.Warn(\"Cannot bind method %%s() to object of class %%s\", b.meta.function, php.DisplayName(this.ClassName))")
	e.p("\tcase this == nil && funcScope != \"\" && !isStatic:")
	e.p("\t\tctx.Warn(\"Cannot unbind $this of method\")")
	e.p("\tcase !same && scope != \"\" && !strings.EqualFold(scope, \"Closure\") && engineClassKind[strings.ToLower(scope)]:")
	e.p("\t\tctx.Warn(\"Cannot bind closure to scope of internal class %%s\", php.DisplayName(engineSpelling(scope)))")
	e.p("\tcase !same && funcScope == \"\":")
	e.p("\t\tctx.Warn(\"Cannot rebind scope of closure created from function\")")
	e.p("\tcase !same:")
	e.p("\t\tctx.Warn(\"Cannot rebind scope of closure created from method\")")
	e.p("\tdefault:")
	e.p("\t\treturn false, nil")
	e.p("\t}")
	e.p("\treturn true, ctx.TakePendingError()")
	e.p("}")
	e.p("")
	e.p("func (b *closureBody) rebind(ctx *php.Ctx, this *php.Object, scope string) (php.Value, error) {")
	e.p("\tif refused, err := b.methodBindingRefused(ctx, this, scope); refused || err != nil {")
	e.p("\t\treturn php.Null(), err")
	e.p("\t}")
	e.p("\t// **A scope named by a string must exist**, autoloaded if need be:")
	e.p("\t// `bindTo($o, \"Nope\")` warns `Class \"Nope\" not found` and answers")
	e.p("\t// null.")
	e.p("\tif scope != \"\" && !strings.EqualFold(scope, \"Closure\") && realClass(scope) == \"\" && !engineClassKind[strings.ToLower(resolveAlias(scope))] {")
	e.p("\t\tfound, err := knownClass(ctx, scope)")
	e.p("\t\tif err != nil {")
	e.p("\t\t\treturn php.Value{}, err")
	e.p("\t\t}")
	e.p("\t\tif found == \"\" {")
	e.p("\t\t\tctx.Warn(\"Class \\\"%%s\\\" not found\", scope)")
	e.p("\t\t\tif err := ctx.TakePendingError(); err != nil {")
	e.p("\t\t\t\treturn php.Value{}, err")
	e.p("\t\t\t}")
	e.p("\t\t\treturn php.Null(), nil")
	e.p("\t\t}")
	e.p("\t\tscope = found")
	e.p("\t}")
	e.p("\tif refused, err := b.internalScopeRefused(ctx, scope); refused || err != nil {")
	e.p("\t\treturn php.Null(), err")
	e.p("\t}")
	e.p("\t// **A closure whose body reads `$this` keeps one**: `bindTo(null)` on")
	e.p("\t// it warns and answers null, where one that never touches `$this`")
	e.p("\t// unbinds quietly. One made where there was no `$this` -- in a")
	e.p("\t// static method -- is static already and has none to lose.")
	e.p("\tif this == nil && !b.meta.static && b.meta.usesThis && b.meta.function == \"\" && b.this != nil {")
	e.p("\t\tctx.Warn(\"Cannot unbind $this of closure using $this\")")
	e.p("\t\tif err := ctx.TakePendingError(); err != nil {")
	e.p("\t\t\treturn php.Value{}, err")
	e.p("\t\t}")
	e.p("\t\treturn php.Null(), nil")
	e.p("\t}")
	e.p("	if b.meta.static && this != nil {")
	e.p("		ctx.Warn(\"Cannot bind an instance to a static closure\")")
	e.p("\t\tif err := ctx.TakePendingError(); err != nil {")
	e.p("\t\t\treturn php.Value{}, err")
	e.p("\t\t}")
	e.p("\t\treturn php.Null(), nil")
	e.p("\t}")
	e.p("	return php.Obj(b.rebound(this, scope)), nil")
	e.p("}")
	e.p("")
	e.p("func (b *closureBody) rebound(this *php.Object, scope string) *php.Object {")
	e.p("\to := php.NewObject(\"Closure\", allocObjectID())")
	e.p("\tbound := b.ownBound()")
	e.p("\tcalled := scope")
	e.p("\tif this != nil {")
	e.p("\t\tcalled = this.ClassName")
	e.p("\t}")
	e.p("\to.Internal = &closureBody{fn: b.fn, bound: bound, order: b.order, meta: b.meta, this: this, scope: scope, called: called}")
	e.p("\treturn o")
	e.p("}")
	e.p("")
	e.p("// closureFrameName is how a trace names a closure: its own")
	e.p("// `{closure:FILE:LINE}`, prefixed with the class it carries. A bound")
	e.p("// receiver gives `Host->{closure:...}`; a scope with no receiver -- a")
	e.p("// closure made inside a static method -- gives `Host::{closure:...}`.")
	e.p("func closureFrameName(b *closureBody, this *php.Object, scope string) string {")
	e.p("\tname := \"{closure}\"")
	e.p("\tif b != nil && b.meta.name != \"\" {")
	e.p("\t\tname = b.meta.name")
	e.p("\t}")
	e.p("\tswitch {")
	e.p("\tcase this != nil && scope != \"\":")
	e.p("\t\t// **The scope names the frame**, the receiver only the arrow: a")
	e.p("\t\t// closure made in A's method and called on a B is `A->{closure}`.")
	e.p("\t\treturn php.DisplayName(scope) + \"->\" + name")
	e.p("\tcase this != nil:")
	e.p("\t\treturn php.DisplayName(this.ClassName) + \"->\" + name")
	e.p("\tcase scope != \"\":")
	e.p("\t\treturn php.DisplayName(scope) + \"::\" + name")
	e.p("\t}")
	e.p("\treturn name")
	e.p("}")
	e.p("")
	e.p("// closureStatic is `static` inside a closure body: the receiver's class,")
	e.p("// or with none the called class its frame carries (closureBody.called).")
	e.p("func closureStatic(ctx *php.Ctx, this *php.Object) string {")
	e.p("\tif this != nil {")
	e.p("\t\treturn this.ClassName")
	e.p("\t}")
	e.p("\tif st := ctx.Stack(); len(st) > 0 {")
	e.p("\t\treturn st[len(st)-1].LSB")
	e.p("\t}")
	e.p("\treturn \"\"")
	e.p("}")
	e.p("")
	e.p("// invokeClosure runs a closure body under a chosen receiver and scope,")
	e.p("// with the frame `callValue` pushes for the same call written `$f()`.")
	e.p("func invokeClosure(ctx *php.Ctx, b *closureBody, this *php.Object, scope string, args []php.Value) (php.Value, error) {")
	e.p("\t// A closure made from something already named -- `throws(...)` --")
	e.p("\t// is no frame of its own: the call it makes pushes the named")
	e.p("\t// function's, and a trace shows that once (closure_064).")
	e.p("\tif b.meta.function != \"\" {")
	e.p("\t\treturn b.fn(ctx, this, b.bound, scope, args)")
	e.p("\t}")
	e.p("\tfile, line := ctx.Location()")
	e.p("\t// **The closure's own name**, which is what the engine puts in a")
	e.p("\t// trace: `{closure:FILE:LINE}`, prefixed with the class when the")
	e.p("\t// closure carries one -- `Host->{closure:Host::make():2}` for a bound")
	e.p("\t// receiver and `Host::{closure:...}` for a scope without one.")
	e.p("\tctx.PushCall(php.StackFrame{Function: closureFrameName(b, this, scope), File: file, Line: line, Args: args, This: this, LSB: b.called})")
	e.p("\tdefer ctx.PopCall()")
	e.p("\treturn b.fn(ctx, this, b.bound, scope, args)")
	e.p("}")
	e.p("")
	e.p("// closureBinding reads the `$newThis, $newScope` pair `bindTo` and")
	e.p("// `Closure::bind` share.")
	e.p("//")
	e.p("// An **omitted** scope keeps the closure's current one rather than")
	e.p("// clearing it, which is what makes `$f->bindTo($a)` still unable to read")
	e.p("// `$a`'s private property while `$f->bindTo($a, A::class)` can. The scope")
	e.p("// may be given as a class name or as an object to take the class from.")
	e.p("//")
	e.p("// **The declared types are `?object` and `object|string|null`**, checked")
	e.p("// in that order and numbered from `first` -- `Closure::bind()` counts the")
	e.p("// closure itself -- and a scalar scope is converted to its string, which")
	e.p("// then names no class (closure_040).")
	e.p("func closureBinding(ctx *php.Ctx, b *closureBody, args []php.Value, function string, first int) (*php.Object, string, error) {")
	e.p("\tvar this *php.Object")
	e.p("\tif len(args) > 0 {")
	e.p("\t\tswitch tv := args[0].Deref(); tv.Kind() {")
	e.p("\t\tcase php.KindObject:")
	e.p("\t\t\tthis = tv.Object()")
	e.p("\t\tcase php.KindNull, php.KindUndef:")
	e.p("\t\tdefault:")
	e.p("\t\t\treturn nil, \"\", php.RaiseAt(ctx, \"TypeError\", \"%%s(): Argument #%%d ($newThis) must be of type ?object, %%s given\", function, first, php.ValueName(tv))")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tscope := b.scope")
	e.p("\tif len(args) > 1 {")
	e.p("\t\tsv := args[1].Deref()")
	e.p("\t\tswitch sv.Kind() {")
	e.p("\t\tcase php.KindInt, php.KindFloat, php.KindTrue, php.KindFalse:")
	e.p("\t\t\tstr, err := php.ToString(ctx, sv)")
	e.p("\t\t\tif err != nil {")
	e.p("\t\t\t\treturn nil, \"\", err")
	e.p("\t\t\t}")
	e.p("\t\t\tsv = str")
	e.p("\t\tcase php.KindObject, php.KindString, php.KindNull:")
	e.p("\t\tdefault:")
	e.p("\t\t\treturn nil, \"\", php.RaiseAt(ctx, \"TypeError\", \"%%s(): Argument #%%d ($newScope) must be of type object|string|null, %%s given\", function, first+1, php.ValueName(sv))")
	e.p("\t\t}")
	e.p("\t\tswitch sv.Kind() {")
	e.p("\t\tcase php.KindObject:")
	e.p("\t\t\tscope = sv.Object().ClassName")
	e.p("\t\tcase php.KindString:")
	e.p("\t\t\t// `\"static\"` is the documented spelling for *keep*, not for")
	e.p("\t\t\t// a class called static.")
	e.p("\t\t\tif !strings.EqualFold(sv.String(), \"static\") {")
	e.p("\t\t\t\tscope = sv.String()")
	e.p("\t\t\t}")
	e.p("\t\tcase php.KindNull:")
	e.p("\t\t\t// An explicit null is *no* scope, not keep: a scoped")
	e.p("\t\t\t// closure rebound with `bindTo(null, null)` loses access to")
	e.p("\t\t\t// its class's private statics.")
	e.p("\t\t\tscope = \"\"")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\t// **An object bound with no scope gets `Closure` as its scope** -- the")
	e.p("\t// engine's dummy, so a frame reads `Closure->{closure}()` and the")
	e.p("\t// object's privates stay out of reach.")
	e.p("\tif this != nil && scope == \"\" {")
	e.p("\t\tscope = \"Closure\"")
	e.p("\t}")
	e.p("\treturn this, scope, nil")
	e.p("}")
	e.p("")
	e.p("// closureFromCallable wraps any callable as a Closure. The body defers to")
	e.p("// `callValue`, so every callable shape it knows works here without a")
	e.p("// second dispatcher -- and `var_dump` of the result shows `function`")
	e.p("// rather than a name/file/line, which is what the engine shows for one.")
	e.p("func closureFromCallable(callable php.Value) php.Value {")
	e.p("\tinner := callable.Deref().Copy()")
	e.p("\t// **An invokable object is its `__invoke` method** on that object")
	e.p("\t// (probed: the closure dumps `function` Foo::__invoke and `this`).")
	e.p("\tif o := inner.Object(); o != nil {")
	e.p("\t\tif _, isClosure := o.Internal.(*closureBody); !isClosure {")
	e.p("\t\t\tpair := php.NewArray()")
	e.p("\t\t\tpair.Append(inner)")
	e.p("\t\t\tpair.Append(php.String(\"__invoke\"))")
	e.p("\t\t\tinner = php.Arr(pair)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tfn := func(ctx *php.Ctx, this *php.Object, bound map[string]*php.Value, scope string, args []php.Value) (php.Value, error) {")
	e.p("\t\t// A method reached with the scope the closure was made in.")
	e.p("\t\tif a := inner.Array(); a != nil && scope != \"\" {")
	e.p("\t\t\trecv, _ := a.Get(php.IntKey(0))")
	e.p("\t\t\tm, _ := a.Get(php.IntKey(1))")
	e.p("\t\t\tif recv.Deref().Kind() == php.KindObject {")
	e.p("\t\t\t\treturn callMethodFrom(ctx, recv.Deref(), m.Deref().String(), args, scope)")
	e.p("\t\t\t}")
	e.p("\t\t\treturn callStaticFrom(ctx, recv.Deref().String(), m.Deref().String(), nil, args, scope)")
	e.p("\t\t}")
	e.p("\t\t// `Class::m` resolved from a keyword keeps the `$this` it was")
	e.p("\t\t// made with: `'parent::m'` is the parent's method on this object.")
	e.p("\t\tif class, method, ok := strings.Cut(inner.String(), \"::\"); ok && inner.Kind() == php.KindString && scope != \"\" {")
	e.p("\t\t\treturn callStaticFrom(ctx, class, method, this, args, scope)")
	e.p("\t\t}")
	e.p("\t\treturn callValue(ctx, inner, args)")
	e.p("\t}")
	e.p("\to := php.NewObject(\"Closure\", allocObjectID())")
	e.p("\tnamed := callableDisplayName(inner)")
	e.p("\tbody := &closureBody{fn: fn, bound: map[string]*php.Value{},")
	e.p("\t\tmeta: closureMeta{name: named, function: named, params: namedCallableParams[strings.ToLower(named)]}}")
	e.p("\t// **An array callable carries its receiver**, and `var_dump` shows")
	e.p("\t// it under `this`. `$o->m(...)` sets this on the way back out; a")
	e.p("\t// `[$o, \"m\"]` reaching here directly had nobody to set it.")
	e.p("\tif a := inner.Array(); a != nil {")
	e.p("\t\tif target, ok := a.Get(php.IntKey(0)); ok && target.Deref().Kind() == php.KindObject {")
	e.p("\t\t\tbody.this = target.Deref().Object()")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\to.Internal = body")
	e.p("\treturn php.Obj(o)")
	e.p("}")
	e.p("")
	e.p("// fromCallable is Closure::fromCallable once the callable has passed")
	e.p("// the callback check.")
	e.p("//")
	e.p("// **A method callable keeps the scope it was made in**, as")
	e.p("// `$this->m(...)` does: `[$this, 'privateMethod']` from inside the")
	e.p("// class is callable wherever the closure goes. A keyword class --")
	e.p("// `'parent::m'`, `'self::m'` -- is resolved here, where it deprecates")
	e.p("// and where `$this` and the class are known (closure_from_callable_basic).")
	e.p("func fromCallable(ctx *php.Ctx, arg php.Value) (php.Value, error) {")
	e.p("\t// **A Closure is returned as it is** -- the same object, not a")
	e.p("\t// wrapper around it (probed: `fromCallable($f) === $f`). Wrapping")
	e.p("\t// it took a fresh object number and lost the closure's own")
	e.p("\t// reflection (closure_from_callable_reflection).")
	e.p("\tif o := arg.Object(); o != nil {")
	e.p("\t\tif _, isClosure := o.Internal.(*closureBody); isClosure {")
	e.p("\t\t\treturn arg, nil")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tstack := ctx.Stack()")
	e.p("\tif n := len(stack); n > 0 && strings.HasPrefix(strings.ToLower(stack[n-1].Function), \"closure::\") {")
	e.p("\t\tstack = stack[:n-1]")
	e.p("\t}")
	e.p("\tscope := \"\"")
	e.p("\tfor i := len(stack) - 1; i >= 0 && scope == \"\"; i-- {")
	e.p("		fn := stack[i].Function")
	e.p("		if at := strings.Index(fn, \"->\"); at > 0 {")
	e.p("\t\t\tscope = fn[:at]")
	e.p("\t\t} else if at := strings.Index(fn, \"::\"); at > 0 {")
	e.p("\t\t\tscope = fn[:at]")
	e.p("\t\t}")
	e.p("\t}")
