	e.p("// callableDisplayName is what `var_dump` shows under `function` for a")
	e.p("// closure made from a callable. An array callable is `C::m`, which is")
	e.p("// not what stringifying the array gives.")
	e.p("func callableDisplayName(v php.Value) string {")
	e.p("	if a := v.Deref().Array(); a != nil {")
	e.p("		target, _ := a.Get(php.IntKey(0))")
	e.p("		method, _ := a.Get(php.IntKey(1))")
	e.p("		class := target.Deref().String()")
	e.p("		if target.Deref().Kind() == php.KindObject {")
	e.p("			class = target.Deref().Object().ClassName")
	e.p("\t\t}")
