	e.p("// closureFromCall is `$o->m(...)` and `C::s(...)`. Both become the")
	e.p("// two-element callable they are equivalent to, so one dispatcher")
	e.p("// answers them and the receiver-versus-class-name question is the one")
	e.p("// `callValue` already asks.")
	e.p("//")
	e.p("// The debug info differs from a literal closure's: `var_dump` shows")
	e.p("// `function` as `C::m` and, for the instance form, the receiver under")
	e.p("// `this`. Measured.")
	e.p("//")
	e.p("// **The scope it was made in comes with it**: `$this->hidden(...)`")
	e.p("// inside the class reaches the private method wherever the closure is")
	e.p("// called from, and no frame of the closure's own carries that scope.")
	e.p("func closureFromCall(target php.Value, method, scope string) php.Value {")
	e.p("\t// **A closure's own `__invoke(...)` is the closure itself** (probed:")
	e.p("\t// the same object number).")
	e.p("\tif o := target.Deref().Object(); o != nil && strings.EqualFold(method, \"__invoke\") {")
	e.p("\t\tif _, isClosure := o.Internal.(*closureBody); isClosure {")
	e.p("\t\t\treturn target.Deref()")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\ta := php.NewArray()")
	e.p("\ta.Append(target)")
	e.p("\ta.Append(php.String(method))")
	e.p("\tv := closureFromCallable(php.Arr(a))")
	e.p("\tb, ok := v.Object().Internal.(*closureBody)")
	e.p("\tif !ok {")
	e.p("\t\treturn v")
	e.p("\t}")
	e.p("\tclass := target.Deref().String()")
	e.p("\tif target.Deref().Kind() == php.KindObject {")
	e.p("\t\tclass = target.Deref().Object().ClassName")
	e.p("\t\tb.this = target.Deref().Object()")
	e.p("\t}")
	e.p("\tb.meta.name = class + \"::\" + method")
	e.p("\tb.meta.function = b.meta.name")
	e.p("\tb.scope = scope")
	e.p("\tb.meta.params = namedCallableParams[strings.ToLower(b.meta.name)]")
	e.p("\tif _, _, _, found := methodOwnerOf(realClass(class), strings.ToLower(method)); !found {")
	e.p("\t\tif _, _, abstract := abstractMethod(realClass(class), strings.ToLower(method)); !abstract {")
	e.p("\t\t\tb.meta.trampoline = hasCompiledMethod(class, \"__call\") || hasCompiledMethod(class, \"__callstatic\")")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn v")
	e.p("}")
	e.p("")
	e.p("// fccOfValue is `$f(...)` with the callable in a variable (probed): a")
	e.p("// Closure is itself, a string or array names what closureFromCallable")
	e.p("// and closureFromCall already build, and a function that does not exist")
	e.p("// is refused now, not when the closure is called.")
	e.p("func fccOfValue(ctx *php.Ctx, v php.Value, scope string) (php.Value, error) {")
	e.p("\td := v.Deref()")
	e.p("\tswitch d.Kind() {")
	e.p("\tcase php.KindObject:")
	e.p("\t\tif _, ok := d.Object().Internal.(*closureBody); ok {")
	e.p("\t\t\treturn d, nil")
	e.p("\t\t}")
