	e.p("\tcase php.KindArray:")
	e.p("\t\tt, okt := d.Array().Get(php.IntKey(0))")
	e.p("\t\tm, okm := d.Array().Get(php.IntKey(1))")
	e.p("\t\tif okt && okm {")
	e.p("\t\t\treturn fccOfMethod(ctx, t.Deref(), m.Deref(), scope)")
	e.p("\t\t}")
	e.p("\tcase php.KindString:")
	e.p("\t\tif class, method, ok := strings.Cut(d.String(), \"::\"); ok {")
	e.p("\t\t\treturn fccOfMethod(ctx, php.String(class), php.String(method), scope)")
	e.p("\t\t}")
	e.p("\t\tname := strings.ToLower(strings.TrimPrefix(d.String(), \"\\\\\"))")
	e.p("\t\tif _, own := userFuncs[name]; !own {")
	e.p("\t\t\tif _, lib := php.LookupBuiltin(name); !lib && !engineFuncs[name] {")
	e.p("\t\t\t\treturn php.Value{}, php.ThrowUndefinedFunction(d.String())")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\treturn closureFromCallable(d), nil")
	e.p("\t}")
	e.p("\treturn php.Value{}, php.RaiseAt(ctx, \"Error\", \"Value of type %%s is not callable\", php.ValueName(d))")
	e.p("}")
	e.p("")
	e.p("// fccOfMethod is `$o->$m(...)`: the method must exist -- or `__call`")
	e.p("// answer for it -- when the closure is made (probed: `Call to undefined")
	e.p("// method O::bar()`).")
	e.p("func fccOfMethod(ctx *php.Ctx, target, method php.Value, scope string) (php.Value, error) {")
	e.p("\tname := method.Deref().String()")
	e.p("\tclass := target.Deref().String()")
	e.p("\tif target.Deref().Kind() == php.KindObject {")
	e.p("\t\tclass = target.Deref().Object().ClassName")
