	e.p("\t// A Closure's `__invoke` is in no table (first_class_callable_009).")
	e.p("\tisClosure := false")
	e.p("\tif o := target.Deref().Object(); o != nil {")
	e.p("\t\t_, isClosure = o.Internal.(*closureBody)")
	e.p("\t}")
	e.p("\tif !(isClosure && strings.EqualFold(name, \"__invoke\")) && !hasMethod(class, strings.ToLower(name)) && !hasMethod(class, \"__call\") && !hasMethod(class, \"__callstatic\") {")
	e.p("\t\treturn php.Value{}, php.ThrowUndefinedMethod(class, name)")
	e.p("\t}")
	e.p("\t// **Reachable from where the closure is made**, as the call would be:")
	e.p("\t// a private method from outside is `Call to private method ... from")
	e.p("\t// global scope`, and an instance method named by class with no")
	e.p("\t// compatible `$this` is `Non-static method ... cannot be called")
	e.p("\t// statically` (first_class_callable_errors).")
	e.p("\tlower := strings.ToLower(name)")
	e.p("\tif d, restricted := methodVisibility[realClassOr(class)][lower]; restricted && !methodReachable(d, scope) &&")
	e.p("\t\t!hasMethod(class, \"__call\") && !hasMethod(class, \"__callstatic\") {")
	e.p("\t\treturn php.Value{}, php.ThrowInaccessibleMethod(ctx, d[0], name, d[1], scope)")
	e.p("\t}")
	e.p("\tif target.Deref().Kind() == php.KindString {")
	e.p("\t\tif owner, spelled, isStatic, known := methodOwnerOf(realClassOr(class), lower); known && !isStatic && callerThis(ctx, class) == nil {")
	e.p("\t\t\treturn php.Value{}, php.ThrowNonStaticCall(ctx, owner, spelled)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tif err := dateMethodGap(target.Deref(), name); err != nil {")
	e.p("\t\treturn php.Value{}, err")
	e.p("\t}")
	e.p("\treturn closureFromCall(target.Deref(), name, scope), nil")
