	e.p("// bindLexical captures one `use` variable.")
	e.p("//")
	e.p("// `use ($n)` captures the **value at capture time**; `use (&$n)` shares")
	e.p("// the enclosing box, so the closure's writes are visible outside and")
	e.p("// later writes outside are visible inside. The engine distinguishes them")
	e.p("// in the opcode's extended_value, and treating both as a copy makes the")
	e.p("// by-reference form silently do nothing.")
	e.p("func bindLexical(ctx *php.Ctx, o *php.Object, name string, slot *php.Value, byRef, implicit bool) {")
	e.p("\tb, ok := o.Internal.(*closureBody)")
	e.p("\tif !ok {")
	e.p("\t\treturn")
	e.p("\t}")
	e.p("\tif byRef {")
	e.p("\t\tr, isRef := slot.RefOf()")
	e.p("\t\tif !isRef {")
	e.p("\t\t\tr = php.NewRef(slot.Deref())")
	e.p("\t\t\t*slot = php.MakeRef(r)")
	e.p("\t\t}")
	e.p("\t\tr.AddBinding()")
	e.p("\t\t// `use (&$x)` is an **explicit &**, which is what var_dump's")
	e.p("\t\t// marker is about -- php2go boxes slots for its own reasons too,")
	e.p("\t\t// and those must not print one. `AddBinding` alone is diagnostic")
	e.p("\t\t// accounting for debug_zval_dump; `Shared` is the marker, and")
	e.p("\t\t// without it the capture printed `int(2)` where the engine prints")
	e.p("\t\t// `&int(2)`.")
	e.p("\t\tshared := php.Shared(php.MakeRef(r))")
	e.p("\t\tb.remember(name)")
	e.p("\t\tb.bound[name] = &shared")
	e.p("\t\treturn")
	e.p("\t}")
	e.p("\t// **Captured by value, an undefined variable warns** at the")
	e.p("\t// closure's creation and is captured as null (closure_027).")
	e.p("\tb.remember(name)")
	e.p("\tcaptured := slot.Deref().Copy()")
	e.p("\t// An arrow function's **implicit** capture of one says nothing and")
	e.p("\t// stays undefined, so the body's read is what warns.")
	e.p("\tif captured.IsUndef() && !implicit {")
	e.p("\t\tctx.WarnUndefinedVariable(name)")
	e.p("\t\tcaptured = php.Null()")
	e.p("\t}")
	e.p("\tb.bound[name] = &captured")
	e.p("}")
	e.p("")
	e.p("// ownBound is the map a **copy** of the closure starts with: the")
	e.p("// captures shared, and its static variables copied. Measured: a")
	e.p("// closure from `bindTo` or `clone` carries on from the original's")
	e.p("// statics, and from then on the two count separately.")
	e.p("func (b *closureBody) ownBound() map[string]*php.Value {")
	e.p("\tbound := make(map[string]*php.Value, len(b.bound))")
	e.p("\tfor k, v := range b.bound {")
	e.p("\t\tif strings.HasPrefix(k, %q) {", closureStaticPrefix)
	e.p("\t\t\tc := v.Deref().Copy()")
	e.p("\t\t\tv = &c")
	e.p("\t\t}")
	e.p("\t\tbound[k] = v")
	e.p("\t}")
	e.p("\treturn bound")
	e.p("}")
	e.p("")
	e.p("func (b *closureBody) remember(name string) {")
	e.p("\tif _, seen := b.bound[name]; !seen {")
	e.p("\t\tb.order = append(b.order, name)")
	e.p("\t}")
	e.p("}")
