	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\tif !builtin {")
	e.p("\t\t\t\tctx.Warn(\"stream_wrapper_restore(): %%s:// never existed, nothing to restore\", shown)")
	e.p("\t\t\t\treturn php.Bool(false), ctx.TakePendingError()")
	e.p("\t\t\t}")
	e.p("\t\t\tif held, found := ctx.StreamWrapperFor(protocol); found && held.Builtin {")
	e.p("\t\t\t\tctx.Notice(\"stream_wrapper_restore(): %%s:// was never changed, nothing to restore\", shown)")
	e.p("\t\t\t\treturn php.Bool(true), ctx.TakePendingError()")
	e.p("\t\t\t}")
	e.p("\t\t\tctx.UnregisterStreamWrapper(protocol)")
	e.p("\t\t\tctx.RegisterStreamWrapper(protocol, &php.StreamWrapper{Builtin: true})")
	e.p("\t\t\treturn php.Bool(true), nil")
	e.p("\t\t},")
	e.p("\t\t\"php2go\\\\internal\\\\stream_wrapper_registry\": func(ctx *php.Ctx, args []php.Value) (php.Value, error) {")
	e.p("\t\t\tif php.Arg(args, 0).Deref().String() != \"list\" {")
	e.p("\t\t\t\treturn php.Value{}, php.RaiseAt(ctx, \"Error\", \"%%s\", \"php2go internal stream_wrapper_registry received an invalid operation\")")
	e.p("\t\t\t}")
	e.p("\t\t\tout := php.NewArray()")
	e.p("\t\t\tfor _, scheme := range ctx.StreamWrapperSchemes() {")
	e.p("\t\t\t\tout.Append(php.String(scheme))")
	e.p("\t\t\t}")
	e.p("\t\t\treturn php.Arr(out), nil")
	e.p("\t\t},")
