	// the *program's* to do -- the interpreter shares that package and must not
	// call os.Exit out from under its own caller.
	for _, name := range []string{"exit", "die"} {
		e.p("\t%q: func(ctx *php.Ctx, args []php.Value) (php.Value, error) {", name)
		e.p("\t\treturn phpExit(ctx, args, %t)", e.strict)
		e.p("\t},")
	}
	e.p("\t\t\"get_class\": func(ctx *php.Ctx, args []php.Value) (php.Value, error) {")
	e.p("\t\t\tif v := php.Arg(args, 0); v.Kind() == php.KindObject {")
