	e.p("\t\t\t\t\t\tif found == \"\" {")
	e.p("\t\t\t\t\t\t\treturn php.Value{}, php.RaiseAt(ctx, \"TypeError\", \"get_parent_class(): Argument #1 ($object_or_class) must be an object or a valid class name, %%s given\", php.TypeName(v))")
	e.p("\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t\tclass = found")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\tdefault:")
	e.p("\t\t\t\t\treturn php.Value{}, php.RaiseAt(ctx, \"TypeError\", \"get_parent_class(): Argument #1 ($object_or_class) must be an object or a valid class name, %%s given\", php.TypeName(v))")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\tif r := realClass(class); r != \"\" {")
