	e.p("\t\t\treturn php.Bool(false), nil")
	e.p("\t\t},")
	e.p("\t\t// **A conditionally declared function is not declared until its")
	e.p("\t\t// DECLARE_FUNCTION has run**, which is the whole reason this cannot")
	e.p("\t\t// be answered from a compile-time table: `if (false) { function f(){} }`")
	e.p("\t\t// is false, and the same source inside `if (true)` is true only after")
	e.p("\t\t// the branch. `userFuncs` holds both kinds and is filled at start-up")
	e.p("\t\t// for the unconditional ones, so it is the one table to ask.")
	e.p("\t\t//")
	e.p("\t\t// A library function counts too -- measured: `function_exists(\"strlen\")`")
	e.p("\t\t// and `function_exists(\"printf\")` are both true -- and the empty name")
	e.p("\t\t// is false rather than an error.")
	e.p("\t\t\"function_exists\": func(ctx *php.Ctx, args []php.Value) (php.Value, error) {")
	e.p("\t\t\t// One leading backslash is the fully-qualified spelling.")
	e.p("\t\t\tname := strings.ToLower(strings.TrimPrefix(php.Arg(args, 0).String(), \"\\\\\"))")
	e.p("\t\t\tif name == \"\" {")
	e.p("\t\t\t\treturn php.Bool(false), nil")
	e.p("\t\t\t}")
	e.p("\t\t\tif _, ok := userFuncs[name]; ok {")
	e.p("\t\t\t\treturn php.Bool(true), nil")
	e.p("\t\t\t}")
	e.p("\t\t\tif localFuncNames[name] {")
	e.p("\t\t\t\treturn php.Bool(true), nil")
	e.p("\t\t\t}")
	e.p("\t\t\tif _, ok := php.LookupBuiltin(name); ok {")
	e.p("\t\t\t\treturn php.Bool(true), nil")
	e.p("\t\t\t}")
	e.p("\t\t\t// **The engine's list is the last word**, and it is a wider set")
	e.p("\t\t\t// than what this program can call: `strlen` is compiled to an")
	e.p("\t\t\t// opcode and so is in no library table at all, and `array_map` is")
	e.p("\t\t\t// a gap php2go reports at the call. PHP says both exist, and")
	e.p("\t\t\t// existing is the question being asked.")
	e.p("\t\t\treturn php.Bool(engineFuncs[name]), nil")
	e.p("\t\t},")
	e.p("\t\t// The engine's functions in its order, then the program's in the")
	e.p("\t\t// order they were declared, lowercased (probed). The engine's list")
	e.p("\t\t// is emitted only for a program that names this function; reached")
	e.p("\t\t// any other way it is a gap.")
	e.p("\t\t\"get_defined_functions\": func(ctx *php.Ctx, args []php.Value) (php.Value, error) {")
	e.p("\t\t\tif engineFuncOrder == nil {")
	e.p("\t\t\t\treturn php.Value{}, php.Unsupported(\"get_defined_functions reached dynamically\")")
	e.p("\t\t\t}")
	e.p("\t\t\tif len(args) > 0 && !args[0].Deref().Bool() {")
	e.p("\t\t\t\tctx.Deprecated(\"get_defined_functions(): Setting $exclude_disabled to false has no effect\")")
	e.p("\t\t\t\tif err := ctx.TakePendingError(); err != nil {")
	e.p("\t\t\t\t\treturn php.Value{}, err")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\tinternal, user := php.NewArray(), php.NewArray()")
	e.p("\t\t\tfor _, n := range engineFuncOrder {")
	e.p("\t\t\t\tinternal.Append(php.String(n))")
	e.p("\t\t\t}")
	e.p("\t\t\tfor _, n := range userFuncOrder {")
	e.p("\t\t\t\tuser.Append(php.String(n))")
	e.p("\t\t\t}")
	e.p("\t\t\tout := php.NewArray()")
	e.p("\t\t\tout.Set(php.StringKey(\"internal\"), php.Arr(internal))")
	e.p("\t\t\tout.Set(php.StringKey(\"user\"), php.Arr(user))")
	e.p("\t\t\treturn php.Arr(out), nil")
