	e.p("\t\t},")
	e.p("\t\t\"gc_enabled\": func(ctx *php.Ctx, args []php.Value) (php.Value, error) {")
	e.p("\t\t\tv, held := ctx.IniRead(\"zend.enable_gc\")")
