	e.p("\t\t},")
	e.p("\t\t// A shutdown function is a **callback with its own arguments**, run")
	e.p("\t\t// after the body in registration order -- including after an uncaught")
	e.p("\t\t// exception's fatal message, and including on `exit`.")
	e.p("\t\t// A tick function, with the arguments to call it with every time")
	e.p("\t\t// (declare_007).")
	e.p("\t\t\"register_tick_function\": func(ctx *php.Ctx, args []php.Value) (php.Value, error) {")
	e.p("\t\t\tif err := ctx.CheckCallable(\"register_tick_function\", 1, \"callback\", php.Arg(args, 0)); err != nil {")
	e.p("\t\t\t\treturn php.Value{}, err")
	e.p("\t\t\t}")
	e.p("\t\t\tbound := make([]php.Value, 0, len(args))")
	e.p("\t\t\tfor _, a := range args[1:] {")
	e.p("\t\t\t\tbound = append(bound, a.Deref().Copy())")
	e.p("\t\t\t}")
	e.p("\t\t\ttickFuncs = append(tickFuncs, tickFunc{args[0].Deref(), bound})")
	e.p("\t\t\treturn php.Bool(true), nil")
	e.p("\t\t},")
	e.p("\t\t\"unregister_tick_function\": func(ctx *php.Ctx, args []php.Value) (php.Value, error) {")
	e.p("\t\t\tcb := php.Arg(args, 0).Deref()")
	e.p("\t\t\tkept := tickFuncs[:0]")
	e.p("\t\t\tfor _, t := range tickFuncs {")
