	e.p("\t\t},")
	e.p("\t\t\"register_shutdown_function\": func(ctx *php.Ctx, args []php.Value) (php.Value, error) {")
	e.p("\t\t\tif len(args) == 0 {")
	e.p("\t\t\t\treturn php.Null(), nil")
