	e.p("\t\t\"is_callable\": func(ctx *php.Ctx, args []php.Value) (php.Value, error) {")
	e.p("\t\t\tif v := php.Arg(args, 0).Deref(); v.Kind() == php.KindArray && v.Array().Len() == 2 && !(len(args) > 1 && args[1].Deref().Bool()) {")
	e.p("\t\t\t\tt, _ := v.Array().Get(php.IntKey(0))")
	e.p("\t\t\t\tm, _ := v.Array().Get(php.IntKey(1))")
	e.p("\t\t\t\tif k := t.Deref().Kind(); (k == php.KindObject || k == php.KindString) && m.Deref().Kind() == php.KindString {")
	e.p("\t\t\t\t\tif owner, _, resolved, _ := resolveQualifiedCallable(ctx, t.Deref(), m.Deref().String()); resolved {")
	e.p("\t\t\t\t\t\tctx.Deprecated(`Callables of the form [\"%%s\", \"%%s\"] are deprecated`, php.DisplayName(owner), m.Deref().String())")
