	e.p("\t\t\tif lower := strings.ToLower(strings.TrimPrefix(name, \"\\\\\")); target == \"\" && engineClassKind[lower] {")
	e.p("\t\t\t\ttarget = engineSpelling(name)")
	e.p("\t\t\t}")
	e.p("\t\t\tif target == \"\" {")
	e.p("\t\t\t\t// A **warning** and false, not an Error: measured.")
	e.p("\t\t\t\tctx.Warn(\"Class \\\"%%s\\\" not found\", php.DisplayName(php.Arg(args, 0).String()))")
	e.p("\t\t\t\treturn php.Bool(false), nil")
