	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\t// **A name already taken is a warning and false**, and the")
	e.p("\t\t\t// message is odd in a way the engine settled: the kind and")
	e.p("\t\t\t// the `previously declared` site are the *aliased* class's,")
	e.p("\t\t\t// the name is the alias as written (class_alias_004, _010).")
	e.p("\t\t\tif lower := strings.ToLower(strings.TrimPrefix(alias, \"\\\\\")); declaredClasses[lower] || engineClassKind[lower] || engineInterfaceKind[lower] {")
	e.p("\t\t\t\td, own := classDecl[strings.ToLower(target)]")
	e.p("\t\t\t\tif !own {")
	e.p("\t\t\t\t\treturn php.Value{}, php.Unsupported(\"class_alias of engine class %%s onto a taken name\", target)")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\tctx.Warn(\"Cannot redeclare %%s %%s (previously declared in %%s:%%d)\", d.kind, alias, srcFile, d.line)")
	e.p("\t\t\t\treturn php.Bool(false), nil")
	e.p("\t\t\t}")
	e.p("\t\t\tif _, again := classAliases[strings.ToLower(alias)]; !again {")
	e.p("\t\t\t\taliasOrder = append(aliasOrder, strings.ToLower(alias))")
	e.p("\t\t\t}")
	e.p("\t\t\tclassAliases[strings.ToLower(alias)] = target")
	e.p("\t\t\tdeclaredClasses[strings.ToLower(alias)] = true")
	e.p("\t\t\treturn php.Bool(true), nil")
	e.p("\t\t},")
	e.p("\t\t// is_a and is_subclass_of differ in two ways, as runtime/interp's")
	e.p("\t\t// ancestryTest has them: whether a string subject is taken by")
	e.p("\t\t// default -- and autoloaded -- and whether the class itself counts.")
	e.p("\t\t\"is_a\": func(ctx *php.Ctx, args []php.Value) (php.Value, error) {")
	e.p("\t\t\treturn ancestryTest(ctx, args, false)")
	e.p("\t\t},")
	e.p("\t\t\"is_subclass_of\": func(ctx *php.Ctx, args []php.Value) (php.Value, error) {")
	e.p("\t\t\treturn ancestryTest(ctx, args, true)")
	e.p("\t\t},")
	e.p("\t\t\"method_exists\": func(ctx *php.Ctx, args []php.Value) (php.Value, error) {")
	e.p("\t\t\t// Asked of an incomplete object, its get_method handler throws.")
	e.p("\t\t\tif o := php.Arg(args, 0).Deref().Object(); php.IsIncomplete(o) {")
	e.p("\t\t\t\treturn php.Value{}, php.IncompleteCallError(ctx, o)")
	e.p("\t\t\t}")
	e.p("\t\t\tname := php.Arg(args, 1).String()")
	e.p("\t\t\t// A Closure has `__invoke`, which no table here lists -- asked")
	e.p("\t\t\t// of a closure or of the class by name.")
	e.p("\t\t\tif strings.EqualFold(name, \"__invoke\") {")
	e.p("\t\t\t\tswitch o := php.Arg(args, 0).Deref(); o.Kind() {")
	e.p("\t\t\t\tcase php.KindObject:")
	e.p("\t\t\t\t\tif _, isClosure := o.Object().Internal.(*closureBody); isClosure {")
	e.p("\t\t\t\t\t\treturn php.Bool(true), nil")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\tcase php.KindString:")
	e.p("\t\t\t\t\tif strings.EqualFold(resolveAlias(o.String()), \"Closure\") {")
	e.p("\t\t\t\t\t\treturn php.Bool(true), nil")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\tstart := className(php.Arg(args, 0))")
	e.p("\t\t\t// **An ancestor's private method counts for an object and not")
	e.p("\t\t\t// for a class name.** Measured, from any scope: with `P` declaring")
	e.p("\t\t\t// a private `pi` and `C extends P`, `method_exists(new C, \"pi\")`")
	e.p("\t\t\t// is true and `method_exists(\"C\", \"pi\")` false, static or not.")
	e.p("\t\t\tbyName := php.Arg(args, 0).Deref().Kind() != php.KindObject")
	e.p("\t\t\tfor c := start; c != \"\"; c = parentOf[c] {")
	e.p("\t\t\t\tfor m, info := range classMethods[c] {")
	e.p("\t\t\t\t\tif byName && c != start && info.visibility == \"private\" {")
	e.p("\t\t\t\t\t\tcontinue")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\t\tif strings.EqualFold(m, name) {")
	e.p("\t\t\t\t\t\treturn php.Bool(true), nil")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\t// An SPL iterator's own methods, all public, are in no")
	e.p("\t\t\t// compiled table.")
	e.p("\t\t\tif engineHasSplMethod(start, name) {")
	e.p("\t\t\t\treturn php.Bool(true), nil")
	e.p("\t\t\t}")
	e.p("\t\t\t// Generator's and Fiber's, likewise (probed: all public).")
	e.p("\t\t\tengineClass := start")
	e.p("\t\t\tif s := php.Arg(args, 0).Deref(); engineClass == \"\" && s.Kind() == php.KindString {")
	e.p("\t\t\t\tengineClass = strings.TrimPrefix(s.String(), `\\`)")
	e.p("\t\t\t}")
	e.p("\t\t\tif engineHasGeneratorMethod(engineClass, name) || engineHasFiberMethod(engineClass, name) ||")
	e.p("\t\t\t\tengineHasUserFilterMethod(engineClass, name) {")
	e.p("\t\t\t\treturn php.Bool(true), nil")
	e.p("\t\t\t}")
	e.p("\t\t\t// WeakMap's, WeakReference's and InternalIterator's (probed:")
	e.p("\t\t\t// all answer, private ones included, except that WeakMap")
	e.p("\t\t\t// declares no constructor). They answered false.")
	e.p("\t\t\tif engineHasWeakMethod(engineClass, name) && !(strings.EqualFold(engineClass, \"WeakMap\") && strings.EqualFold(name, \"__construct\")) {")
	e.p("\t\t\t\treturn php.Bool(true), nil")
	e.p("\t\t\t}")
	e.p("\t\t\t// Asked of an object, a dual iterator answers for the one it")
	e.p("\t\t\t// wraps too -- private methods included, as the engine's")
	e.p("\t\t\t// get_method finds them.")
	e.p("\t\t\tif subject := php.Arg(args, 0).Deref(); subject.Kind() == php.KindObject {")
	e.p("\t\t\t\tif inner, ok := splForwardTarget(subject.Object(), strings.ToLower(name)); ok && hasMethod(inner.Object().ClassName, strings.ToLower(name)) {")
	e.p("\t\t\t\t\treturn php.Bool(true), nil")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\t// A date class's own methods are the engine's, listed there.")
	e.p("\t\t\tif engineHasDateMethod(start, name) {")
	e.p("\t\t\t\treturn php.Bool(true), nil")
	e.p("\t\t\t}")
	e.p("\t\t\treturn php.Bool(false), nil")
	e.p("\t\t},")
	e.p("\t}")
	e.p("}")
	e.p("")
	e.p("func ancestryTest(ctx *php.Ctx, args []php.Value, strict bool) (php.Value, error) {")
	e.p("\tif len(args) < 2 {")
	e.p("\t\treturn php.Bool(false), nil")
	e.p("\t}")
	e.p("\tsubject := args[0].Deref()")
	e.p("\twanted := strings.TrimPrefix(args[1].Deref().String(), \"\\\\\")")
	e.p("\tallowString := strict")
	e.p("\tif len(args) > 2 {")
	e.p("\t\tallowString = args[2].Deref().Bool()")
	e.p("\t}")
	e.p("\tclass := \"\"")
	e.p("\tswitch {")
	e.p("\tcase subject.Kind() == php.KindObject:")
	e.p("\t\tclass = subject.Object().ClassName")
	e.p("\tcase subject.Kind() == php.KindString && allowString:")
	e.p("\t\tfound, err := knownClass(ctx, subject.String())")
	e.p("\t\tif err != nil {")
	e.p("\t\t\treturn php.Value{}, err")
	e.p("\t\t}")
	e.p("\t\tif found == \"\" {")
	e.p("\t\t\treturn php.Bool(false), nil")
	e.p("\t\t}")
	e.p("\t\tclass = found")
	e.p("\tdefault:")
	e.p("\t\treturn php.Bool(false), nil")
	e.p("\t}")
	e.p("\tsame := strings.EqualFold(resolveAlias(class), resolveAlias(wanted))")
	e.p("\tif strict && same {")
	e.p("\t\treturn php.Bool(false), nil")
	e.p("\t}")
	e.p("\tif subject.Kind() == php.KindObject {")
	e.p("\t\treturn php.Bool(instanceOf(subject, wanted)), nil")
	e.p("\t}")
	e.p("\treturn php.Bool(same || extendsClass(class, resolveAlias(wanted))), nil")
	e.p("}")
	e.p("")
	e.p("// visibleProperties is the property table an object presents to a scope:")
	e.p("// `get_object_vars` is this question asked from the calling scope, and a")
	e.p("// library function such as json_encode asks it with the empty one.")
	e.p("func visibleProperties(ctx *php.Ctx, o *php.Object, scope string) (*php.Array, error) {")
	e.p("\t// A hider shows **nothing** to anything that walks a table, which is")
	e.p("\t// the whole point of `SensitiveParameterValue`.")
	e.p("\tif o == nil || php.HidesProperties(o) {")
	e.p("\t\treturn php.NewArray(), nil")
	e.p("\t}")
	e.p("\t// **Reading a lazy object\"s properties initialises it.** Measured")
	e.p("\t// across fifteen operations: `get_object_vars`, `foreach`,")
	e.p("\t// `json_encode`, `serialize` and `==` all initialise, while")
	e.p("\t// `var_dump`, `print_r`, `(array)` and `count` deliberately do not --")
	e.p("\t// which is why this lives here, on the path that *reads values*, and")
	e.p("\t// not in `objectProperties`, which is what the dumps walk.")
	e.p("\tif o.Lazy != nil {")
	e.p("\t\tresolved, err := php.ResolveLazy(ctx, o, \"\", \"\")")
	e.p("\t\tif err != nil {")
	e.p("\t\t\treturn nil, err")
	e.p("\t\t}")
	e.p("\t\to = resolved")
	e.p("\t}")
	e.p("\t// **A hooked property is something to run, not a slot to read**, and a")
	e.p("\t// virtual one has no slot at all. So a class with hooks is walked in")
	e.p("\t// *declaration* order from the emitted name list rather than over the")
	e.p("\t// property table, and each name goes through `propGet` -- the same")
	e.p("\t// read an expression performs, hook, mangling and all.")
	e.p("\tout := php.NewArray()")
	e.p("\tif hooks := propHooks[o.ClassName]; len(hooks) > 0 {")
	e.p("\t\tdone := map[string]bool{}")
	e.p("\t\t// In the order of the object's slots -- a parent's shadowed")
	e.p("\t\t// private where the parent declared it, the class's own at the")
	e.p("\t\t// end (property_hooks/dump) -- skipping a private the scope")
	e.p("\t\t// is not the declaring class of.")
	e.p("\t\tnames := propOrder[o.ClassName]")
	e.p("\t\tif decls := declaredProps[strings.ToLower(o.ClassName)]; len(decls) > 0 {")
	e.p("\t\t\tnames = nil")
	e.p("\t\t\tfor _, d := range decls {")
	e.p("\t\t\t\tif d.Static || d.Visibility == \"private\" && !strings.EqualFold(d.Class, scope) {")
	e.p("\t\t\t\t\tcontinue")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\tnames = append(names, d.Name)")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\tfor _, name := range names {")
	e.p("\t\t\tif done[name] {")
	e.p("\t\t\t\tcontinue")
	e.p("\t\t\t}")
	e.p("\t\t\tdone[name] = true")
	e.p("\t\t\t// A **write-only** property -- virtual with only a set hook --")
	e.p("\t\t\t// has nothing to present, and reading it would be an Error")
	e.p("\t\t\t// rather than an omission.")
	e.p("\t\t\th, hooked := hooks[name]")
	e.p("\t\t\tif hooked && h.get == nil && h.virtual {")
	e.p("\t\t\t\tcontinue")
	e.p("\t\t\t}")
	e.p("\t\t\t// Visibility is asked of the **slot the scope resolves to**,")
	e.p("\t\t\t// before the read, because `propGet` answers an unreachable")
	e.p("\t\t\t// property with `__get` or a warning and this question wants")
	e.p("\t\t\t// neither.")
	e.p("\t\t\tslot := propertySlot(o, name, scope)")
	e.p("\t\t\tif php.CheckPropertyRead(ctx, o, slot, scope) != php.PropertyReachable {")
	e.p("\t\t\t\tcontinue")
	e.p("\t\t\t}")
	e.p("\t\t\tif !hooked {")
	e.p("\t\t\t\t// **Its box, not its value.** Only a hooked name is")
	e.p("\t\t\t\t// something to run; a plain one in the same class is still")
	e.p("\t\t\t\t// a slot, and a program-visible reference in it survives")
	e.p("\t\t\t\t// into the array.")
	e.p("\t\t\t\tif item, present := o.PropRaw(php.StringKey(slot)); present && item.Deref().Kind() != php.KindUndef {")
	e.p("\t\t\t\t\tout.Set(php.StringKey(name), php.CopyElement(item))")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\tcontinue")
	e.p("\t\t\t}")
	e.p("\t\t\tv, err := propGet(ctx, php.Obj(o), name, scope)")
	e.p("\t\t\tif err != nil {")
	e.p("\t\t\t\treturn nil, err")
	e.p("\t\t\t}")
	e.p("\t\t\tif v.Deref().Kind() == php.KindUndef {")
	e.p("\t\t\t\tcontinue")
	e.p("\t\t\t}")
	e.p("\t\t\tout.Set(php.StringKey(name), v.Deref())")
	e.p("\t\t}")
	e.p("\t\t// Whatever the declaration list does not cover is a **dynamic**")
	e.p("\t\t// property, which the engine lists after the declared ones.")
	e.p("\t\tvar failed error")
	e.p("\t\to.PropEachRaw(func(k php.Key, item php.Value) bool {")
	e.p("\t\t\tname := k.String()")
	e.p("\t\t\tplain, _, _ := php.UnmangleProperty(name)")
	e.p("\t\t\tif done[plain] || item.Deref().Kind() == php.KindUndef {")
	e.p("\t\t\t\treturn true")
	e.p("\t\t\t}")
	e.p("\t\t\tif php.CheckPropertyRead(ctx, o, name, scope) != php.PropertyReachable {")
	e.p("\t\t\t\treturn true")
	e.p("\t\t\t}")
	e.p("\t\t\tout.Set(php.StringKey(plain), php.CopyElement(item))")
	e.p("\t\t\treturn true")
	e.p("\t\t})")
	e.p("\t\treturn out, failed")
	e.p("\t}")
	e.p("\t// **A name the calling scope holds privately is that private slot.**")
	e.p("\t// `get_object_vars($this)` in A, on a B that redeclares A's private")
	e.p("\t// `$prop` as protected, shows A's value: the scope resolves the name to")
	e.p("\t// its own private, and the subclass's slot of the same name is not")
	e.p("\t// listed under it (gh20177).")
	e.p("\tscopeOwn := map[string]bool{}")
	e.p("\tif scope != \"\" {")
	e.p("\t\to.PropEachRaw(func(k php.Key, _ php.Value) bool {")
	e.p("\t\t\tif plain, owner, _ := php.UnmangleProperty(k.String()); owner != \"\" && owner != \"*\" && strings.EqualFold(owner, scope) {")
	e.p("\t\t\t\tscopeOwn[plain] = true")
	e.p("\t\t\t}")
	e.p("\t\t\treturn true")
	e.p("\t\t})")
	e.p("\t}")
	e.p("\t// **Raw**, so a program-visible reference in a slot is still one when")
	e.p("\t// it reaches the array: `Each` hands over the value behind the box.")
	e.p("\to.PropEachRaw(func(k php.Key, item php.Value) bool {")
	e.p("\t\t// An **uninitialised** typed property is not there: it has a slot")
	e.p("\t\t// and no value.")
	e.p("\t\tif item.Deref().Kind() == php.KindUndef {")
	e.p("\t\t\treturn true")
	e.p("\t\t}")
	e.p("\t\tname := k.String()")
	e.p("\t\tif plain, owner, _ := php.UnmangleProperty(name); scopeOwn[plain] && !strings.EqualFold(owner, scope) {")
	e.p("\t\t\treturn true")
	e.p("\t\t}")
	e.p("\t\tif php.CheckPropertyRead(ctx, o, name, scope) != php.PropertyReachable {")
	e.p("\t\t\treturn true")
	e.p("\t\t}")
	e.p("\t\tplain, _, _ := php.UnmangleProperty(name)")
	e.p("\t\t// **The box, not the value.** `get_object_vars` duplicates the")
	e.p("\t\t// property table rather than reading it, so a program-visible")
	e.p("\t\t// reference stays one: `$r = &$o->x` then makes the array")
	e.p("\t\t// element render `&int(9)` and track a later write. Same fact as")
	e.p("\t\t// `get_defined_vars` over the symbol table.")
	e.p("\t\tout.Set(php.StringKey(plain), php.CopyElement(item))")
	e.p("\t\treturn true")
	e.p("\t})")
	e.p("\treturn out, nil")
	e.p("}")
	e.p("")
	e.p("// scopedBuiltins are the library names whose answer depends on the")
	e.p("// **calling scope**. There is one, and giving it a table of its own is")
	e.p("// cheaper than threading a scope through every other entry.")
	e.p("var scopedBuiltins = map[string]func(*php.Ctx, string, []php.Value) (php.Value, error){}")
	e.p("")
	e.p("// Filled at start-up rather than in the initializer, for the reason")
	e.p("// `propHooks` is: `get_object_vars` reaches `propGet`, a hook body")
	e.p("// reaches a builtin, and a builtin reaches this table. Go rejects that")
	e.p("// cycle at package scope even though nothing runs at initialization.")
	e.p("func initScopedBuiltins() {")
	e.p("	scopedBuiltins = map[string]func(*php.Ctx, string, []php.Value) (php.Value, error){")
	e.p("\t\t\"get_object_vars\": func(ctx *php.Ctx, scope string, args []php.Value) (php.Value, error) {")
	e.p("\t\t\t// **What the *calling scope* can reach**, which is why this is")
	e.p("\t\t\t// here and not in the library table: from outside a class the")
	e.p("\t\t\t// public properties only, from inside also its own private and")
	e.p("\t\t\t// any protected in its hierarchy. The rule itself is the shared")
	e.p("\t\t\t// intrinsic -- only the scope comes from the call site.")
	e.p("\t\t\tv := php.Arg(args, 0)")
	e.p("\t\t\tif v.Kind() != php.KindObject {")
	e.p("\t\t\t\treturn php.Bool(false), nil")
	e.p("\t\t\t}")
	e.p("\t\t\tout, err := visibleProperties(ctx, v.Object(), scope)")
	e.p("\t\t\tif err != nil {")
	e.p("\t\t\t\treturn php.Value{}, err")
	e.p("\t\t\t}")
	e.p("\t\t\treturn php.Arr(out), nil")
	e.p("\t\t},")
	e.p("\t\t\"get_declared_classes\": func(_ *php.Ctx, _ string, _ []php.Value) (php.Value, error) {")
	e.p("\t\t\t// The engine\"s own first, in registration order, then the")
	e.p("\t\t\t// program\"s in declaration order. A **conditionally** declared")
	e.p("\t\t\t// class is listed only once its declaration has run, which is")
	e.p("\t\t\t// what `declaredClasses` answers -- an unconditional one is")
	e.p("\t\t\t// bound before the program starts and is always in it.")
	e.p("\t\t\tout := php.NewArray()")
	e.p("\t\t\tfor _, name := range engineClassList {")
	e.p("\t\t\t\tout.Append(php.String(name))")
	e.p("\t\t\t}")
	e.p("\t\t\tfor _, name := range declaredClassOrder {")
	e.p("\t\t\t\t// The library's own classes (php://memory's wrapper) are")
	e.p("\t\t\t\t// php2go's, not the program's, and the engine has none.")
	e.p("\t\t\t\tif declaredClasses[strings.ToLower(name)] && !strings.HasPrefix(name, `PHP2Go\\`) {")
	e.p("\t\t\t\t\tout.Append(php.String(name))")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\t// A `class_alias` is listed after them under its folded name,")
	e.p("\t\t\t// the class table's key (probed: `BB` lists as `bb`).")
	e.p("\t\t\tfor _, alias := range aliasOrder {")
	e.p("\t\t\t\tif t := strings.ToLower(classAliases[alias]); !interfaceClasses[t] && !traitClasses[t] {")
	e.p("\t\t\t\t\tout.Append(php.String(alias))")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\treturn php.Arr(out), nil")
	e.p("\t\t},")
	e.p("\t\t\"get_declared_interfaces\": func(_ *php.Ctx, _ string, _ []php.Value) (php.Value, error) {")
	e.p("\t\t\tout := php.NewArray()")
	e.p("\t\t\tfor _, name := range engineInterfaceList {")
	e.p("\t\t\t\tout.Append(php.String(name))")
	e.p("\t\t\t}")
	e.p("\t\t\tfor _, name := range declaredInterfaceOrder {")
	e.p("\t\t\t\tif declaredClasses[strings.ToLower(name)] {")
	e.p("\t\t\t\t\tout.Append(php.String(name))")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\tfor _, alias := range aliasOrder {")
	e.p("\t\t\t\tif interfaceClasses[strings.ToLower(classAliases[alias])] {")
	e.p("\t\t\t\t\tout.Append(php.String(alias))")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\treturn php.Arr(out), nil")
	e.p("\t\t},")
	e.p("\t\t\"get_declared_traits\": func(_ *php.Ctx, _ string, _ []php.Value) (php.Value, error) {")
	e.p("\t\t\tout := php.NewArray()")
	e.p("\t\t\tfor _, name := range declaredTraits {")
	e.p("\t\t\t\tout.Append(php.String(name))")
	e.p("\t\t\t}")
	e.p("\t\t\t// A trait's `class_alias` too, folded, as get_declared_classes")
	e.p("\t\t\t// lists a class's.")
	e.p("\t\t\tfor _, alias := range aliasOrder {")
	e.p("\t\t\t\tif traitClasses[strings.ToLower(classAliases[alias])] {")
	e.p("\t\t\t\t\tout.Append(php.String(alias))")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\treturn php.Arr(out), nil")
	e.p("\t\t},")
	e.p("\t\t\"get_class_methods\": func(ctx *php.Ctx, scope string, args []php.Value) (php.Value, error) {")
	e.p("\t\t\t// **What the calling scope can reach**, in the engine's order: a")
	e.p("\t\t\t// class's own declarations first -- with a trait's after them,")
	e.p("\t\t\t// which is where the harvest puts them -- then each ancestor's.")
	e.p("\t\t\t// A name a subclass redeclares appears once, at the subclass.")
	e.p("\t\t\tclass := realClass(className(php.Arg(args, 0)))")
	e.p("\t\t\tif class == \"\" {")
	e.p("\t\t\t\treturn php.Bool(false), nil")
	e.p("\t\t\t}")
	e.p("\t\t\t// An SPL iterator's methods are the engine's, in an order no")
	e.p("\t\t\t// table here keeps: listing only the compiled ones would drop")
	e.p("\t\t\t// them silently.")
	e.p("\t\t\tif splClassOf(class) != \"\" {")
	e.p("\t\t\t\treturn php.Value{}, php.Unsupported(\"get_class_methods of SPL iterator class %%s\", class)")
	e.p("\t\t\t}")
	e.p("\t\t\tout := php.NewArray()")
	e.p("\t\t\tseen := map[string]bool{}")
	e.p("\t\t\t// The class's whole table first (classFullMethodOrder: own,")
	e.p("\t\t\t// inherited, then traits, nested and aliased ones included),")
	e.p("\t\t\t// then each interface's names along the chain.")
	e.p("\t\t\tfirst := true")
	e.p("\t\t\tfor c := class; c != \"\"; c = parentOf[c] {")
	e.p("\t\t\t\tvar names []string")
	e.p("\t\t\t\tif first {")
	e.p("\t\t\t\t\tnames = append(names, classFullMethodOrder[c]...)")
	e.p("\t\t\t\t\tfirst = false")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\t// And then the interfaces': an abstract class that has not")
	e.p("\t\t\t\t// implemented one still lists the name, and a class that has")
	e.p("\t\t\t\t// declared it already saw it among its own.")
	e.p("\t\t\t\tfor _, i := range interfacesOf[c] {")
	e.p("\t\t\t\t\tnames = append(names, classMethodOrder[i]...)")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\tfor _, spelled := range names {")
	e.p("\t\t\t\t\tkey := strings.ToLower(spelled)")
	e.p("\t\t\t\t\tif seen[key] {")
	e.p("\t\t\t\t\t\tcontinue")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\t\t// **Marked seen whether or not it is visible.** A")
	e.p("\t\t\t\t\t// subclass's declaration shadows the ancestor's, so the")
	e.p("\t\t\t\t\t// ancestor's must not reappear further down the chain")
	e.p("\t\t\t\t\t// just because the nearer one was private.")
	e.p("\t\t\t\t\tseen[key] = true")
	e.p("\t\t\t\t\tif d, restricted := methodVisibility[class][key]; !restricted || methodReachable(d, scope) {")
	e.p("\t\t\t\t\t\tout.Append(php.String(spelled))")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\treturn php.Arr(out), nil")
	e.p("\t\t},")
	e.p("\t\t\"get_class_vars\": func(ctx *php.Ctx, scope string, args []php.Value) (php.Value, error) {")
	e.p("\t\t\tgiven := php.Arg(args, 0).Deref().String()")
	e.p("\t\t\tclass := resolveAlias(given)")
	e.p("\t\t\tctor, known := classCtors[strings.ToLower(class)]")
	e.p("\t\t\tif !known {")
	e.p("\t\t\t\t// The message quotes the **name as given**, not its type.")
	e.p("\t\t\t\treturn php.Value{}, php.RaiseAt(ctx, \"TypeError\",")
	e.p("\t\t\t\t\t\"get_class_vars(): Argument #1 ($class) must be a valid class name, %%s given\", given)")
	e.p("\t\t\t}")
	e.p("\t\t\t// **The declared defaults**, which only an instance carries here:")
	e.p("\t\t\t// the constructor helper declares and defaults every slot before")
	e.p("\t\t\t// any `__construct` runs, so a throwaway one is the table. It must")
	e.p("\t\t\t// not cost a handle -- the engine allocates no object for this and")
	e.p("\t\t\t// object numbers are graded byte-exact -- so the counter is put")
	e.p("\t\t\t// back. Nothing observes the instance: a property default is a")
	e.p("\t\t\t// constant expression, so building one prints nothing.")
	e.p("\t\t\tsaved, savedFree := nextObjectID, append([]int(nil), freeObjectIDs...)")
	e.p("\t\t\tsample := ctor(ctx)")
	e.p("\t\t\tnextObjectID, freeObjectIDs = saved, savedFree")
	e.p("\t\t\tout := php.NewArray()")
	e.p("\t\t\tfields := classFields[class]")
	e.p("\t\t\t// **Instance properties first, then the statics** -- whatever")
	e.p("\t\t\t// order they were declared in -- and within each group the")
	e.p("\t\t\t// class's own declarations before its ancestors'. Both read back")
	e.p("\t\t\t// from the engine, and both are the opposite of what is to hand:")
	e.p("\t\t\t// the harvest flattens parent-first, which is the order an")
	e.p("\t\t\t// *instance* carries -- and `get_object_vars`, a few lines up,")
	e.p("\t\t\t// really does use that one.")
	e.p("\t\t\tfor _, static := range []bool{false, true} {")
	e.p("\t\t\t\tfor _, i := range classFieldsOrdered(class) {")
	e.p("\t\t\t\t\tf := fields[i]")
	e.p("\t\t\t\t\tif f.static != static {")
	e.p("\t\t\t\t\t\tcontinue")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\t\tif static {")
	e.p("\t\t\t\t\t\t// Asked for its visibility and to force a deferred")
	e.p("\t\t\t\t\t\t// initializer; the **declared** value is what is")
	e.p("\t\t\t\t\t\t// reported, which is not the slot once anything has")
	e.p("\t\t\t\t\t\t// written to it.")
	e.p("\t\t\t\t\t\tslot, err := staticSlot(ctx, class, f.name, scope)")
	e.p("\t\t\t\t\t\tif err != nil || slot == nil {")
	e.p("\t\t\t\t\t\t\tcontinue")
	e.p("\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t\tvalue := slot.Deref()")
	e.p("\t\t\t\t\t\tif declared, ok := staticDefaults[f.owner+\"::\"+f.name]; ok {")
	e.p("\t\t\t\t\t\t\tvalue = declared")
	e.p("\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t\tout.Set(php.StringKey(f.name), value)")
	e.p("\t\t\t\t\t\tcontinue")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\t\tkey, held, ok := classVarSlot(sample, f.name, f.owner)")
	e.p("\t\t\t\t\tif !ok {")
	e.p("\t\t\t\t\t\tcontinue")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\t\tif php.CheckPropertyRead(ctx, sample, key, scope) != php.PropertyReachable {")
	e.p("\t\t\t\t\t\tcontinue")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\t\t// **An uninitialised typed property is listed as null**,")
	e.p("\t\t\t\t\t// unlike get_object_vars, which omits it: this asks what")
	e.p("\t\t\t\t\t// the class declares, not what an instance holds.")
	e.p("\t\t\t\t\tvalue := held.Deref()")
	e.p("\t\t\t\t\tif value.Kind() == php.KindUndef {")
	e.p("\t\t\t\t\t\tvalue = php.Null()")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\t\tout.Set(php.StringKey(f.name), value)")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\treturn php.Arr(out), nil")
	e.p("\t\t},")
	e.p("\t\t\"property_exists\": func(ctx *php.Ctx, scope string, args []php.Value) (php.Value, error) {")
	e.p("\t\t\t// `object|string` admits nothing else, even weakly: an int is")
	e.p("\t\t\t// refused, not converted to a class name.")
	e.p("\t\t\tif k := php.Arg(args, 0).Deref().Kind(); k != php.KindObject && k != php.KindString {")
	e.p("\t\t\t\treturn php.Value{}, php.Raise(\"TypeError\", \"property_exists(): Argument #1 ($object_or_class) must be of type object|string, %%s given\", php.ValueName(php.Arg(args, 0).Deref()))")
	e.p("\t\t\t}")
	e.p("\t\t\t// An incomplete object's has_property handler warns and says no.")
	e.p("\t\t\tif o := php.Arg(args, 0).Deref().Object(); php.IsIncomplete(o) {")
	e.p("\t\t\t\treturn php.Bool(false), php.IncompleteReadWarningFrom(ctx, o, \"property_exists\")")
	e.p("\t\t\t}")
	e.p("\t\t\tname := php.Arg(args, 1).String()")
	e.p("\t\t\tclass := className(php.Arg(args, 0))")
	e.p("\t\t\t// **A parent's private property is not part of the child.**")
	e.p("\t\t\t// Measured: with `class C extends B` and `B` declaring")
	e.p("\t\t\t// `private $p`, `property_exists(new C, \"p\")` and")
	e.p("\t\t\t// `property_exists(\"C\", \"p\")` are both false while")
	e.p("\t\t\t// `property_exists(\"B\", \"p\")` is true. The instance still")
	e.p("\t\t\t// *carries* the slot, which is why asking the object first")
	e.p("\t\t\t// answered true for every one of them.")
	e.p("\t\t\tdeclared := false")
	e.p("\t\t\tfor _, f := range classFields[class] {")
	e.p("\t\t\t\tif f.name != name {")
	e.p("\t\t\t\t\tcontinue")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\tdeclared = true")
	e.p("\t\t\t\t// Visible when the **caller** is the declaring class, which")
	e.p("\t\t\t\t// is how `property_exists($this, ...)` inside the parent")
	e.p("\t\t\t\t// answers true for an instance of the child.")
	e.p("\t\t\t\tif f.visibility == \"private\" &&")
	e.p("\t\t\t\t\t!strings.EqualFold(f.owner, class) && !strings.EqualFold(f.owner, scope) {")
	e.p("\t\t\t\t\tcontinue")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\treturn php.Bool(true), nil")
	e.p("\t\t\t}")
	e.p("\t\t\t// A **dynamic** property is on the instance and in no class")
	e.p("\t\t\t// table, so the object answers for exactly the names the table")
	e.p("\t\t\t// does not know.")
	e.p("\t\t\tif v := php.Arg(args, 0); !declared && v.Kind() == php.KindObject {")
	e.p("\t\t\t\tif _, ok := v.Object().Get(name); ok {")
	e.p("\t\t\t\t\treturn php.Bool(true), nil")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\treturn php.Bool(false), nil")
	e.p("\t\t},")
	e.p("\t}")
	e.p("}")
	e.p("")
	e.p("// globals is the file body's variables, by name. `global $g` in a")
	e.p("// function binds to the slot the file body declared, so the two names")
	e.p("// are one storage location and a write through either is visible to the")
	e.p("// other.")
	e.p("var globals = map[string]*php.Value{}")
	e.p("")
	e.p("// bindGlobal is `global $g`. It binds **by reference**, which is what")
	e.p("// makes an assignment inside the function change the global -- and what")
	e.p("// makes `unset($g)` afterwards drop only the local binding, leaving the")
	e.p("// global as it was. Read back from the engine, both halves.")
	e.p("//")
	e.p("// A name the file body never mentions gets a slot here rather than being")
	e.p("// refused: `function f() { global $n; $n = 7; }` creates the global, and")
	e.p("// anything reading it afterwards must find the same one.")
	e.p("func bindGlobal(target *php.Value, name string) {")
	e.p("\tslot, ok := globals[name]")
	e.p("\tif !ok {")
	e.p("\t\tslot = new(php.Value)")
	e.p("\t\tglobals[name] = slot")
	e.p("\t\tglobalOrder = append(globalOrder, name)")
	e.p("\t}")
	e.p("\tphp.BindRef(target, slot)")
	e.p("}")
	e.p("")
	e.p("// defineSuperglobal is where a superglobal a library defines lives in")
	e.p("// this program: the globals table. The first definition wins, and a")
	e.p("// name is defined once per request. A name the engine does not define")
	e.p("// -- php2go's own `$_RESP_HEADERS` -- is kept out of `$GLOBALS`, where")
	e.p("// no program on the engine could see it.")
	e.p("func defineSuperglobal(_ *php.Ctx, name string, initial php.Value) bool {")
	e.p("\tif definedSuperglobals[name] {")
	e.p("\t\treturn false")
	e.p("\t}")
	e.p("\tdefinedSuperglobals[name] = true")
	e.p("\tslot, ok := globals[name]")
	e.p("\tif !ok {")
	e.p("\t\tslot = new(php.Value)")
	e.p("\t\tglobals[name] = slot")
	e.p("\t\tif php.IsEngineSuperglobal(name) {")
	e.p("\t\t\tglobalOrder = append(globalOrder, name)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tif r, boxed := slot.RefOf(); boxed {")
	e.p("\t\tr.Set(initial)")
	e.p("\t} else {")
	e.p("\t\t*slot = initial")
	e.p("\t}")
	e.p("\treturn true")
	e.p("}")
	e.p("")
	e.p("var definedSuperglobals = map[string]bool{}")
	e.p("")
	e.p("// globalOrder is the order `$GLOBALS` lists its entries in. The map")
	e.p("// beside it cannot answer that, and the order is observable.")
	e.p("var globalOrder []string")
	e.p("")
	e.p("// globalsHoldObject reports whether any global slot -- a file-body")
	e.p("// variable, a compiler temporary of the file body, or a name bound by")
	e.p("// `global` -- holds an object, directly or through a reference. Every")
	e.p("// file-body place that can hold a PHP value is in the table; the ones")
	e.p("// left out are native ints, string builders and callee frames.")
	e.p("func globalsHoldObject() bool {")
	e.p("\tfor _, slot := range globals {")
	e.p("\t\tif slot != nil && slot.Deref().Kind() == php.KindObject {")
	e.p("\t\t\treturn true")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn false")
	e.p("}")
	e.p("")
	e.p("// globalsSnapshot is `$GLOBALS` read whole.")
	e.p("//")
	e.p("// **A snapshot, not a live view.** Since PHP 8.1 writing through the")
	e.p("// array does nothing, and `$GLOBALS[\"x\"] = v` is rewritten by the")
	e.p("// compiler into a plain global fetch rather than reaching here -- so a")
	e.p("// copy is the whole contract.")
	e.p("//")
	e.p("// A global with no value yet is **not there**: a name is in the symbol")
	e.p("// table once something has been written to it, and `global $n;` alone")
	e.p("// creates the slot without putting the name in `$GLOBALS`.")
	e.p("func globalsSnapshot() php.Value {")
	e.p("\tout := php.NewArray()")
	e.p("\tfor _, name := range globalOrder {")
	e.p("\t\tslot, ok := globals[name]")
	e.p("\t\tif !ok || slot.Deref().Kind() == php.KindUndef {")
	e.p("\t\t\tcontinue")
	e.p("\t\t}")
	e.p("\t\tout.Set(php.StringKey(name), slot.Deref().Copy())")
	e.p("\t}")
	e.p("\treturn php.Arr(out)")
	e.p("}")
	e.p("")
	e.p("// variadicArgs collects `...$rest` -- every argument from a position on,")
	e.p("// in order, as an array with sequential keys.")
	e.p("//")
	e.p("// A declared type applies to **each element** rather than to the array,")
	e.p("// and the position it reports is the argument's own, so the second")
	e.p("// element of a variadic starting at 1 is `Argument #2`.")
	e.p("func variadicArgs(ctx *php.Ctx, args []php.Value, from int, declared, fn string, strict bool) (php.Value, error) {")
	e.p("\tout := php.NewArray()")
	e.p("\t// **A named argument no parameter claimed lands here under its name.**")
	e.p("\t// They are the trailing arguments -- a positional one after a named one")
	e.p("\t// does not compile -- so the count lines them up with the tail.")
	e.p("\tnames := ctx.TakeArgNames()")
	e.p("\tnamedFrom := len(args) - len(names)")
	e.p("\tfor i := from; i < len(args); i++ {")
	e.p("\t\tv := args[i].Deref().Copy()")
	e.p("\t\tif declared != \"\" {")
	e.p("\t\t\tcoerced, err := php.CoerceArgument(ctx, v, declared, fn, i+1, \"\", strict)")
	e.p("\t\t\tif err != nil {")
	e.p("\t\t\t\treturn php.Value{}, err")
	e.p("\t\t\t}")
	e.p("\t\t\tv = coerced")
	e.p("\t\t}")
	e.p("\t\tif i >= namedFrom && i-namedFrom < len(names) {")
	e.p("\t\t\tout.Set(php.StringKey(names[i-namedFrom]), v)")
	e.p("\t\t\tcontinue")
	e.p("\t\t}")
	e.p("\t\tout.Append(v)")
	e.p("\t}")
	e.p("\treturn php.Arr(out), nil")
	e.p("}")
	e.p("")
	e.p("// variadicRefArgs is `...$rest` for a **by-reference** variadic: the")
	e.p("// elements keep the boxes the caller sent, so `$rest[0] = 1` writes the")
	e.p("// first variable the caller named.")
	e.p("//")
	e.p("// An argument that arrived as a value rather than as storage is copied in")
	e.p("// as one. The engine warns at the *call site* when it cannot pass a")
	e.p("// reference, so there is nothing for the callee to say about it.")
	e.p("func variadicRefArgs(ctx *php.Ctx, args []php.Value, from int) (php.Value, error) {")
	e.p("\t_ = ctx")
	e.p("\tout := php.NewArray()")
	e.p("\tfor i := from; i < len(args); i++ {")
	e.p("\t\tif _, boxed := args[i].RefOf(); boxed {")
	e.p("\t\t\tout.Append(php.Shared(args[i]))")
	e.p("\t\t\tcontinue")
	e.p("\t\t}")
	e.p("\t\tout.Append(args[i].Deref().Copy())")
	e.p("\t}")
	e.p("\treturn php.Arr(out), nil")
	e.p("}")
	e.p("")
	e.p("// unshareArgs drops the marks variadicRefArgs made.")
	e.p("func unshareArgs(args []php.Value, from int) {")
	e.p("\tfor i := from; i < len(args); i++ {")
	e.p("\t\tif _, boxed := args[i].RefOf(); boxed {")
	e.p("\t\t\tphp.Unshare(args[i])")
	e.p("\t\t}")
	e.p("\t}")
	e.p("}")
	e.p("")
	e.p("// unpackArgs appends `...$args` to a call's argument list.")
	e.p("//")
	e.p("// **An integer key is positional and a string key is a named argument**,")
	e.p("// which is a different calling convention this emitter does not have --")
	e.p("// so a string key is reported as the gap it is rather than quietly bound")
	e.p("// by position. `f(...[\"b\" => 5, \"a\" => 4])` binds by name in the")
	e.p("// engine, which is what makes the quiet version a wrong answer.")
	e.p("//")
	e.p("// A Traversable unpacks as well as an array; anything else is a")
	e.p("// TypeError naming what was given.")
	e.p("// namedParamAt is the position of the callee's parameter `name` and")
	e.p("// whether it takes a reference, from the same table a closure's")
	e.p("// var_dump reads.")
	e.p("func namedParamAt(callee, name string) (int, bool, bool) {")
	e.p("\tif callee == \"\" {")
	e.p("\t\treturn 0, false, false")
	e.p("\t}")
	e.p("\tfor i, p := range namedCallableParams[strings.ToLower(callee)] {")
	e.p("\t\tif strings.TrimPrefix(p.name, \"&\") == \"$\"+name {")
	e.p("\t\t\treturn i, strings.HasPrefix(p.name, \"&\"), true")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn 0, false, false")
	e.p("}")
	e.p("")
	e.p("// unpackForUserSend is set while call_user_func_array's argument list")
	e.p("// is unpacked: its refusal of a positional argument after a named one")
	e.p("// is the plain message, where a written `...$x` adds `during")
	e.p("// unpacking` (named_params/call_user_func_array).")
	e.p("var unpackForUserSend bool")
	e.p("")
	e.p("func positionalAfterNamed() string {")
	e.p("\tif unpackForUserSend {")
	e.p("\t\treturn \"Cannot use positional argument after named argument\"")
	e.p("\t}")
	e.p("\treturn \"Cannot use positional argument after named argument during unpacking\"")
	e.p("}")
	e.p("")
	e.p("func unpackArgs(ctx *php.Ctx, into []php.Value, v php.Value, slot *php.Value, callee string, byRef []int, refFrom int) ([]php.Value, error) {")
	e.p("\tsubject := v.Deref()")
	e.p("\tisRef := func(at int) bool {")
	e.p("\t\tif refFrom >= 0 && at >= refFrom {")
	e.p("\t\t\treturn true")
	e.p("\t\t}")
	e.p("\t\tfor _, r := range byRef {")
	e.p("\t\t\tif r == at {")
	e.p("\t\t\t\treturn true")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\treturn false")
	e.p("\t}")
	e.p("\t// **A by-reference position binds the variable's own element.** The")
	e.p("\t// engine separates the unpacked variable's array and makes each such")
	e.p("\t// element a reference in it, so the callee's writes land in `$a` and")
	e.p("\t// not in `$b = $a`. Boxed first, then sent as any bound element is;")
	e.p("\t// keys collected before boxing, since RefAt may separate the body.")
	e.p("\t// A string key binds by **name**, and a by-reference parameter of")
	e.p("\t// that name takes the element's box just as a position does:")
	e.p("\t// `test2(...$ary)` with `['b' => 0]` against `&$b` increments `$ary`")
	e.p("\t// and not its copy (named_params/unpack).")
	e.p("\tif slot != nil && subject.Kind() == php.KindArray && (len(byRef) > 0 || refFrom >= 0 || callee != \"\") {")
	e.p("\t\tif own := slot.Deref(); own.Kind() == php.KindArray {")
	e.p("\t\t\tvar keys []php.Key")
	e.p("\t\t\tat := len(into)")
	e.p("\t\t\town.Array().EachRaw(func(k php.Key, e php.Value) bool {")
	e.p("\t\t\t\tif !k.IsInt {")
	e.p("\t\t\t\t\tif _, byName, ok := namedParamAt(callee, k.Str); ok && byName {")
	e.p("\t\t\t\t\t\tif _, boxed := e.RefOf(); !boxed {")
	e.p("\t\t\t\t\t\t\tkeys = append(keys, k)")
	e.p("\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\t\treturn true")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\tif _, boxed := e.RefOf(); !boxed && isRef(at) {")
	e.p("\t\t\t\t\tkeys = append(keys, k)")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\tat++")
	e.p("\t\t\t\treturn true")
	e.p("\t\t\t})")
	e.p("\t\t\tfor _, k := range keys {")
	e.p("\t\t\t\town.Array().RefAt(k)")
	e.p("\t\t\t}")
	e.p("\t\t\tsubject = own")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tswitch subject.Kind() {")
	e.p("\tcase php.KindArray:")
	e.p("\t\tvar err error")
	e.p("\t\tvar named []string")
	e.p("\t\tvar namedValues []php.Value")
	// **Raw**, because a bound element keeps its box. `$a = [&$v]; f(...$a)`
	// -- which is also what `call_user_func_array` compiles to, since the
	// engine sends it as an unpack -- reaches a `&$x` parameter as a
	// reference, and dereferencing here made every such call by value with no
	// complaint.
	e.p("\t\tsubject.Array().EachRaw(func(k php.Key, e php.Value) bool {")
	e.p("\t\t\tif !k.IsInt {")
	e.p("\t\t\t\t// **A string key is a named argument**, which is what the")
	e.p("\t\t\t\t// engine does with it: `f(...[\"b\" => 20])` binds `$b`.")
	e.p("\t\t\t\t// Collected here and handed to the same `argNames`")
	e.p("\t\t\t\t// channel an explicitly written `f(b: 20)` uses, rather")
	e.p("\t\t\t\t// than bound by position -- which is the wrong answer this")
	e.p("\t\t\t\t// used to refuse rather than give.")
	e.p("\t\t\t\tnamed = append(named, k.Str)")
	e.p("\t\t\t\tif _, boxed := e.RefOf(); boxed {")
	e.p("\t\t\t\t\tnamedValues = append(namedValues, e)")
	e.p("\t\t\t\t\treturn true")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\tnamedValues = append(namedValues, e.Deref().Copy())")
	e.p("\t\t\t\treturn true")
	e.p("\t\t\t}")
	e.p("\t\t\tif len(named) > 0 {")
	e.p("\t\t\t\t// PHP refuses a positional argument after a named one, and")
	e.p("\t\t\t\t// an unpacked array is no different.")
	e.p("\t\t\t\terr = php.RaiseAt(ctx, \"Error\", \"%%s\", positionalAfterNamed())")
	e.p("\t\t\t\treturn false")
	e.p("\t\t\t}")
	e.p("\t\t\tif _, boxed := e.RefOf(); boxed {")
	e.p("\t\t\t\t// The callee\"s `recv` decides: a by-reference parameter")
	e.p("\t\t\t\t// takes the box and a by-value one unboxes, which is the")
	e.p("\t\t\t\t// same undecided send a dynamic call already makes.")
	e.p("\t\t\t\tinto = append(into, e)")
	e.p("\t\t\t\treturn true")
	e.p("\t\t\t}")
	e.p("\t\t\tinto = append(into, e.Deref().Copy())")
	e.p("\t\t\treturn true")
	e.p("\t\t})")
	e.p("\t\tif err == nil && len(named) > 0 {")
	e.p("\t\t\t// The named ones go **after** every positional argument, which")
	e.p("\t\t\t// is where `BindNamedArgs` looks for them: it reads the names")
	e.p("\t\t\t// as covering the trailing arguments.")
	e.p("\t\t\tinto = append(into, namedValues...)")
	e.p("\t\t\tctx.SetArgNames(append(append([]string(nil), ctx.ArgNames()...), named...))")
	e.p("\t\t}")
	e.p("\t\treturn into, err")
	e.p("\tcase php.KindObject:")
	e.p("\t\t// A Traversable unpacks by being **drained**: one left-to-right")
	e.p("\t\t// walk of the iterator protocol, which this program already has.")
	e.p("\t\t// Not Traversable at all falls through to the TypeError below.")
	e.p("\t\t// A **Generator** is Traversable without the class table saying")
	e.p("\t\t// so -- it is the engine's own type, recognised by its payload the")
	e.p("\t\t// way `newIterator` recognises it.")
	e.p("\t\t_, isGen := subject.Object().Internal.(*php.Generator)")
	e.p("\t\tif !isGen && !isTraversableClass(subject.Object().ClassName) {")
	e.p("\t\t\tbreak")
	e.p("\t\t}")
	e.p("\t\tit, err := newIterator(ctx, subject, \"\")")
	e.p("\t\tif err != nil {")
	e.p("\t\t\treturn into, err")
	e.p("\t\t}")
	e.p("\t\tvar tNamed []string")
	e.p("\t\tvar tNamedValues []php.Value")
	e.p("\t\tfor php.IteratorValid(it) {")
	e.p("\t\t\tkey, err := php.IteratorKey(ctx, it)")
	e.p("\t\t\tif err != nil {")
	e.p("\t\t\t\treturn into, err")
	e.p("\t\t\t}")
	e.p("\t\t\t// **A numeric string key is an integer one**: a generator")
	e.p("\t\t\t// yielding `'100' => ...` sends a positional argument, as an")
	e.p("\t\t\t// array's key would be (gh18581).")
	e.p("\t\t\tif k := key.Deref(); k.Kind() == php.KindString {")
	e.p("\t\t\t\tif ak := php.ArrayKey(nil, k); ak.IsInt {")
	e.p("\t\t\t\t\tkey = php.Int(ak.Int)")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\tswitch key.Deref().Kind() {")
	e.p("\t\t\tcase php.KindInt:")
	e.p("\t\t\t\t// **An integer key is not a position.** Measured: a")
	e.p("\t\t\t\t// generator yielding `5 => \"x\"` then `9 => \"y\"` sends")
	e.p("\t\t\t\t// them as the next two arguments, not the sixth and tenth.")
	e.p("\t\t\t\t// And none may follow a string key, as for an array.")
	e.p("\t\t\t\tif len(tNamed) > 0 {")
	e.p("\t\t\t\t\treturn into, php.RaiseAt(ctx, \"Error\", \"%%s\", positionalAfterNamed())")
	e.p("\t\t\t\t}")
	e.p("\t\t\tcase php.KindString:")
	e.p("\t\t\t\t// A string key is a **named** argument, and goes out on the")
	e.p("\t\t\t\t// same `argNames` channel an unpacked array\"s does -- the")
	e.p("\t\t\t\t// value trails and the callee\"s prologue places it.")
	e.p("\t\t\t\tv, err := php.IteratorCurrent(ctx, it)")
	e.p("\t\t\t\tif err != nil {")
	e.p("\t\t\t\t\treturn into, err")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\tif at, byName, ok := namedParamAt(callee, key.Deref().String()); ok && byName {")
	e.p("\t\t\t\t\tctx.Warn(\"Cannot pass by-reference argument %%d of %%s() by unpacking a Traversable, passing by-value instead\", at+1, callee)")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\ttNamed = append(tNamed, key.Deref().String())")
	e.p("\t\t\t\ttNamedValues = append(tNamedValues, v.Deref().Copy())")
	e.p("\t\t\t\tif _, err := php.IteratorNext(ctx, it); err != nil {")
	e.p("\t\t\t\t\treturn into, err")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\tcontinue")
	e.p("\t\t\tdefault:")
	e.p("\t\t\t\treturn into, php.RaiseAt(ctx, \"Error\", \"Keys must be of type int|string during argument unpacking\")")
	e.p("\t\t\t}")
	e.p("\t\t\tv, err := php.IteratorCurrent(ctx, it)")
	e.p("\t\t\tif err != nil {")
	e.p("\t\t\t\treturn into, err")
	e.p("\t\t\t}")
	e.p("\t\t\t// By value: a Traversable hands out values, so a callee's")
	e.p("\t\t\t// by-reference parameter gets a **warning** rather than a box")
	e.p("\t\t\t// -- and the call still happens, which is why this is not an")
	e.p("\t\t\t// error. Named per position, so the callee has to be known.")
	e.p("\t\t\tif callee != \"\" {")
	e.p("\t\t\t\tif at := len(into); isRef(at) {")
	e.p("\t\t\t\t\tctx.Warn(\"Cannot pass by-reference argument %%d of %%s() by unpacking a Traversable, passing by-value instead\", at+1, callee)")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\tinto = append(into, v.Deref().Copy())")
	e.p("\t\t\tif _, err := php.IteratorNext(ctx, it); err != nil {")
	e.p("\t\t\t\treturn into, err")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\tif len(tNamed) > 0 {")
	e.p("\t\t\tinto = append(into, tNamedValues...)")
	e.p("\t\t\tctx.SetArgNames(append(append([]string(nil), ctx.ArgNames()...), tNamed...))")
	e.p("\t\t}")
	e.p("\t\treturn into, nil")
	e.p("\t}")
	e.p("\treturn into, php.RaiseAt(ctx, \"TypeError\", \"Only arrays and Traversables can be unpacked, %%s given\", php.TypeName(subject))")
	e.p("}")
	e.p("")
	e.p("// castToObject is `(object)$x`. The property table is runtime/php's;")
	e.p("// the handle is this unit's, which is why the two halves are split the")
	e.p("// same way `clone` is.")
	e.p("func castToObject(v php.Value) php.Value {")
	e.p("\tif v.Deref().Kind() == php.KindObject {")
	e.p("\t\treturn v.Deref()")
	e.p("\t}")
	e.p("\to := php.NewObject(\"stdClass\", allocObjectID())")
	e.p("\to.Props = php.ObjectCastProps(v)")
	e.p("\treturn php.Obj(o)")
	e.p("}")
	e.p("")
	e.p("// newDynamic instantiates a class named at run time.")
	e.p("func newDynamic(ctx *php.Ctx, name string) (php.Value, error) {")
	e.p("\tresolved := resolveAlias(name)")
	e.p("\tif strings.EqualFold(resolved, \"stdClass\") {")
	e.p("\t\treturn php.Obj(php.NewObject(\"stdClass\", allocObjectID())), nil")
	e.p("\t}")
	e.p("\t// An engine exception named at run time -- `new $x` with `$x =")
	e.p("\t// \"Exception\"` -- is made as a literal `new Exception` is; its")
	e.p("\t// constructor runs separately.")
	e.p("\tif !declaredClasses[strings.ToLower(resolved)] && php.IsThrowableClass(resolved) && !interfaceClasses[strings.ToLower(resolved)] && !strings.EqualFold(resolved, \"Throwable\") {")
	e.p("\t\to := php.InitThrowable(ctx, php.NewObject(engineSpelling(resolved), allocObjectID()), \"\", 0, php.Null())")
	e.p("\t\tsetThrowableTrace(ctx, o, ctx.ExceptionTrace())")
	e.p("\t\treturn php.Obj(o), nil")
	e.p("\t}")
	e.p("\tif !declaredClasses[strings.ToLower(resolved)] {")
	e.p("\t\t// `new` autoloads, which is the commonest way an autoloader is")
	e.p("\t\t// reached at all.")
	e.p("\t\tc, err := knownClass(ctx, resolved)")
	e.p("\t\tif err != nil {")
	e.p("\t\t\treturn php.Value{}, err")
	e.p("\t\t}")
	e.p("\t\tif c == \"\" {")
	e.p("\t\t\treturn php.Value{}, php.ThrowClassNotFound(name)")
	e.p("\t\t}")
	e.p("\t\tresolved = c")
	e.p("\t}")
	e.p("\tif err := instantiableErr(resolved); err != nil {")
	e.p("\t\treturn php.Value{}, err")
	e.p("\t}")
	e.p("\tif err := ensureClass(ctx, declaredSpelling(resolved)); err != nil {")
	e.p("\t\treturn php.Value{}, err")
	e.p("\t}")
	e.p("\tctor, ok := classCtors[strings.ToLower(resolved)]")
	e.p("\tif !ok {")
	e.p("\t\treturn php.Value{}, php.Unsupported(\"instantiating %%s\", name)")
	e.p("\t}")
	e.p("\treturn php.Obj(ctor(ctx)), nil")
	e.p("}")
	e.p("")
	e.p("// engineFuncs is every global function the *engine* provides.")
	e.p("//")
	e.p("// A **dynamic** call cannot be checked at emit time, so the set travels")
	e.p("// with the program to answer the same question the static path answers")
	e.p("// from the harvest: a name the engine has and runtime/php lacks is")
	e.p("// **our gap**, while one neither has is the program's error. Reporting")
	e.p("// the first as `Call to undefined function` claims PHP semantics that")
	e.p("// were never implemented, which is the masquerade QUALITY_GATE forbids.")
	e.p("var engineFuncs = map[string]bool{")
	names := make([]string, 0, len(p.EngineFunctions))
	for n := range p.EngineFunctions {
		names = append(names, n)
	}
	sort.Strings(names)
	for _, n := range names {
		e.p("\t%q: true,", n)
	}
	e.p("}")
	e.p("")
	e.p("// engineFuncAttributed is the engine functions carrying attributes")
	e.p("// (harvested): reflecting their attributes is a gap.")
	e.p("var engineFuncAttributed = map[string]bool{")
	{
		attributed := make([]string, 0, len(p.EngineFunctionAttributed))
		for n := range p.EngineFunctionAttributed {
			attributed = append(attributed, n)
		}
		sort.Strings(attributed)
		for _, n := range attributed {
			e.p("\t%q: true,", n)
		}
	}
	e.p("}")
	e.p("")
	e.p("// callUser runs a function the program defines, recording the frame a")
	e.p("// stack trace needs.")
	e.p("//")
	e.p("// The file and line are the **call site**, captured before the callee")
	e.p("// runs, because that is what PHP's trace names: `#0 t.php(2): inner(42)`")
	e.p("// is where `inner` was called from, not where it threw. Reading the")
	e.p("// location after the call would give the callee's own last line.")
	e.p("func callUser(ctx *php.Ctx, name string, fn func(*php.Ctx, []php.Value) (php.Value, error), args []php.Value) (php.Value, error) {")
	e.p("\tfile, line := ctx.Location()")
	e.p("\tctx.PushCall(php.StackFrame{Function: name, File: file, Line: line, Args: args})")
	e.p("\tdefer ctx.PopCall()")
	e.p("\treturn fn(ctx, args)")
	e.p("}")
	e.p("")
	e.p("// inIntRange is an int version's range: see lower.AssumedIntRange.")
	e.p("func inIntRange(x int64) bool { return x >= %d && x <= %d }", -lower.AssumedIntRange, lower.AssumedIntRange)
	e.p("")
	for n := 1; n <= maxUnboxedArity; n++ {
		ps, ts, boxed := make([]string, n), make([]string, n), make([]string, n)
		for i := range ps {
			ps[i], ts[i], boxed[i] = fmt.Sprintf("a%d", i), "int64", fmt.Sprintf("php.Int(a%d)", i)
		}
		e.p("// callUserInt%d calls an int version's unboxed entry with %d int arguments,", n, n)
		e.p("// pushing the frame a trace reads with the arguments boxed into it.")
		e.p("func callUserInt%d(ctx *php.Ctx, name string, fn func(*php.Ctx, %s) (php.Value, error), %s int64) (php.Value, error) {",
			n, strings.Join(ts, ", "), strings.Join(ps, ", "))
		e.p("\tfile, line := ctx.Location()")
		if n <= 4 {
			// Kept unboxed in the frame (php.Ctx.PushCallInts): nothing is
			// copied onto the argument stack, and Args is built only if a
			// trace reads the frame.
			pad := append(append([]string(nil), ps...), "0", "0", "0", "0")[:4]
			e.p("\tctx.PushCallInts(name, file, line, %d, %s)", n, strings.Join(pad, ", "))
		} else {
			e.p("\tctx.PushCallArgs(name, file, line, []php.Value{%s})", strings.Join(boxed, ", "))
		}
		e.p("\tdefer ctx.PopCall()")
		e.p("\treturn fn(ctx, %s)", strings.Join(ps, ", "))
		e.p("}")
		e.p("")
	}
	e.p("// callUserArgs is callUser for a function whose body does not keep its")
	e.p("// argument slice: the arguments are copied onto the Ctx's argument stack")
	e.p("// for the call's duration (php.Ctx.PushCallArgs), so the literal the call")
	e.p("// site passes stays on the Go stack and the call allocates nothing.")
	e.p("func callUserArgs(ctx *php.Ctx, name string, fn func(*php.Ctx, []php.Value) (php.Value, error), args ...php.Value) (php.Value, error) {")
	e.p("\tfile, line := ctx.Location()")
	e.p("\town := ctx.PushCallArgs(name, file, line, args)")
	e.p("\tdefer ctx.PopCall()")
	e.p("\treturn fn(ctx, own)")
	e.p("}")
	e.p("")
	e.p("// callBuiltin dispatches to the runtime's library surface. Whether a name")
	e.p("// is a builtin was decided at emit time; this fails loudly if the two ever")
	e.p("// disagree rather than silently returning null.")
	// The engine's declared parameter list for every library function this
	// program can reach, and the check over it. It is what makes
	// `str_repeat("a", [])` the TypeError the engine raises rather than `""`:
	// an internal function's arguments are verified *before* it runs, and
	// compiled code was skipping that entirely.
	//
	// Only the functions the runtime provides are emitted -- the engine
	// declares some 1,500 and a program can call the ones that exist.
	e.p("type builtinParam struct {")
	e.p("\tname  string")
	e.p("\ttyp   string")
	e.p("\tbyRef bool")
	e.p("}")
	e.p("")
	e.p("type builtinSignature struct {")
	e.p("\tname     string")
	e.p("\tparams   []builtinParam")
	e.p("\tvariadic bool")
	e.p("\t// required is how many leading parameters have no default, which is")
	e.p("\t// what the argument-count check needs and the type check never did.")
	e.p("\trequired int")
	e.p("}")
	e.p("")
	e.p("var builtinSignatures = map[string]builtinSignature{")
	signed := make([]string, 0, len(e.builtins))
	for name := range e.builtins {
		signed = append(signed, name)
	}
	sort.Strings(signed)
	for _, name := range signed {
		sig, ok := p.BuiltinSignatures[name]
		if !ok {
			continue
		}
		var params []string
		for _, arg := range sig.Params {
			params = append(params, fmt.Sprintf("{%q, %q, %t}", arg.Name, arg.Type, arg.ByRef))
		}
		e.p("\t%q: {%q, []builtinParam{%s}, %t, %d},", name, sig.Name,
			strings.Join(params, ", "), sig.Variadic, sig.Required)
	}
	e.p("}")
	e.p("")
	// get_parent_class is the one function whose declared type is wider than
	// what it accepts, so its refusal is its own to word.
	e.p("// ownArgumentDiagnostics are the functions whose parameter is declared")
	e.p("// wider than what they accept, so the refusal is theirs to word rather")
	e.p("// than the signature's. Checking here would report the declared type,")
	e.p("// which is not what the engine prints.")
	e.p("var ownArgumentDiagnostics = map[string]bool{\"get_parent_class\": true}")
	e.p("")
	e.p("// builtinMinimumArgs: a handful of ext/standard variadics declare only")
	e.p("// their first array in the stub and then parse trailing callbacks")
	e.p("// themselves, so the parser\"s minimum -- not the wider reflection")
	e.p("// signature -- decides the ArgumentCountError.")
	e.p("var builtinMinimumArgs = map[string]int{")
	for _, n := range []string{"array_diff_uassoc", "array_diff_ukey", "array_intersect_uassoc",
		"array_intersect_ukey", "array_udiff", "array_udiff_assoc", "array_uintersect",
		"array_uintersect_assoc"} {
		e.p("\t%q: 2,", n)
	}
	for _, n := range []string{"array_udiff_uassoc", "array_uintersect_uassoc"} {
		e.p("\t%q: 3,", n)
	}
	e.p("}")
	e.p("")
	e.p("// verifyBuiltinArgs applies the engine's declared parameter types to a")
	e.p("// library call, coercing where PHP coerces and raising where it raises.")
	e.p("//")
	e.p("// A **by-reference** parameter is skipped: the native implementation")
	e.p("// parses its own and may deliberately narrow the declared type.")
	e.p("// A **callable** parameter is checked by the callback rule instead,")
	e.p("// which says why the value is not one rather than what type it is.")
	e.p("func verifyBuiltinArgs(ctx *php.Ctx, name string, args []php.Value, strict bool) error {")
	e.p("\tsig, ok := builtinSignatures[name]")
	e.p("\tif !ok {")
	e.p("\t\treturn nil")
	e.p("\t}")
	e.p("\t// **The argument count comes first**, and it is checked even for the")
	e.p("\t// functions that word their own type refusals -- those own the")
	e.p("\t// *type* message, not the count. Compiled output checked types and")
	e.p("\t// never the count at all, so `strtoupper(\"a\", \"b\")` quietly")
	e.p("\t// answered \"AB\" where the engine raises ArgumentCountError.")
	e.p("\tcounted := true")
	e.p("\tfor _, a := range args {")
	e.p("\t\tif a.IsUndef() {")
	e.p("\t\t\t// Named arguments left a hole the defaults have not filled.")
	e.p("\t\t\tcounted = false")
	e.p("\t\t\tbreak")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tif counted {")
	e.p("\t\tleast := sig.required")
	e.p("\t\tif parsed := builtinMinimumArgs[name]; parsed > least {")
	e.p("\t\t\tleast = parsed")
	e.p("\t\t}")
	e.p("\t\tmost := len(sig.params)")
	e.p("\t\tif sig.variadic {")
	e.p("\t\t\tmost = -1")
	e.p("\t\t}")
	e.p("\t\tif msg, bad := php.BuiltinArityError(sig.name, len(args), least, most); bad {")
	e.p("\t\t\treturn php.RaiseAt(ctx, \"ArgumentCountError\", \"%%s\", msg)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tif ownArgumentDiagnostics[name] {")
	e.p("\t\treturn nil")
	e.p("\t}")
	e.p("\tfor i := range args {")
	e.p("\t\tindex := i")
	e.p("\t\tif index >= len(sig.params) {")
	e.p("\t\t\tif !sig.variadic || len(sig.params) == 0 {")
	e.p("\t\t\t\tbreak")
	e.p("\t\t\t}")
	e.p("\t\t\tindex = len(sig.params) - 1")
	e.p("\t\t}")
	e.p("\t\tparam := sig.params[index]")
	// **The variadic parameter is never named.** It carries a name in the
	// declaration -- `array ...$arrays` -- and the engine prints the position
	// alone for it: `Argument #3 must be of type array`, where the declared
	// one before it says `Argument #2 ($array)`.
	e.p("\t\tparamName := param.name")
	e.p("\t\tif sig.variadic && index == len(sig.params)-1 {")
	e.p("\t\t\tparamName = \"\"")
	e.p("\t\t}")
	e.p("\t\t// A **by-reference array** is checked in its turn too, though")
	e.p("\t\t// nothing is converted: `usort($undefined, \"f\")` refuses the")
	e.p("\t\t// array before it looks at the callback.")
	e.p("\t\tif param.byRef && param.typ == \"array\" {")
	e.p("\t\t\tif _, err := php.CoerceInternalArgument(ctx, args[i].Deref(), \"array\", sig.name, i+1, paramName, strict); err != nil {")
	e.p("\t\t\t\treturn err")
	e.p("\t\t\t}")
	e.p("\t\t\tcontinue")
	e.p("\t\t}")
	e.p("\t\tif param.byRef || param.typ == \"\" {")
	e.p("\t\t\tcontinue")
	e.p("\t\t}")
	e.p("\t\tif strings.Contains(param.typ, \"callable\") {")
	e.p("\t\t\tcheck := ctx.CheckCallable")
	e.p("\t\t\tif strings.HasPrefix(param.typ, \"?\") || strings.Contains(param.typ, \"null\") {")
	e.p("\t\t\t\tif k := args[i].Deref().Kind(); k == php.KindNull || k == php.KindUndef {")
	e.p("\t\t\t\t\tcontinue")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\tcheck = ctx.CheckCallableOrNull")
	e.p("\t\t\t}")
	e.p("\t\t\tif err := check(sig.name, i+1, paramName, args[i]); err != nil {")
	e.p("\t\t\t\treturn err")
	e.p("\t\t\t}")
	e.p("\t\t\tcontinue")
	e.p("\t\t}")
	e.p("\t\tconverted, err := php.CoerceInternalArgument(")
	e.p("\t\t\tctx, args[i], param.typ, sig.name, i+1, paramName, strict)")
	e.p("\t\tif err != nil {")
	e.p("\t\t\treturn err")
	e.p("\t\t}")
	e.p("\t\targs[i] = converted")
	e.p("\t}")
	e.p("\treturn nil")
	e.p("}")
	e.p("")
	e.p("func callBuiltin(ctx *php.Ctx, scope, name string, args []php.Value, strict bool) (php.Value, error) {")
	e.p("\t// **Some builtins are scope-sensitive.** `property_exists` reports a")
	e.p("\t// parent\"s private property when the *caller* is that parent and not")
	e.p("\t// when it is anyone else -- measured, including from a static method")
	e.p("\t// of the declaring class -- and `get_object_vars` shows what the")
	e.p("\t// calling scope can reach. They get a table of their own rather than")
	e.p("\t// the scope being threaded through every entry.")
	e.p("\t//")
	e.p("\t// Dispatched **below the frame push**, not above it: one of these is")
	e.p("\t// still a library function and owes the same frame. Returning early")
	e.p("\t// from here meant a property hook reached through `get_object_vars`")
	e.p("\t// was located at the call site rather than at `[internal function]`,")
	e.p("\t// because there was no internal frame beneath it to say so.")
	e.p("\t// **The undecided send is settled here.** A call whose callee is not")
	e.p("\t// resolved at compile time passes the caller's storage, because only")
	e.p("\t// the callee knows whether it wanted a reference -- so every")
	e.p("\t// receiving end has to take the value back out of the box, and this")
	e.p("\t// is the library surface's. The table of which positions really are")
	e.p("\t// by reference is the engine's own.")
	e.p("\targs = php.UnboxBuiltinArgs(name, args)")
	e.p("\t// **A library function gets a frame too, and gets it before its")
	e.p("\t// arguments are checked.** It is what a trace names when one of them")
	e.p("\t// throws -- `serialize(Object(Generator))` is the innermost line of")
	e.p("\t// that exception's stack -- and without it the throw appeared to come")
	e.p("\t// from the caller. The argument check raises the same way, so it is")
	e.p("\t// inside the frame too: `strtoupper('ab', 9)` opens its own")
	e.p("\t// ArgumentCountError. Marked internal, so a callback reached from")
	e.p("\t// here is located at `[internal function]` rather than at the call.")
	e.p("\tfile, line := ctx.Location()")
	e.p("\tctx.PushCall(php.StackFrame{Function: name, File: file, Line: line, Args: args})")
	e.p("\tctx.MarkInternalCall(name)")
	e.p("\tdefer ctx.PopCall()")
	e.p("\tif scoped, ok := scopedBuiltins[name]; ok {")
	e.p("\t\tv, err := scoped(ctx, scope, args)")
	e.p("\t\treturn v, php.AttachStack(ctx, err)")
	e.p("\t}")
	e.p("\t// The engine's own argument check, which runs **before** the")
	e.p("\t// function does: `str_repeat(\"a\", [])` is a TypeError, not \"\".")
	e.p("\tif err := verifyBuiltinArgs(ctx, name, args, strict); err != nil {")
	e.p("\t\treturn php.Value{}, err")
	e.p("\t}")
	e.p("\t// The class-introspection group is answered here, before the shared")
	e.p("\t// surface, because it needs the class table and runtime/php has none.")
	e.p("\tif fn, ok := classBuiltins[name]; ok {")
	e.p("\t\treturn fn(ctx, args)")
	e.p("\t}")
	e.p("\tfn, ok := php.LookupBuiltin(name)")
	e.p("\tif !ok {")
	e.p("\t\treturn php.Value{}, php.ThrowUndefinedFunction(name)")
	e.p("\t}")
	e.p("\tv, err := fn(ctx, args)")
	e.p("\t// Attached **here**, while the frame is still on the stack: the")
	e.p("\t// caller attaches too, but by then this frame has been popped and the")
	e.p("\t// trace would open at the caller rather than at the library function")
	e.p("\t// that threw. AttachStack keeps the first stack it is given.")
	e.p("\treturn v, php.AttachStack(ctx, err)")
	e.p("}")
	e.p("")
	e.p("// materialise turns a raised failure into a PHP exception object.")
	e.p("//")
	e.p("// runtime/php raises a *class and a message* rather than an object,")
	e.p("// because allocating one needs a handle and handles are this side's to")
	e.p("// number. So a `catch` has to construct it here, at the point it is")
	e.p("// caught, using the class the runtime named.")
	e.p("func materialise(ctx *php.Ctx, err error) (php.Value, bool) {")
	e.p("\t// **The generator-close unwind travels as an exception no clause can")
	e.p("\t// match.** Abandoning a suspended generator runs its `finally`")
	e.p("\t// blocks and nothing else -- PHP resumes it for that reason alone --")
	e.p("\t// so it has to reach the handler machinery, where every `instanceof`")
	e.p("\t// test fails and the unmatched-catch edge carries it out through the")
	e.p("\t// finally. Returning it as a plain Go error instead would leave the")
	e.p("\t// function immediately, skipping the very blocks it exists to run.")
	e.p("\t//")
	e.p("\t// The class name is one no program can declare, so no `catch` and no")
	e.p("\t// `instanceof` can name it -- `catch (Throwable)` included.")
	e.p("\tif errors.Is(err, php.ErrGeneratorClose) {")
	e.p("\t\treturn php.Obj(php.NewObject(php.GeneratorCloseClass, 0)), true")
	e.p("\t}")
	e.p("\tif o, ok := php.AsThrown(err); ok {")
	e.p("\t\treturn php.Obj(o), true")
	e.p("\t}")
	e.p("\tif class, message, ok := php.ThrowableFor(err); ok {")
	e.p("\t\t// The throwable records where it was **raised**. By the time this")
	e.p("\t\t// runs, `PopCall` has restored the caller's position, so reading")
	e.p("\t\t// the current location would name the call site -- which is where")
	e.p("\t\t// the trace's first frame belongs, not where the error happened.")
	e.p("\t\tif file, line, ok := php.RaisedAt(err); ok {")
	e.p("\t\t\tsaved, savedLine := ctx.Location()")
	e.p("\t\t\tctx.SetLocation(file, line)")
	e.p("\t\t\tdefer ctx.SetLocation(saved, savedLine)")
	e.p("\t\t}")
	e.p("\t\to := php.InitThrowable(ctx, php.NewObject(class, allocObjectID()), message, php.RaisedCode(err), php.Null())")
	e.p("\t\t// The stack **as it was when the error was raised**, when the")
	e.p("\t\t// raiser recorded one: by the time this runs, the frames it was")
	e.p("\t\t// raised inside have been popped on the way out.")
	e.p("\t\tif callee, ok := php.RaisedCallee(err); ok {")
	e.p("\t\t\t// Raised inside a call whose frame is gone: it is the trace's top.")
	e.p("\t\t\tfile, line := ctx.Location()")
	e.p("\t\t\tctx.PushCall(php.StackFrame{Function: callee, File: file, Line: line})")
	e.p("\t\t\tsetThrowableTrace(ctx, o, ctx.ExceptionTrace())")
	e.p("\t\t\tctx.PopCall()")
	e.p("\t\t} else if stack, ok := php.RaisedStack(err); ok {")
	e.p("\t\t\tsetThrowableTrace(ctx, o, stack)")
	e.p("\t\t} else {")
	e.p("\t\t\tsetThrowableTrace(ctx, o, ctx.ExceptionTrace())")
	e.p("\t\t}")
	e.p("\t\treturn php.Obj(o), true")
	e.p("\t}")
	e.p("\treturn php.Value{}, false")
	e.p("}")
	e.p("")
	e.p("// extendsClass reports whether `child` is `ancestor` or descends from it,")
	e.p("// by class *name*: visibility is decided between two named scopes, where")
	e.p("// `instanceOf` answers about a value.")
	e.p("// isThrowableObject walks this program's hierarchy up to an")
	e.p("// engine-defined throwable root, so a user class extending Exception")
	e.p("// counts as one.")
	e.p("func isThrowableObject(class string) bool {")
	e.p("\tfor c := class; c != \"\"; c = parentOf[c] {")
	e.p("\t\tif php.IsThrowableClass(c) {")
	e.p("\t\t\treturn true")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn false")
	e.p("}")
	e.p("")
	e.p("// extendsClass answers \"is child an ancestor\", **including through")
	e.p("// interfaces**. Walking `parentOf` alone was enough for property")
	e.p("// visibility -- an interface declares no properties -- but a class type")
	e.p("// declaration asks the same question of `f(Countable $c)`, and a")
	e.p("// parent-only walk would answer no for a class that implements it.")
	e.p("// classFieldsOrdered indexes a class's fields the way the engine lists")
	e.p("// them: the class's **own** declarations first, then each ancestor's in")
	e.p("// turn. The harvest flattens the table parent-first, which is the order")
	e.p("// an instance carries and the opposite of this one.")
	e.p("func classFieldsOrdered(class string) []int {")
	e.p("\tfields := classFields[class]")
	e.p("\ttaken := make([]bool, len(fields))")
	e.p("\torder := make([]int, 0, len(fields))")
	e.p("\tfor c := class; c != \"\"; c = parentOf[c] {")
	e.p("\t\tfor i := range fields {")
	e.p("\t\t\tif !taken[i] && strings.EqualFold(fields[i].owner, c) {")
	e.p("\t\t\t\ttaken[i] = true")
	e.p("\t\t\t\torder = append(order, i)")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\t// An owner that is not on the parent chain -- a trait's -- keeps its")
	e.p("\t// place at the end rather than being dropped.")
	e.p("\tfor i := range fields {")
	e.p("\t\tif !taken[i] {")
	e.p("\t\t\torder = append(order, i)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn order")
	e.p("}")
	e.p("")
	e.p("// classVarSlot finds the slot a declared property occupies on an")
	e.p("// instance. A private with more than one declarer is keyed by its owner,")
	e.p("// and a protected by `*`, so the plain name is the last thing tried.")
	e.p("func classVarSlot(o *php.Object, name, owner string) (string, php.Value, bool) {")
	e.p("\tfor _, key := range []string{\"\\x00\" + owner + \"\\x00\" + name, \"\\x00*\\x00\" + name, name} {")
	e.p("\t\tif v, ok := o.PropGet(php.StringKey(key)); ok {")
	e.p("\t\t\treturn key, v, true")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn \"\", php.Value{}, false")
	e.p("}")
	e.p("")
	e.p("func extendsClass(child, ancestor string) bool {")
	e.p("\t// A declared type may name an alias (`: AliasA`), which is its class.")
	e.p("\tancestor = resolveAlias(ancestor)")
	e.p("\tfor c := child; c != \"\"; c = parentOf[c] {")
	e.p("\t\tif strings.EqualFold(c, ancestor) {")
	e.p("\t\t\treturn true")
	e.p("\t\t}")
	e.p("\t\tif implementsInterface(c, ancestor) {")
	e.p("\t\t\treturn true")
	e.p("\t\t}")
	e.p("\t\t// **The engine's exception hierarchy** is runtime/php's, not in")
	e.p("\t\t// this program's tables: a `Throwable $e` parameter given an")
	e.p("\t\t// `Exception`, or a class extending `RuntimeException` checked")
	e.p("\t\t// against `Exception`, is answered there.")
	e.p("\t\tif php.IsThrowableClass(c) && php.ThrowableIsA(c, ancestor) {")
	e.p("\t\t\treturn true")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn false")
	e.p("}")
	e.p("")
	e.p("// visible asks the shared intrinsic. The *rule* is value-level --")
	e.p("// it reads Object.Declared and a scope name -- so it lives in")
	e.p("// runtime/php; only the hierarchy question needs this program's")
	e.p("// class table, and that arrives through the SubclassOf hook.")
	e.p("func visible(ctx *php.Ctx, o *php.Object, name, scope string) (bool, bool) {")
	e.p("\tswitch php.CheckPropertyRead(ctx, o, name, scope) {")
	e.p("\tcase php.PropertyReachable:")
	e.p("\t\treturn true, false")
	e.p("\tcase php.PropertyInvisible:")
	e.p("\t\treturn false, true")
	e.p("\t}")
	e.p("\treturn false, false")
	e.p("}")
	e.p("")
	// Place constructors, so `prop.ref`, `dim.ref` and `dim.append` are calls
	// in the IR like every other operation. They are the generated unit's own
	// helpers rather than runtime/php functions because `place` is this
	// program's type -- a write target knows about this unit's classes.
	// The runtime asks the program for anything needing the class table. These
	// are the same two questions the interpreter answers its own way, which is
	// the point of the hooks: one implementation of the *rule*, two of the
	// lookup.
	e.p("// unmodelledStringables are the engine classes whose `__toString` php2go")
	e.p("// does not render.")
	e.p("var unmodelledStringables = []string{")
	e.p("\t\"ReflectionClass\", \"ReflectionFunction\", \"ReflectionMethod\", \"ReflectionParameter\",")
	e.p("\t\"ReflectionProperty\", \"ReflectionClassConstant\", \"ReflectionExtension\",")
	e.p("\t\"ReflectionZendExtension\", \"ReflectionAttribute\", \"ReflectionConstant\",")
	e.p("}")
	e.p("")
	e.p("// throwableString is the engine's Exception::__toString: the chain")
	e.p("// rendered, and **kept in the root's private `string` property** --")
	e.p("// var_export of the exception shows it afterwards (bug73350). Only the")
	e.p("// outer exception keeps it; the ones it wraps stay empty (probed).")
	e.p("func throwableString(o *php.Object) php.Value {")
	e.p("\ts := php.String(php.ThrowableChainString(o))")
	e.p("\to.PropSet(php.StringKey(php.MangleProperty(php.ObjectThrowableRoot(o), \"string\")), s)")
	e.p("\treturn s")
	e.p("}")
	e.p("")
	e.p("func objectToString(ctx *php.Ctx, o *php.Object) (php.Value, bool, error) {")
	e.p("\t{")
	e.p("\t\tif hasMethod(o.ClassName, \"__tostring\") {")
	e.p("\t\t\t// A user override wins, including on a class extending")
	e.p("\t\t\t// Exception.")
	e.p("\t\t\tv, err := callMethod(ctx, php.Obj(o), \"__tostring\", nil)")
	e.p("\t\t\treturn v, true, err")
	e.p("\t\t}")
	e.p("\t\tif isThrowableObject(o.ClassName) {")
	e.p("\t\t\t// `Exception::__toString` is the engine's, not a method the")
	e.p("\t\t\t// program declares, and runtime/php already renders it --")
	e.p("\t\t\t// class, message, file, line and the trace. Without this,")
	e.p("\t\t\t// `echo $e` said the object could not be converted to a")
	e.p("\t\t\t// string, which is what PHP says for a class that is NOT a")
	e.p("\t\t\t// Throwable, so the diagnostic was doubly wrong.")
	e.p("\t\t\t// Through the method, whose frame a conversion failure's")
	e.p("\t\t\t// trace names: `#0 f.php(6): Exception->__toString()`.")
	e.p("\t\t\tv, err := callMethod(ctx, php.Obj(o), \"__tostring\", nil)")
	e.p("\t\t\treturn v, true, err")
	e.p("\t\t}")
	// **The reflectors' own `__toString` is a gap, not a PHP error**: the
	// engine prints a multi-line export of the class or function, which is
	// not modelled, and saying the object cannot be converted graded a
	// missing feature as a wrong answer (ctor_promotion_mixing, bug43200).
	e.p("\t\tif r, isReflector := o.Internal.(*reflector); isReflector {")
	e.p("\t\t\tif text, ok := reflectorString(ctx, r); ok {")
	e.p("\t\t\t\treturn php.String(text), true, nil")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\tfor _, class := range unmodelledStringables {")
	e.p("\t\t\tif instanceOf(php.Obj(o), class) {")
	e.p("\t\t\t\treturn php.Null(), false, php.Unsupported(\"%%s::__toString\", class)")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\treturn php.Null(), false, nil")
	e.p("\t}")
	e.p("}")
	e.p("")
	e.p("func countObject(ctx *php.Ctx, o *php.Object) (php.Value, bool, error) {")
	e.p("\tif !hasMethod(o.ClassName, \"count\") {")
	e.p("\t\treturn php.Null(), false, nil")
	e.p("\t}")
	e.p("\tv, err := callMethod(ctx, php.Obj(o), \"count\", nil)")
	e.p("\treturn v, true, err")
	e.p("}")
	e.p("")
	e.p("// propPlaceRW is the **read-write** property fetch. The place is the same")
	e.p("// one; the flag says the container is being read as well as written, and")
	e.p("// a read-write fetch reads *before* it refuses: `$t->prop->prop += 1` on")
	e.p("// an uninitialized `readonly Inner $prop` reports the property as")
	e.p("// uninitialized, where `$t->prop->prop = 0` refuses the modification.")
	e.p("// propPlaceUnset is the **unset** property fetch. An uninitialized")
	e.p("// property has nothing to refuse about: `unset($t->prop->prop)` on an")
	e.p("// uninitialized `readonly Inner $prop` is allowed, where the write fetch")
	e.p("// refuses the modification.")
	e.p("func propPlaceUnset(recv php.Value, name, scope string) place {")
	e.p("	return place{recv: recv, name: name, scope: scope, unsetting: true}")
	e.p("}")
	e.p("")
	e.p("func propPlaceRW(recv php.Value, name, scope string) place {")
	e.p("	return place{recv: recv, name: name, scope: scope, rw: true}")
	e.p("}")
	e.p("")
	e.p("func propPlace(recv php.Value, name, scope string) place {")
	e.p("\treturn place{recv: recv, name: name, scope: scope}")
	e.p("}")
	e.p("")
	// Unlike the other place builders this one can **fail**: an undeclared
	// static property is an Error, and the lookup is where that is found. So it
	// takes the ctx and returns an error where `dimPlace` and `propPlace` are
	// total.
	e.p("func staticPlace(ctx *php.Ctx, name, class, scope string) (place, error) {")
	e.p("\tslot, err := staticSlot(ctx, class, name, scope)")
	e.p("\tif err != nil {")
	e.p("\t\treturn place{}, err")
	e.p("\t}")
	e.p("\towner := class")
	e.p("\tfor c := class; c != \"\"; c = parentOf[c] {")
	e.p("\t\tif o, ok := declaresStatic[c][name]; ok {")
	e.p("\t\t\towner = o")
	e.p("\t\t\tbreak")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn place{slot: slot, direct: true, sclass: owner, sname: name}, nil")
	e.p("}")
	e.p("")
	e.p("func dimPlace(slot *php.Value, key php.Value) place {")
	e.p("\treturn place{slot: slot, key: key}")
	e.p("}")
	e.p("")
	e.p("// dimPlaceRW is the **read-write** dimension fetch. It differs from")
	e.p("// dimPlace in what it says about an undefined container and in what it")
	e.p("// leaves behind: `$y[\"k\"] .= \"s\"` on an undefined `$y` warns")
	e.p("// `Undefined variable $y`, **autovivifies** it to an array so the key")
	e.p("// read that follows warns `Undefined array key \"k\"` rather than")
	e.p("// `Trying to access array offset on null`, and only then reads.")
	e.p("//")
	e.p("// `name` is the container's spelling, empty when it is not a named")
	e.p("// variable -- a nested fetch, whose container is another place.")
	e.p("func dimPlaceRW(ctx *php.Ctx, slot *php.Value, key php.Value) place {")
	e.p("\t// Autovivifies **before** the read that follows, so the key read")
	e.p("\t// says `Undefined array key \"k\"` rather than")
	e.p("\t// `Trying to access array offset on null`. The container's own")
	e.p("\t// warning is emitted at the call site, before the key is evaluated.")
	e.p("\tif slot.IsUndef() || slot.Kind() == php.KindNull {")
	e.p("\t\t*slot = php.Arr(php.NewArray())")
	e.p("\t} else if r, isRef := slot.RefOf(); isRef && len(r.Sources()) == 0 {")
	e.p("\t\t// **Through a reference too**: `$v[0] .= \"x\"` on a null `$v` a")
	e.p("\t\t// closure captured by reference warns `Undefined array key 0`, not")
	e.p("\t\t// `Trying to access array offset on null`. One a typed property")
	e.p("\t\t// holds is left to the reach, which refuses what the type does not")
	e.p("\t\t// admit.")
	e.p("\t\tif inner := r.Slot(); inner != nil && (inner.IsUndef() || inner.Kind() == php.KindNull) {")
	e.p("\t\t\t*inner = php.Arr(php.NewArray())")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\t// **The key is converted once**, at the fetch: a resource or a float")
	e.p("\t// offset warns there and not again for the read and the write that")
	e.p("\t// follow (resource_key). Only into an array -- an ArrayAccess object")
	e.p("\t// is handed the key as it is.")
	e.p("\tif k := key.Deref(); slot.Deref().Kind() == php.KindArray && (k.Kind() == php.KindResource || k.Kind() == php.KindFloat) {")
	e.p("\t\tif ak := php.ArrayKey(ctx, k); ak.IsInt {")
	e.p("\t\t\tkey = php.Int(ak.Int)")
	e.p("\t\t} else {")
	e.p("\t\t\tkey = php.String(ak.Str)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn place{slot: slot, key: key, rw: true}")
	e.p("}")
	e.p("")
	e.p("func appendPlace(slot *php.Value) place {")
	e.p("\treturn place{slot: slot, append: true}")
	e.p("}")
	e.p("")
	// `silent` is the IS access mode: `$o->missing ?? "d"` must not warn, and
	// must answer **not set** rather than null so the coalesce takes its right
	// side. The mode was on the instruction and never reached here, so every
	// `??` over a property warned where PHP says nothing.
	// The two modes are two intrinsics, so the generated unit exposes two
	// functions. They share one body because the difference is genuinely a
	// branch inside it -- what must not be shared is the *name*, since the
	// catalogue's effect contract differs: the loud form warns, the silent one
	// only throws.
	e.p("func propGet(ctx *php.Ctx, recv php.Value, name, scope string) (php.Value, error) {")
	e.p("\treturn propGetMode(ctx, recv, name, scope, false, false)")
	e.p("}")
	e.p("")
	e.p("func propGetSilent(ctx *php.Ctx, recv php.Value, name, scope string) (php.Value, error) {")
	e.p("\treturn propGetMode(ctx, recv, name, scope, true, true)")
	e.p("}")
	e.p("")
	e.p("// propGetFetch is the quiet read a **write fetch** makes of its")
	e.p("// container -- `$o->p->q = 1` reading `$o->p`. It goes straight to")
	e.p("// `__get`: only an isset fetch asks `__isset` first (zend_std_read_")
	e.p("// property, BP_VAR_IS), and asking it here answered false and read the")
	e.p("// container as null (bug71359).")
	e.p("func propGetFetch(ctx *php.Ctx, recv php.Value, name, scope string) (php.Value, error) {")
	e.p("\treturn propGetMode(ctx, recv, name, scope, true, false)")
	e.p("}")
	e.p("")
	e.p("// issetBeforeGet is the quiet read's first question: a class with")
	e.p("// `__isset` is asked whether an unreachable name is set, and a false")
	e.p("// answer is the read's null -- `$o->x ?? d` and `$o->x ??= v` never reach")
	e.p("// `__get` then. answered is false when there is no `__isset` to ask or")
	e.p("// it said yes, and the caller goes on to `__get`.")
	e.p("// magicUsable is whether o's class has the accessor and it is not")
	e.p("// already running for this name on this object -- the guard that makes")
	e.p("// an accessor reaching its own property read the table instead.")
	e.p("func magicUsable(o *php.Object, method, name string) bool {")
	e.p("\treturn hasMethod(o.ClassName, method) && !magicInFlight[[3]any{php.GuardOf(o), method, name}]")
	e.p("}")
	e.p("")
	e.p("func issetBeforeGet(ctx *php.Ctx, o *php.Object, name string) (bool, php.Value, error) {")
	e.p("\tv, handled, err := magic(ctx, o, \"__isset\", name, []php.Value{php.String(name)})")
	e.p("\tif !handled {")
	e.p("\t\treturn false, php.Value{}, nil")
	e.p("\t}")
	e.p("\tif err != nil {")
	e.p("\t\treturn true, php.Value{}, err")
	e.p("\t}")
	e.p("\tif !v.Deref().Bool() {")
	e.p("\t\treturn true, php.Value{}, nil")
	e.p("\t}")
	e.p("\treturn false, php.Value{}, nil")
	e.p("}")
	e.p("")
	e.p("func propGetMode(ctx *php.Ctx, recv php.Value, name, scope string, silent, askIsset bool) (php.Value, error) {")
	e.p("\tif recv.Kind() != php.KindObject {")
	e.p("\t\tif silent {")
	e.p("\t\t\treturn php.Value{}, nil")
	e.p("\t\t}")
	e.p("\t\tctx.WarnPropertyOnNonObject(name, recv)")
	e.p("\t\treturn php.Null(), nil")
	e.p("\t}")
	e.p("\to := recv.Object()")
	e.p("\t// An incomplete object's read handler warns and reads NULL, for a")
	e.p("\t// plain read, isset, empty and `??` alike (runtime/php incomplete.go).")
	e.p("\tif php.IsIncomplete(o) {")
	e.p("\t\treturn php.IncompleteReadWarning(ctx, o)")
	e.p("\t}")
	e.p("\t// **The fast path**: a public, unhooked, declared property holding a")
	e.p("\t// value, on a class with no hooks and an object that is neither lazy")
	e.p("\t// nor shadowing a private. Every step below would pass it straight")
	e.p("\t// through -- visibility, hooks, __get (only for what is absent or")
	e.p("\t// hidden), the uninitialized check (only for undef).")
	e.p("\tif o.PlainAccess && o.Lazy == nil && len(o.Shadowed) == 0 {")
	e.p("\t\tif d, ok := o.Declared[name]; ok && d.Plain {")
	e.p("\t\t\tif v, ok := o.Get(name); ok && !v.IsUndef() {")
	e.p("\t\t\t\treturn v, nil")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\t// **A lazy object produces its state here**, before the read reaches")
	e.p("\t// it -- and for a proxy the object that holds the state is the")
	e.p("\t// instance behind it, not the one the program is holding. An isset")
	e.p("\t// read of an undeclared name asks `__isset` first, on the stand-in")
	e.p("\t// and before anything is initialised (gh18038-005, probed).")
	e.p("\t// One already running for the name is not asked again: inside")
	e.p("\t// `__isset`, `isset($this->$name[...])` goes to `__get` (gh18038-006).")
	e.p("\tlazyMagic := \"__get\"")
	e.p("\tif askIsset && o.Lazy != nil && magicUsable(o, \"__isset\", name) {")
	e.p("\t\tlazyMagic = \"__isset\"")
	e.p("\t}")
	e.p("\tif resolved, err := lazyResolved(ctx, o, name, lazyMagic); err != nil {")
	e.p("\t\treturn php.Value{}, err")
	e.p("\t} else {")
	e.p("\t\to = resolved")
	e.p("\t}")
	e.p("\t// **The source name, before mangling.** propertySlot rewrites a")
	e.p("\t// shadowed private property to the engine's own `\\0Class\\0name`")
	e.p("\t// key, so asking the NUL question of the *slot* would refuse every")
	e.p("\t// legitimate access to one. The rule is about what the program")
	e.p("\t// wrote.")
	e.p("\tgiven := name")
	e.p("\tname = propertySlot(o, name, scope)")
	e.p("\t// The mirror: a hooked property with **no get hook** is write-only,")
	e.p("\t// except from inside its own set hook.")
	e.p("\t// A hook is filed under the property's plain name, while a shadowed")
	e.p("\t// private's slot is the object's mangled key for it -- the parent's")
	e.p("\t// and the class's own alike (property_hooks/dump).")
	e.p("\towner := hookOwner(o, given, scope)")
	e.p("\thooks := propHooks[owner]")
	e.p("\thookKey := name")
	e.p("\tif _, filed := hooks[hookKey]; !filed {")
	e.p("\t\thookKey = given")
	e.p("\t}")
	e.p("\tif h, ok := hooks[hookKey]; ok && h.get == nil && h.virtual {")
	e.p("\t\tif !magicInFlight[[3]any{php.GuardOf(o), \"hook.set\", name}] {")
	e.p("\t\t\treturn php.Value{}, php.Raise(\"Error\", \"Property %%s::$%%s is write-only\", o.ClassName, name)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\t// **Inside either of its hooks the property is its backing field**,")
	e.p("\t// for reading and writing alike: a set hook reading `$this->prop`")
	e.p("\t// sees the field and does not run the get hook (field_guard).")
	e.p("\tif h, ok := hooks[hookKey]; ok && h.get != nil && !magicInFlight[[3]any{php.GuardOf(o), \"hook.set\", name}] {")
	e.p("\t\tkey := [3]any{php.GuardOf(o), \"hook.get\", name}")
	e.p("\t\tif !magicInFlight[key] {")
	e.p("\t\t\tmagicInFlight[key] = true")
	e.p("\t\t\tdefer delete(magicInFlight, key)")
	e.p("\t\t\treturn hookFramed(ctx, h, o, name, \"get\", nil, func() (php.Value, error) {")
	e.p("\t\t\t\treturn h.get(ctx, o, nil)")
	e.p("\t\t\t})")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tif ok, invisible := visible(ctx, o, name, scope); !ok {")
	e.p("\t\tif askIsset {")
	e.p("\t\t\tif answered, v, err := issetBeforeGet(ctx, o, name); answered {")
	e.p("\t\t\t\treturn v, err")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\t// `__get` answers for exactly what ordinary access could not")
	e.p("\t\t// reach: inaccessible *or* absent. Checked against the engine --")
	e.p("\t\t// a private property read from outside runs the hook, and the")
	e.p("\t\t// same read from inside does not.")
	e.p("\t\tif v, handled, err := magic(ctx, o, \"__get\", name, []php.Value{php.String(name)}); handled {")
	e.p("\t\t\treturn v.Deref(), err")
	e.p("\t\t}")
	e.p("\t\t// **Silent first**: `isset($a->priv)` and `$a->priv ?? \"d\"` from")
	e.p("\t\t// outside are false and \"d\", not an Error. Only the loud read")
	e.p("\t\t// refuses. Asked of the engine after a rebound closure -- which")
	e.p("\t\t// reads an inaccessible property through `??` on purpose -- turned")
	e.p("\t\t// a working expression into a fatal.")
	e.p("\t\tif silent {")
	e.p("\t\t\treturn php.Value{}, nil")
	e.p("\t\t}")
	e.p("\t\t// **After __get, not before.** A class with the magic method")
	e.p("\t\t// answers a NUL-prefixed name and never reaches the table; one")
	e.p("\t\t// without it would read the engine's private namespace, where")
	e.p("\t\t// mangled private slots live, and is refused.")
	e.p("\t\tif php.IsNulProperty(given) {")
	e.p("\t\t\treturn php.Value{}, php.ThrowNulProperty()")
	e.p("\t\t}")
	e.p("\t\tif !invisible {")
	e.p("\t\t\treturn php.Value{}, php.ThrowInaccessibleProperty(o.ClassName, o.Declared[name].Visibility, name)")
	e.p("\t\t}")
	e.p("\t\tstaticAsNonStatic(ctx, o, name)")
	e.p("\t\tctx.WarnUndefinedProperty(o.ClassName, name)")
	e.p("\t\treturn php.Null(), nil")
	e.p("\t}")
	e.p("\tv, ok := o.Get(name)")
	e.p("\tif !ok {")
	e.p("\t\tif askIsset {")
	e.p("\t\t\tif answered, v, err := issetBeforeGet(ctx, o, name); answered {")
	e.p("\t\t\t\treturn v, err")
	e.p("\t\t\t}")
	e.p("\t\t\t// `__isset` said yes on a stand-in still lazy: with no `__get`")
	e.p("\t\t\t// to answer, the state is produced now and the read goes on")
	e.p("\t\t\t// there -- without asking `__isset` a second time.")
	e.p("\t\t\tif o.Lazy != nil && !magicUsable(o, \"__get\", given) {")
	e.p("\t\t\t\tresolved, err := lazyResolved(ctx, o, given, \"\")")
	e.p("\t\t\t\tif err != nil {")
	e.p("\t\t\t\t\treturn php.Value{}, err")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\tif resolved != o {")
	e.p("\t\t\t\t\treturn propGetMode(ctx, php.Obj(resolved), given, scope, silent, false)")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\tif v, handled, err := magic(ctx, o, \"__get\", name, []php.Value{php.String(name)}); handled {")
	e.p("\t\t\treturn v.Deref(), err")
	e.p("\t\t}")
	e.p("\t\tif silent {")
	e.p("\t\t\treturn php.Value{}, nil")
	e.p("\t\t}")
	e.p("\t\tif php.IsNulProperty(given) {")
	e.p("\t\t\treturn php.Value{}, php.ThrowNulProperty()")
	e.p("\t\t}")
	e.p("\t\tstaticAsNonStatic(ctx, o, name)")
	e.p("\t\tctx.WarnUndefinedProperty(o.ClassName, name)")
	e.p("\t\treturn php.Null(), nil")
	e.p("\t}")
	e.p("\tif v.IsUndef() {")
	e.p("\t\t// **An untyped slot holding undef was unset**, since an untyped")
	e.p("\t\t// declaration is never uninitialized: it reads as absent --")
	e.p("\t\t// `__get`, or `Undefined property` -- and the Error below is only")
	e.p("\t\t// for a typed one. Measured: `unset($t->u); echo $t->u;` warns.")
	e.p("\t\t// A **typed** one reads as absent too once unset() removed it --")
	e.p("\t\t// `unset($o->typed); $o->typed` asks `__get` -- where one never")
	e.p("\t\t// assigned is the uninitialized Error.")
	e.p("\t\tif d, declared := o.Declared[name]; declared && (d.Type == \"\" || o.WasCleared(name)) {")
	e.p("\t\t\tif v, handled, err := magic(ctx, o, \"__get\", name, []php.Value{php.String(name)}); handled {")
	e.p("\t\t\t\tif err != nil || d.Type == \"\" {")
	e.p("\t\t\t\t\treturn v.Deref(), err")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\t// What `__get` answers for an unset typed property must fit")
	e.p("\t\t\t\t// its type, coerced as an assignment would be.")
	e.p("\t\t\t\tcv, cerr := php.CoerceProperty(ctx, v.Deref(), d.Type, d.Class, name, false)")
	e.p("\t\t\t\tif cerr != nil {")
	e.p("\t\t\t\t\treturn php.Value{}, php.RaiseAt(ctx, \"TypeError\", \"Value of type %%s returned from %%s::__get() must be compatible with unset property %%s::$%%s of type %%s\",")
	e.p("\t\t\t\t\t\tphp.TypeName(v.Deref()), php.DisplayName(o.ClassName), php.DisplayName(d.Class), name, d.Type)")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\treturn cv, nil")
	e.p("\t\t\t}")
	e.p("\t\t\t// With no `__get` to answer, a typed one is still the")
	e.p("\t\t\t// uninitialized Error below; only an untyped one is absent.")
	e.p("\t\t\tif d.Type == \"\" {")
	e.p("\t\t\t\tif silent {")
	e.p("\t\t\t\t\treturn php.Value{}, nil")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\tctx.WarnUndefinedProperty(o.ClassName, name)")
	e.p("\t\t\t\treturn php.Null(), nil")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\t// **A silent read answers not-set rather than refusing.**")
	e.p("\t\t// `$t->prop ?? \"d\"` and `isset($t->prop->prop)` on an")
	e.p("\t\t// uninitialized typed property are \"d\" and false; only the loud")
	e.p("\t\t// read is `Typed property T::$prop must not be accessed before")
	e.p("\t\t// initialization`.")
	e.p("\t\tif silent {")
	e.p("\t\t\treturn php.Value{}, nil")
	e.p("\t\t}")
	e.p("\t\t// The **declaring** class: `class B extends A` with `A` declaring")
	e.p("\t\t// the typed property reports `A::$t`. `runtime/php`'s")
	e.p("\t\t// ReadDeclaredProp says the same thing -- this is the second copy")
	e.p("\t\t// of one rule, and fixing only the other one left this path wrong.")
	e.p("\t\towner := o.ClassName")
	e.p("\t\tif d, declared := o.Declared[name]; declared && d.Class != \"\" {")
	e.p("\t\t\towner = d.Class")
	e.p("\t\t}")
	e.p("\t\treturn php.Value{}, php.ThrowUninitializedProperty(owner, name)")
	e.p("\t}")
	e.p("\t// The notice fires on **every** loud read of a name the class declares")
	e.p("\t// static, not only the one that finds nothing: once a write has")
	e.p("\t// created a dynamic property of that name, reading it still notices")
	e.p("\t// and still answers the dynamic value. `__get` is the one thing that")
	e.p("\t// suppresses it, and it has already returned by here.")
	e.p("\tif !silent {")
	e.p("\t\tif _, declared := o.Declared[name]; !declared {")
	e.p("\t\t\tstaticAsNonStatic(ctx, o, name)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn v, nil")
	e.p("}")
	e.p("")
	e.p("// Source paths below are relative to the compilation root; sourceRootPolicy")
	e.p("// says how that root was chosen. The root itself is a build-machine path and")
	e.p("// is deliberately not recorded.")
	e.p("const sourceRootPolicy = %q", p.RootPolicy)
	e.p("const sourceEntry = %q", p.EntryFile)
	e.p("const compileDiagnostic = %q", p.CompileDiagnostic)
	e.p("")
	e.p("// declaredClasses is which class names are currently bound.")
	e.p("//")
	e.p("// A class declared unconditionally is bound before the program runs; one")
	e.p("// declared inside a branch is bound only when its `declare_class` runs,")
	e.p("// and `new` of an unbound name is the engine's `Class \"X\" not found`.")
	e.p("// classNeeds is what a **conditionally** declared class must have bound")
	e.p("// before it can be: its parent and its interfaces. The engine links a")
	e.p("// class at its declaration point, and linking autoloads -- `class B")
	e.p("// extends A` inside an autoloader loads A from inside the load of B.")
	e.p("// engineInterfaceSet is the interfaces the engine provides, which no")
	e.p("// program declares and so which `realClass` never answers for.")
	e.p("var engineInterfaceSet = map[string]bool{")
	{
		names := make([]string, 0, len(engineInterfaces))
		for n := range engineInterfaces {
			names = append(names, n)
		}
		sort.Strings(names)
		for _, n := range names {
			e.p("\t%q: true,", n)
		}
	}
	e.p("}")
	e.p("")
	// **The variance checks linking runs**, for a class declared at run
	// time: the engine could not decide them when it compiled the class,
	// because a class they name was not there yet (variance/
	// class_order_autoload_error*). Only overrides whose two signatures are
	// plain enough to spell -- see varianceChecks.
	e.p("var classVariance = map[string][]struct {")
	e.p("\tsub, super, child, parent string")
	e.p("\tline                     uint32")
	e.p("}{")
	for _, c := range p.Classes {
		if !conditional[strings.ToLower(c.Name)] {
			continue
		}
		// A check naming an engine class or interface is the engine's own
		// to have made: it is always there, and this program's tables do
		// not know its hierarchy (variance/stringable).
		var checks []varianceCheck
		for _, v := range varianceChecks(byName, c) {
			if !e.engineProvides(v.sub) && !e.engineProvides(v.super) {
				checks = append(checks, v)
			}
		}
		if len(checks) == 0 {
			continue
		}
		e.p("\t%q: {", strings.ToLower(c.Name))
		for _, v := range checks {
			e.p("\t\t{%q, %q, %q, %q, %d},", v.sub, v.super, v.child, v.parent, v.line)
		}
		e.p("\t},")
	}
	e.p("}")
	e.p("")
	e.p("// checkVariance runs a class's variance checks once what they name has")
	e.p("// been loaded: a class still not there is `Could not check")
	e.p("// compatibility`, one that is not a subtype is `Declaration of ... must")
	e.p("// be compatible with ...`, both fatal where the class is declared.")
	e.p("//")
	e.p("// A class **still being declared** -- its own declaration is what")
	e.p("// loaded this one -- is not missing: what it declares it extends and")
	e.p("// implements answers the question (class_order_autoload1,")
	e.p("// infinite_recursion).")
	e.p("//")
	e.p("// Run **as each delayed load arrives**, a check whose classes are both")
	e.p("// there is asked then -- the engine fails `m(): X` as soon as X is")
	e.p("// loaded, before it loads what `m2()` names (class_order_autoload_error8)")
	e.p("// -- and `final` asks the rest once the loads are done.")
	e.p("func checkVariance(ctx *php.Ctx, name string) error {")
	e.p("\treturn checkVarianceStep(ctx, name, map[int]bool{}, true)")
	e.p("}")
	e.p("")
	e.p("func checkVarianceStep(ctx *php.Ctx, name string, done map[int]bool, final bool) error {")
	e.p("\tfor i, v := range classVariance[name] {")
	e.p("\t\tif done[i] {")
	e.p("\t\t\tcontinue")
	e.p("\t\t}")
	e.p("\t\t// An alias names its class (bug54624, bug76451).")
	e.p("\t\tif v.super != \"\" {")
	e.p("\t\t\tv.sub, v.super = resolveAlias(v.sub), resolveAlias(v.super)")
	e.p("\t\t}")
	e.p("\t\t// `static` against a class is never compatible (gh9407).")
	e.p("\t\tif v.super == \"\" {")
	e.p("\t\t\tdone[i] = true")
	e.p("\t\t\tif file, _ := ctx.Location(); v.line > 0 {")
	e.p("\t\t\t\tctx.SetLocation(file, v.line)")
	e.p("\t\t\t}")
	e.p("\t\t\treturn fatalAt(ctx, fmt.Sprintf(\"Declaration of %%s must be compatible with %%s\", v.child, v.parent))")
	e.p("\t\t}")
	e.p("\t\t// **A class whose link is under way and cannot finish** is asked")
	e.p("\t\t// as the engine's unlinked_instanceof asks: by the parent and")
	e.p("\t\t// interfaces its declaration names, looked up without autoloading.")
	e.p("\t\t// Answered yes, the check now depends on that class")
	e.p("\t\t// (track_class_dependency), whose failure then cannot be undone")
	e.p("\t\t// (declareFailingClass; variance/loading_exception1); answered no,")
	e.p("\t\t// it is incompatible at once (probed).")
	e.p("\t\tif a, b := strings.ToLower(v.sub), strings.ToLower(v.super); failingDeclaring[a] || failingDeclaring[b] {")
	e.p("\t\t\tdone[i] = true")
	e.p("\t\t\tif a != b {")
	e.p("\t\t\t\tif !unlinkedInstanceof(a, b, map[string]bool{}) {")
	e.p("\t\t\t\t\tif file, _ := ctx.Location(); v.line > 0 {")
	e.p("\t\t\t\t\t\tctx.SetLocation(file, v.line)")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\t\treturn fatalAt(ctx, fmt.Sprintf(\"Declaration of %%s must be compatible with %%s\", v.child, v.parent))")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\tfor _, n := range []string{a, b} {")
	e.p("\t\t\t\t\tif failingDeclaring[n] {")
	e.p("\t\t\t\t\t\tvarianceDependents[n] = true")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\tcontinue")
	e.p("\t\t}")
	e.p("\t\tknown := func(n string) bool { l := strings.ToLower(n); return declaredClasses[l] || declaringClasses[l] }")
	e.p("\t\tready := known(v.sub) && known(v.super)")
	e.p("\t\tif !ready && !final {")
	e.p("\t\t\tcontinue")
	e.p("\t\t}")
	e.p("\t\tdone[i] = true")
	e.p("\t\t// Reported on the overriding method's line (probed).")
	e.p("\t\tif file, _ := ctx.Location(); v.line > 0 {")
	e.p("\t\t\tctx.SetLocation(file, v.line)")
	e.p("\t\t}")
	e.p("\t\tfor _, n := range []string{v.sub, v.super} {")
	e.p("\t\t\tif low := strings.ToLower(n); !declaredClasses[low] && !declaringClasses[low] {")
	e.p("\t\t\t\treturn fatalAt(ctx, fmt.Sprintf(\"Could not check compatibility between %%s and %%s, because class %%s is not available\", v.child, v.parent, n))")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\t// By declared spelling, which the hierarchy tables key on even for a")
	e.p("\t\t// class whose declaration is still under way.")
	e.p("\t\tspell := func(n string) string {")
	e.p("\t\t\tif s, ok := classSpelling[strings.ToLower(n)]; ok {")
	e.p("\t\t\t\treturn s")
	e.p("\t\t\t}")
	e.p("\t\t\treturn n")
	e.p("\t\t}")
	e.p("\t\tif !extendsClass(spell(v.sub), spell(v.super)) {")
	e.p("\t\t\treturn fatalAt(ctx, fmt.Sprintf(\"Declaration of %%s must be compatible with %%s\", v.child, v.parent))")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn nil")
	e.p("}")
	e.p("")
	e.p("// declaringClasses are the classes whose declaration is under way.")
	e.p("var declaringClasses = map[string]bool{}")
	e.p("")
	e.p("// classNeedRT is a name a failing declaration resolves, with the kind")
	e.p("// its \"not found\" message uses.")
	e.p("type classNeedRT struct{ name, kind string }")
	e.p("")
	e.p("// failingDeclaring are the declarations under way that were proven")
	e.p("// unable to finish, and varianceDependents those a variance check has")
	e.p("// since tied up.")
	e.p("var failingDeclaring = map[string]bool{}")
	e.p("")
	e.p("// failingNeeds is what each failing declaration under way names.")
	e.p("var failingNeeds = map[string][]classNeedRT{}")
	e.p("")
	e.p("// unlinkedInstanceof is zend_inheritance's unlinked_instanceof for a")
	e.p("// failing declaration under way: its named parent and interfaces are")
	e.p("// looked up without autoloading -- a class that is declared answers")
	e.p("// through the linked hierarchy, one that is not there is passed over.")
	e.p("func unlinkedInstanceof(sub, super string, seen map[string]bool) bool {")
	e.p("\tif sub == super {")
	e.p("\t\treturn true")
	e.p("\t}")
	e.p("\tif !failingDeclaring[sub] {")
	e.p("\t\tif c := realClass(sub); c != \"\" && declaredClasses[sub] {")
	e.p("\t\t\treturn extendsClass(c, resolveAlias(super))")
	e.p("\t\t}")
	e.p("\t\treturn false")
	e.p("\t}")
	e.p("\tif seen[sub] {")
	e.p("\t\treturn false")
	e.p("\t}")
	e.p("\tseen[sub] = true")
	e.p("\tfor _, n := range failingNeeds[sub] {")
	e.p("\t\tif unlinkedInstanceof(strings.ToLower(resolveAlias(n.name)), super, seen) {")
	e.p("\t\t\treturn true")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn false")
	e.p("}")
	e.p("var varianceDependents = map[string]bool{}")
	e.p("")
	e.p("// declareFailingClass runs one declaration of a class no declaration of")
	e.p("// which can succeed (gogen failingDeclarations): its parent and")
	e.p("// interfaces are resolved in the engine's order, autoloading, until one")
	e.p("// is missing. The failure is the program's to catch -- unless a variance")
	e.p("// check made while it was linking now depends on it, when the engine")
	e.p("// cannot unlink it and the failure is fatal (probed:")
	e.p("// variance/loading_exception1, 2).")
	e.p("func declareFailingClass(ctx *php.Ctx, name string, needs []classNeedRT) error {")
	e.p("\tdeclaringClasses[name] = true")
	e.p("\tfailingDeclaring[name] = true")
	e.p("\tfailingNeeds[name] = needs")
	e.p("\tdefer delete(failingNeeds, name)")
	e.p("\tdefer delete(declaringClasses, name)")
	e.p("\tdefer delete(failingDeclaring, name)")
	e.p("\tfile, line := ctx.Location()")
	e.p("\tfor _, need := range needs {")
	e.p("\t\tc, err := knownClass(ctx, need.name)")
	e.p("\t\tif err == nil && c == \"\" {")
	e.p("\t\t\terr = php.RaiseAt(ctx, \"Error\", \"%%s \\\"%%s\\\" not found\", need.kind, php.DisplayName(need.name))")
	e.p("\t\t}")
	e.p("\t\tif err == nil {")
	e.p("\t\t\tcontinue")
	e.p("\t\t}")
	e.p("\t\tif varianceDependents[name] {")
	e.p("\t\t\tif o, thrown := php.AsThrown(err); thrown {")
	e.p("\t\t\t\tctx.SetLocation(file, line)")
	e.p("\t\t\t\tspelled := name")
	e.p("\t\t\t\tif s, ok := classSpelling[name]; ok {")
	e.p("\t\t\t\t\tspelled = s")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\treturn fatalAt(ctx, \"During inheritance of \"+spelled+\" with variance dependencies: Uncaught \"+php.ThrowableChainString(o))")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\treturn err")
	e.p("\t}")
	e.p("\treturn php.Unsupported(\"declaration of %%s whose names were proven missing\", name)")
	e.p("}")
	e.p("")
	e.p("var classNeeds = map[string][]struct{ name, kind string }{")
	for _, c := range p.Classes {
		if !conditional[strings.ToLower(c.Name)] {
			continue
		}
		// The **kind** travels with the name, because the message the engine
		// raises is chosen by what the declaration named rather than by what
		// the missing thing is: a parent gives `Class "X" not found` and an
		// interface `Interface "X" not found`. A type named only in a method
		// signature is a class.
		type need struct{ name, kind string }
		needs := []need{}
		if c.Parent != "" {
			needs = append(needs, need{c.Parent, "Class"})
		}
		for _, i := range c.Interfaces {
			needs = append(needs, need{i, "Interface"})
		}
		// **And the types in the signatures of methods the parent also
		// declares.** Linking a class variance-checks each override against
		// what it overrides, and that resolves the class names in both
		// signatures. Measured: `class Kid extends P` with `m(): R` over
		// `P::m(): Q` loads R, and a method `other(): S` the parent does *not*
		// declare never loads S -- there is nothing to check it against.
		// A signature type is loaded, never refused: its kind is left empty so
		// declareClass does not report it missing.
		for _, t := range overrideTypes(byName, c) {
			needs = append(needs, need{t, ""})
		}
		// **Not what the engine provides.** Its classes and interfaces are
		// always there, so linking against one never autoloads -- and
		// resolving `UnitEnum` for a conditionally declared enum through
		// `knownClass` asked the autoloader for it, which printed.
		kept := needs[:0]
		for _, n := range needs {
			if !e.engineProvides(n.name) {
				kept = append(kept, n)
			}
		}
		needs = kept
		if len(needs) == 0 {
			continue
		}
		e.p("\t%q: {", strings.ToLower(c.Name))
		for _, n := range needs {
			e.p("\t\t{%q, %q},", n.name, n.kind)
		}
		e.p("\t},")
	}
	e.p("}")
	e.p("")
	e.p("// declareClass binds a conditionally declared class, linking it first.")
	e.p("// linkDeprecation is one tentative-return deprecation linking a class")
	e.p("// raises (gogen engineReturnChecks).")
	e.p("type linkDeprecation struct {")
	e.p("\tline    uint32")
	e.p("\tmessage string")
	e.p("\towner   string")
	e.p("}")
	e.p("")
	e.p("// linkDeprecations raises them as the engine does while it links: each")
	e.p("// at its method's line, with the handler called from the declaration.")
	e.p("// A handler that throws ends the link, and the engine reports the")
	e.p("// exception as the link's fatal, at the declaration (probed).")
	e.p("func linkDeprecations(ctx *php.Ctx, list []linkDeprecation) error {")
	e.p("\tfor _, d := range list {")
	e.p("\t\tfile, line := ctx.Location()")
	e.p("\t\tctx.DeprecatedAt(file, d.line, \"%%s\", d.message)")
	e.p("\t\tif err := ctx.TakePendingError(); err != nil {")
	e.p("\t\t\tif o, thrown := php.AsThrown(err); thrown {")
	e.p("\t\t\t\tctx.SetLocation(file, line)")
	e.p("\t\t\t\treturn fatalAt(ctx, \"During inheritance of \"+d.owner+\": Uncaught \"+php.ThrowableChainString(o))")
	e.p("\t\t\t}")
	e.p("\t\t\treturn err")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn nil")
	e.p("}")
	e.p("")
	e.p("func declareClass(ctx *php.Ctx, name string) error {")
	e.p("\t// **A conditional declaration reached twice is a fatal error**:")
	e.p("\t// a function declaring a class, called again (declare_already_in_use).")
	e.p("\t// An unconditional class is declared before anything runs, so only")
	e.p("\t// a conditional one can meet itself here.")
	e.p("\tif conditionalClasses[name] && declaredClasses[name] {")
	e.p("\t\td := classDecl[name]")
	e.p("\t\treturn fatalAt(ctx, fmt.Sprintf(\"Cannot redeclare %%s %%s (previously declared in %%s:%%d)\", d.kind, realClassOr(name), srcFile, d.line))")
	e.p("\t}")
	e.p("\tdeclaringClasses[name] = true")
	e.p("\tdefer delete(declaringClasses, name)")
	e.p("\t// **Parent and interfaces, then the class, then its signatures.** The")
	e.p("\t// engine registers the class once what it extends and implements")
	e.p("\t// resolves, and only then loads the types its overrides name for the")
	e.p("\t// variance check -- so an autoloaded `C extends B`, reached from B's")
	e.p("\t// signature, finds B. Resolving everything first refused that as")
	e.p("\t// `Class \"B\" not found`.")
	e.p("\tneeds := classNeeds[name]")
	e.p("\tsignatures := len(needs)")
	e.p("\tfor i, need := range needs {")
	e.p("\t\tif need.kind == \"\" {")
	e.p("\t\t\tsignatures = i")
	e.p("\t\t\tbreak")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tfor _, need := range needs[:signatures] {")
	e.p("\t\t// Resolving may autoload, which can print and throw, so it runs")
	e.p("\t\t// for every name first. This was once never refused, because no")
	e.p("\t\t// list said which interfaces the *engine* provides and each name")
	e.p("\t\t// missed from a hand-written one (`ArrayAccess`, `JsonSerializable`)")
	e.p("\t\t// turned working code into a link failure.")
	e.p("\t\tc, err := knownClass(ctx, need.name)")
	e.p("\t\tif err != nil {")
	e.p("\t\t\treturn err")
	e.p("\t\t}")
	e.p("\t\t// **Now refused**, for a parent or an interface: the list of what")
	e.p("\t\t// the engine provides is harvested from its class table, and those")
	e.p("\t\t// names never reach this list. `class T implements A {}` with no")
	e.p("\t\t// `A` is `Interface \"A\" not found` where the declaration runs; a")
	e.p("\t\t// missing parent is `Class \"P\" not found`, and is asked first.")
	e.p("\t\tif c == \"\" && linkChecked {")
	e.p("\t\t\treturn php.RaiseAt(ctx, \"Error\", \"%%s \\\"%%s\\\" not found\", need.kind, php.DisplayName(need.name))")
	e.p("\t\t}")
	e.p("\t}")
	e.p("	declaredClasses[name] = true")
	e.p("\t// **One queue for the whole request**: a class declared while")
	e.p("\t// another's signature types are loading first loads the rest of")
	e.p("\t// them -- `X extends B`, autoloaded for B's check, loads B's Y")
	e.p("\t// before X is done (probed; class_order_autoload6).")
	e.p("\tfor _, need := range needs[signatures:] {")
	e.p("\t\tdelayedAutoloads = append(delayedAutoloads, delayedLoad{need.name, name})")
	e.p("\t}")
	e.p("\t// **A class it extends that is still loading is finished first**: it")
	e.p("\t// cannot be linked against until its loads are done and its checks")
	e.p("\t// made -- which is where `class Y extends B`, loaded for B's check,")
	e.p("\t// fails B's `m(): X` (class_order_autoload_error8). Then its own")
	e.p("\t// loads, but never an unrelated class's.")
	e.p("\tvar ancestors []string")
	e.p("\tfor a := parentOf[realClassOr(name)]; a != \"\"; a = parentOf[a] {")
	e.p("\t\tif low := strings.ToLower(a); declaringClasses[low] {")
	e.p("\t\t\tancestors = append(ancestors, low)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tfor _, owner := range append(ancestors, name) {")
	e.p("\t\tfor {")
	e.p("\t\t\tat := -1")
	e.p("\t\t\tfor i, d := range delayedAutoloads {")
	e.p("\t\t\t\tif d.owner == owner {")
	e.p("\t\t\t\t\tat = i")
	e.p("\t\t\t\t\tbreak")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\tif at < 0 {")
	e.p("\t\t\t\tbreak")
	e.p("\t\t\t}")
	e.p("\t\t\tnext := delayedAutoloads[at].name")
	e.p("\t\t\tdelayedAutoloads = append(delayedAutoloads[:at:at], delayedAutoloads[at+1:]...)")
	e.p("\t\t\t// A class whose declaration is under way is known already, not")
	e.p("\t\t\t// autoloaded again (infinite_recursion).")
	e.p("\t\t\tif declaringClasses[strings.ToLower(next)] {")
	e.p("\t\t\t\tcontinue")
	e.p("\t\t\t}")
	e.p("\t\t\tif _, err := knownClass(ctx, next); err != nil {")
	e.p("\t\t\t\tdelayedAutoloads = nil")
	e.p("\t\t\t\treturn err")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\tif owner != name {")
	e.p("\t\t\tif err := checkVariance(ctx, owner); err != nil {")
	e.p("\t\t\t\tdelayedAutoloads = nil")
	e.p("\t\t\t\treturn err")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tif err := checkVariance(ctx, name); err != nil {")
	e.p("\t\treturn err")
	e.p("\t}")
	e.p("\treturn nil")
	e.p("}")
	e.p("")
	e.p("// delayedAutoloads are the signature types still to load (declareClass),")
	e.p("// with the class whose check asked for each.")
	e.p("type delayedLoad struct{ name, owner string }")
	e.p("")
	e.p("var delayedAutoloads []delayedLoad")
	e.p("")
	e.p("// linkFatalProbe is whether the class a variance check needs is there")
	e.p("// once `declaring` has been declared: loaded then if its needs named it,")
	e.p("// and asked of the autoloader here otherwise, once, as the engine's")
	e.p("// check does.")
	e.p("func linkFatalProbe(ctx *php.Ctx, declaring, missing string) (bool, error) {")
	e.p("\tif realClass(missing) != \"\" || engineClassKind[strings.ToLower(missing)] || engineInterfaceKind[strings.ToLower(missing)] {")
	e.p("\t\treturn true, nil")
	e.p("\t}")
	e.p("\tfor _, need := range classNeeds[declaring] {")
	e.p("\t\tif strings.EqualFold(need.name, missing) {")
	e.p("\t\t\treturn false, nil")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tfound, err := knownClass(ctx, missing)")
	e.p("\treturn found != \"\", err")
	e.p("}")
	e.p("")
	e.p("// linkChecked says the engine's own classes and interfaces were harvested,")
	e.p("// so a name declareClass cannot resolve is really missing.")
	e.p("const linkChecked = %t", len(e.engineClassOrder) > 0 && len(e.engineInterfaceOrder) > 0)
	e.p("")
	e.p("// conditionalClasses are the classes declared where control reaches")
	e.p("// their declaration rather than before the program runs.")
	e.p("var conditionalClasses = map[string]bool{")
	for _, c := range p.Classes {
		if conditional[strings.ToLower(c.Name)] {
			e.p("\t%q: true,", strings.ToLower(c.Name))
		}
	}
	e.p("}")
	e.p("")
	e.p("var declaredClasses = map[string]bool{")
	for _, c := range p.Classes {
		if !conditional[strings.ToLower(c.Name)] {
			e.p("\t%q: true,", strings.ToLower(c.Name))
		}
	}
	// The engine classes this output implements itself are declared for the
	// same reason a compiled one is: `class_exists`, `new $name` and the
	// `Class not found` refusal all read this table.
	for _, name := range e.engineClasses() {
		e.p("\t%q: true,", strings.ToLower(name))
	}
	e.p("}")
	e.p("")
	e.p("// userFuncs resolves a callable given by name. PHP function names are")
	e.p("// case-insensitive, so the keys are folded.")
	// Filled at start-up rather than in the initializer. A closure body can
	// reach `callValue`, which reads this table, and Go rejects that cycle at
	// package scope -- the same wall the property-hook table hit.
	e.p("var userFuncs = map[string]func(*php.Ctx, []php.Value) (php.Value, error){}")
	e.p("")
	e.p("// methodFrames builds a method's frame without entering it, for a call")
	e.p("// that may suspend. Keyed class -> folded method name.")
	e.p("//")
	e.p("// A method call cannot be resolved at emit time -- an interface-typed")
	e.p("// variable holds any implementor -- so the constructor is looked up the")
	e.p("// way the dispatcher looks up the body, from the receiver's own class.")
	e.p("var methodFrames = map[string]map[string]func(*php.Ctx, *php.Object, []php.Value) php.Resumable{}")
	e.p("")
	e.p("func initMethodFrames() {")
	e.p("\tmethodFrames = map[string]map[string]func(*php.Ctx, *php.Object, []php.Value) php.Resumable{")
	for _, c := range p.Classes {
		var names []string
		for n, fn := range c.Methods {
			// Only the bodies that actually get one, or the table names a
			// constructor that was never emitted and the program does not
			// build.
			if fn != nil && hasFrameConstructor(fn) {
				names = append(names, n)
			}
		}
		if len(names) == 0 {
			continue
		}
		sort.Strings(names)
		e.p("\t\t%q: {", c.Name)
		for _, n := range names {
			e.p("\t\t\t%q: %s_frame,", n, methodName(c.Name, n))
		}
		e.p("\t\t},")
	}
	e.p("\t}")
	e.p("}")
	e.p("")
	e.p("// takeFrameObject takes one object off a frame's list, answering it")
	e.p("// alone, or nothing when it is not there.")
	e.p("func takeFrameObject(list *[]php.Value, v php.Value) []php.Value {")
	e.p("\to := v.Deref().Object()")
	e.p("\tfor i, held := range *list {")
	e.p("\t\tif o != nil && held.Object() == o {")
	e.p("\t\t\t*list = append((*list)[:i:i], (*list)[i+1:]...)")
	e.p("\t\t\treturn []php.Value{held}")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn nil")
	e.p("}")
	e.p("")
	e.p("// destructorFrame is the frame an object's `__destruct` runs in when")
	e.p("// that destructor may suspend -- the one the dispatcher would reach,")
	e.p("// from the object's own class -- and false when it has none.")
	e.p("func destructorFrame(ctx *php.Ctx, o *php.Object) (php.Resumable, bool) {")
	e.p("\towner, _, _, ok := methodOwnerOf(o.ClassName, \"__destruct\")")
	e.p("\tif !ok {")
	e.p("\t\treturn nil, false")
	e.p("\t}")
	e.p("\tif make, found := methodFrames[owner][\"__destruct\"]; found {")
	e.p("\t\treturn make(ctx, o, nil), true")
	e.p("\t}")
	e.p("\treturn nil, false")
	e.p("}")
	e.p("")
	e.p("// methodFrameOf finds the frame constructor for a method call, walking")
	e.p("// the receiver's class chain exactly as the dispatcher does -- a method")
	e.p("// declared in a parent is the one an instance of the child reaches.")
	e.p("func methodFrameOf(ctx *php.Ctx, recv php.Value, name string) (func(*php.Ctx, *php.Object, []php.Value) php.Resumable, *php.Object, error) {")
	e.p("\to := recv.Deref().Object()")
	e.p("\tif o == nil {")
	e.p("\t\treturn nil, nil, php.ThrowMethodCallOnNonObject(name, recv)")
	e.p("\t}")
	e.p("\t// **A driver call on a Generator is itself the resumable.** The body")
	e.p("\t// is not this frame's to enter -- the generator owns it -- so what is")
	e.p("\t// built is a drive over the generator, which performs the call and")
	e.p("\t// hands a suspension inside the body out to the fiber.")
	e.p("\tif g, ok := o.Internal.(*php.Generator); ok {")
	e.p("\t\treturn func(c *php.Ctx, _ *php.Object, args []php.Value) php.Resumable {")
	e.p("\t\t\tif d, named := generatorDriveFor(c, o, g, name, args); named {")
	e.p("\t\t\t\t// Its own frame, as callMethod pushes for the call it")
	e.p("\t\t\t\t// does not perform: `Generator->current()`, under the")
	e.p("\t\t\t\t// body it enters.")
	e.p("\t\t\t\treturn d.Trace(\"Generator->\"+generatorMethodName(name), args)")
	e.p("\t\t\t} else {")
	e.p("\t\t\t\treturn d")
	e.p("\t\t\t}")
	e.p("\t\t}, o, nil")
	e.p("\t}")
	e.p("\tfolded := strings.ToLower(name)")
	e.p("\tfor c := o.ClassName; c != \"\"; c = parentOf[c] {")
	e.p("\t\tif make, ok := methodFrames[c][folded]; ok {")
	e.p("\t\t\treturn make, o, nil")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\t// **Nothing here suspends after all.** The split is static and")
	e.p("\t// conservative -- `$x->next()` may drive a Generator and may be a")
	e.p("\t// method on anything -- so a receiver with no frame of its own gets a")
	e.p("\t// frame that performs the ordinary call and returns. Refusing instead")
	e.p("\t// would turn every conservatively-split call on an ordinary object")
	e.p("\t// into a gap.")
	e.p("\treturn func(c *php.Ctx, recvObj *php.Object, args []php.Value) php.Resumable {")
	e.p("\t\treturn php.CallOnce(func(cc *php.Ctx) (php.Value, error) {")
	e.p("\t\t\treturn callMethod(cc, php.Obj(recvObj), name, args)")
	e.p("\t\t})")
	e.p("\t}, o, nil")
	e.p("}")
	e.p("")
	e.p("// generatorDriveFor turns one Generator driver call into a resumable, so")
	e.p("// a `Fiber::suspend()` inside the generator's body reaches the fiber.")
	e.p("//")
	e.p("// The advance and the answer are separate because advancing is what")
	e.p("// produces the answer: `current()` reads its value after the body has")
	e.p("// run, and reading it before would give the element the generator was")
	e.p("// parked on rather than the one the call asks for.")
	e.p("func generatorDriveFor(ctx *php.Ctx, o *php.Object, g *php.Generator, name string, args []php.Value) (*php.GeneratorDrive, bool) {")
	e.p("\tswitch strings.ToLower(name) {")
	e.p("\tcase \"next\":")
	e.p("\t\treturn php.DriveGenerator(g, g.Next, nil), true")
	e.p("\tcase \"rewind\":")
	e.p("\t\treturn php.DriveGenerator(g, g.Rewind, nil), true")
	e.p("\tcase \"current\":")
	e.p("\t\tvar v php.Value")
	e.p("\t\treturn php.DriveGenerator(g, func(c *php.Ctx) error {")
	e.p("\t\t\tgot, err := g.Current(c)")
	e.p("\t\t\tv = got")
	e.p("\t\t\treturn err")
	e.p("\t\t}, func() php.Value { return v }).Reread(g.Current), true")
	e.p("\tcase \"key\":")
	e.p("\t\tvar v php.Value")
	e.p("\t\treturn php.DriveGenerator(g, func(c *php.Ctx) error {")
	e.p("\t\t\tgot, err := g.Key(c)")
	e.p("\t\t\tv = got")
	e.p("\t\t\treturn err")
	e.p("\t\t}, func() php.Value { return v }).Reread(g.Key), true")
	e.p("\tcase \"valid\":")
	e.p("\t\tvar v php.Value")
	e.p("\t\treturn php.DriveGenerator(g, func(c *php.Ctx) error {")
	e.p("\t\t\tok, err := g.Valid(c)")
	e.p("\t\t\tv = php.Bool(ok)")
	e.p("\t\t\treturn err")
	e.p("\t\t}, func() php.Value { return v }).Reread(func(c *php.Ctx) (php.Value, error) {")
	e.p("\t\t\tok, err := g.Valid(c)")
	e.p("\t\t\treturn php.Bool(ok), err")
	e.p("\t\t}), true")
	e.p("\tcase \"send\":")
	e.p("\t\tvar v php.Value")
	e.p("\t\treturn php.DriveGenerator(g, func(c *php.Ctx) error {")
	e.p("\t\t\tgot, err := g.Send(c, php.Arg(args, 0).Deref())")
	e.p("\t\t\tv = got")
	e.p("\t\t\treturn err")
	e.p("\t\t}, func() php.Value { return v }).Reread(g.Current), true")
	e.p("\t}")
	e.p("\t// **Everything else goes to the ordinary dispatcher**, still inside a")
	e.p("\t// drive: `throw()` advances the body as much as next() does, and a")
	e.p("\t// suspension there has to reach the fiber too. This used to be a drive")
	e.p("\t// that did nothing, so `$g->throw($e)` or `$g->getReturn()` from any")
	e.p("\t// body the split made resumable -- `{main}` among them -- was a silent")
	e.p("\t// no-op answering NULL. The dispatcher also gives an unknown method its")
	e.p("\t// `Call to undefined method Generator::...`.")
	e.p("\tvar v php.Value")
	e.p("\treturn php.DriveGenerator(g, func(c *php.Ctx) error {")
	e.p("\t\tgot, err := callMethod(c, php.Obj(o), name, args)")
	e.p("\t\tv = got")
	e.p("\t\treturn err")
	e.p("\t}, func() php.Value { return v }), false")
	e.p("}")
	e.p("")
	e.p("// userFuncNames recovers the **declared** spelling from the folded key.")
	e.p("// A trace names a function as it was declared, not as the callable")
	e.p("// spelled it: `array_map(\"BOOM\", ...)` reaching `function Boom()`")
	e.p("// gives a frame reading `Boom(1)`.")
	e.p("var userFuncNames = map[string]string{")
	for _, fn := range p.Functions {
		if folded := strings.ToLower(fn.Name); folded != fn.Name {
			e.p("\t%q: %q,", folded, fn.Name)
		}
	}
	e.p("}")
	e.p("")
	e.p("func initUserFuncs() {")
	e.p("\tuserFuncs = map[string]func(*php.Ctx, []php.Value) (php.Value, error){")
	for _, fn := range p.Functions {
		e.p("\t\t%q: %s,", strings.ToLower(fn.Name), goName(fn.Name))
	}
	e.p("\t}")
	// The program's own, in declaration order; php2go's library is the
	// engine's to list. A linked library *function* is known by
	// `libraryFile`, not `libraryPaths` (that is the libraries' classes):
	// testing only the latter listed `str_pad` as a user function.
	e.p("\tuserFuncOrder = []string{")
	for _, fn := range p.Functions {
		if !e.libraryPaths[fn.File] && e.libraryFile[strings.ToLower(fn.Name)] == "" && !strings.HasPrefix(strings.ToLower(fn.Name), "php2go\\") {
			e.p("\t\t%q,", strings.ToLower(fn.Name))
		}
	}
	e.p("\t}")
	e.p("}")
	e.p("")
	e.p("// userFuncOrder is the program's functions in the order declared.")
	e.p("var userFuncOrder []string")
	e.p("")
	e.p("// hybridFuncOrder includes generated function bodies visible to runtime eval.")
	e.p("var hybridFuncOrder = []string{")
	for _, fn := range p.Functions {
		e.p("\t%q,", fn.Name)
	}
	e.p("}")
	e.p("")
	e.p("// The tagged hybrid hook uses these plain-Go tables to pass call metadata.")
	e.p("var hybridFuncRequired = map[string]int{")
	for _, fn := range p.Functions {
		e.p("\t%q: %d,", strings.ToLower(fn.Name), fn.RequiredParams)
	}
	e.p("}")
	e.p("var hybridFuncParams = map[string][]string{")
	for _, fn := range p.Functions {
		names := make([]string, len(fn.ParamInfo))
		for i, parameter := range fn.ParamInfo {
			names[i] = parameter.Name
		}
		e.p("\t%q: %#v,", strings.ToLower(fn.Name), names)
	}
	e.p("}")
	e.p("var hybridFuncByRef = map[string][]bool{")
	for _, fn := range p.Functions {
		flags := make([]bool, len(fn.ParamInfo))
		for i, parameter := range fn.ParamInfo {
			flags[i] = parameter.ByRef
		}
		e.p("\t%q: %#v,", strings.ToLower(fn.Name), flags)
	}
	e.p("}")
	e.p("var hybridFuncVariadic = map[string]int{")
	for _, fn := range p.Functions {
		index := -1
		for i, parameter := range fn.ParamInfo {
			if parameter.Variadic {
				index = i
				break
			}
		}
		e.p("\t%q: %d,", strings.ToLower(fn.Name), index)
	}
	e.p("}")
	e.p("")
	e.p("func dispatchHybridUserFunction(ctx *php.Ctx, name string, args []php.Value) (php.Value, error) {")
	e.p("\tkey := strings.ToLower(name)")
	e.p("\tfn, ok := userFuncs[key]")
	e.p("\tif !ok { return php.Undef(), php.Unsupported(\"hybrid eval function %%s\", name) }")
	e.p("\tif spelled, ok := userFuncNames[key]; ok { name = spelled }")
	e.p("\treturn callUser(ctx, name, fn, args)")
	e.p("}")
	e.p("")
	if namesFunction(p, "get_defined_functions") {
		e.p("var engineFuncOrder = []string{")
		for _, n := range p.EngineFunctionOrder {
			e.p("\t%q,", n)
		}
		e.p("}")
	} else {
		e.p("var engineFuncOrder []string")
	}
	e.p("")
	e.p("// callValue invokes a PHP callable on behalf of a builtin.")
	e.p("//")
	e.p("// runtime/php cannot do this itself: it has no function table and no")
	e.p("// method dispatch, which is why the hop is supplied from the layer that")
	e.p("// has both. A callable this cannot resolve is an error rather than a")
	e.p("// silent no-op -- a builtin skipping its callback would return the same")
	e.p("// thing an empty input does.")
	e.p("// callerScope is the class whose body is running, read off the innermost")
	e.p("// frame that names a method. Nothing on the callable path takes a scope")
	e.p("// as an argument, and the frame carries the declaring class because that")
	e.p("// is what pushed it -- `owner + \"->\" + name`.")
	e.p("// callerThis is the receiver of the innermost frame that has one, when it")
	e.p("// is compatible with the class about to be called. A keyword callable")
	e.p("// written inside an instance method calls a non-static method on that")
	e.p("// receiver, the same way `[\"C\", \"parent::m\"]` does.")
	e.p("// callerLSB is the class the innermost frame's call named, which is what")
	e.p("// `static` means there.")
	e.p("func callerLSB(ctx *php.Ctx) string {")
	e.p("\tstack := ctx.Stack()")
	e.p("	for i := len(stack) - 1; i >= 0; i-- {")
	e.p("		if stack[i].LSB != \"\" {")
	e.p("			return stack[i].LSB")
	e.p("\t\t}")
	e.p("		if o := stack[i].This; o != nil {")
	e.p("			return o.ClassName")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn \"\"")
	e.p("}")
	e.p("")
	e.p("func callerThis(ctx *php.Ctx, class string) *php.Object {")
	e.p("\tstack := ctx.Stack()")
	e.p("	for i := len(stack) - 1; i >= 0; i-- {")
	e.p("		if o := stack[i].This; o != nil {")
	e.p("			if strings.EqualFold(o.ClassName, class) || extendsClass(o.ClassName, class) {")
	e.p("				return o")
	e.p("\t\t\t}")
	e.p("\t\t\treturn nil")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn nil")
	e.p("}")
	e.p("")
	e.p("func callerScope(ctx *php.Ctx) string {")
	e.p("\tstack := ctx.Stack()")
	e.p("	for i := len(stack) - 1; i >= 0; i-- {")
	e.p("		fn := stack[i].Function")
	e.p("		if at := strings.Index(fn, \"->\"); at > 0 {")
	e.p("			return fn[:at]")
	e.p("\t\t}")
	e.p("		if at := strings.Index(fn, \"::\"); at > 0 {")
	e.p("			return fn[:at]")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn \"\"")
	e.p("}")
	// callableReason answers why a value cannot be called, and "" when it can.
	// It is the check a builtin makes on its **callback argument**, which
	// happens before the call and reports something different from what the
	// call would: `array_reduce(..., "nope")` is
	// `must be a valid callback, function "nope" not found`, where `$f()` on
	// the same value is `Call to undefined function nope()`. Answering the
	// second for both was a wrong answer, not a missing feature.
	//
	// The wording is the engine's, read back from it one shape at a time --
	// `["C", "m"]` and `"C::m"` both say the method cannot be called
	// statically, `[new C, 5]` blames the second member and `[null, "m"]` the
	// first, and a plain object is refused for its shape like an int.
	e.p("// allInterfaces is a class's interface list in the engine's order")
	e.p("// (probed): the parent's whole list first, then each interface the")
	e.p("// class names followed by the ones *it* extends, each name once.")
	e.p("// `class E implements I4, I3` with `I3 extends I1` is I4, I3, I1, and a")
	e.p("// subclass restating an inherited one does not list it twice.")
	e.p("func allInterfaces(class string, depth int) []string {")
	e.p("\tif class == \"\" || depth > 32 {")
	e.p("\t\treturn nil")
	e.p("\t}")
	e.p("\tvar out []string")
	e.p("\tseen := map[string]bool{}")
	e.p("\tadd := func(n string) {")
	e.p("\t\tif k := strings.ToLower(n); !seen[k] {")
	e.p("\t\t\tseen[k] = true")
	e.p("\t\t\tout = append(out, n)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tfor _, n := range allInterfaces(parentOf[class], depth+1) {")
	e.p("\t\tadd(n)")
	e.p("\t}")
	e.p("\tfor _, i := range interfacesOf[class] {")
	e.p("\t\tadd(i)")
	e.p("\t\tfor _, n := range allInterfaces(realClassOr(i), depth+1) {")
	e.p("\t\t\tadd(n)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn out")
	e.p("}")
	e.p("")
	e.p("// resolveQualifiedCallable judges `[$target, \"Q::m\"]`, probed case by")
	e.p("// case. `self` and `parent` are the **target's** class and its parent;")
	e.p("// `static` is the calling frame's called class; any other Q must be a")
	e.p("// class the target is an instance of. `resolved` is whether that class")
	e.p("// part settled, which is when the engine deprecates the form -- even if")
	e.p("// the method then turns out to be missing. A target class this program")
	e.p("// does not know is not judged.")
	e.p("func resolveQualifiedCallable(ctx *php.Ctx, target php.Value, method string) (owner, reason string, resolved, qualified bool) {")
	e.p("\tq, m, qualified := strings.Cut(method, \"::\")")
	e.p("\tif !qualified {")
	e.p("\t\treturn \"\", \"\", false, false")
	e.p("\t}")
	e.p("\tif target.Kind() == php.KindObject {")
	e.p("\t\towner = target.Object().ClassName")
	e.p("\t} else {")
	e.p("\t\towner = realClass(target.String())")
	e.p("\t}")
	e.p("\tif owner == \"\" {")
	e.p("\t\treturn owner, \"\", false, true")
	e.p("\t}")
	e.p("\tcls := \"\"")
	e.p("\tswitch strings.ToLower(q) {")
	e.p("\tcase \"self\":")
	e.p("\t\tcls = owner")
	e.p("\tcase \"parent\":")
	e.p("\t\tif cls = parentOf[owner]; cls == \"\" {")
	e.p("\t\t\treturn owner, `cannot access \"parent\" when current class scope has no parent`, false, true")
	e.p("\t\t}")
	e.p("\tcase \"static\":")
	e.p("\t\tif cls = realClass(callerLSB(ctx)); cls == \"\" {")
	e.p("\t\t\treturn owner, `cannot access \"static\" when no class scope is active`, false, true")
	e.p("\t\t}")
	e.p("\tdefault:")
	e.p("\t\tif cls = realClass(q); cls == \"\" {")
	e.p("\t\t\treturn owner, \"class \\\"\" + q + \"\\\" not found\", false, true")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tif !strings.EqualFold(owner, cls) && !extendsClass(owner, cls) {")
	e.p("\t\treturn owner, \"class \" + php.DisplayName(owner) + \" is not a subclass of \" + php.DisplayName(cls), false, true")
	e.p("\t}")
	e.p("\tif _, spelled, isStatic, known := methodOwnerOf(cls, strings.ToLower(m)); known {")
	e.p("\t\tif !isStatic && target.Kind() != php.KindObject && callerThis(ctx, cls) == nil {")
	e.p("\t\t\treturn owner, \"non-static method \" + php.DisplayName(cls) + \"::\" + spelled + \"() cannot be called statically\", true, true")
	e.p("\t\t}")
	e.p("\t\t// Visibility is judged from the calling scope, as for any method")
	e.p("\t\t// callable, and the refusal names the class the callable named")
	e.p("\t\t// (bug48770_2: `[$c, \"parent::func22\"]` is `B::func22()`).")
	e.p("\t\tif d, found := methodVisibility[cls][strings.ToLower(m)]; found && d[1] != \"public\" && !methodReachable(d, callerScope(ctx)) && !hasMethod(cls, \"__call\") {")
	e.p("\t\t\treturn owner, \"cannot access \" + d[1] + \" method \" + php.DisplayName(cls) + \"::\" + spelled + \"()\", true, true")
	e.p("\t\t}")
	e.p("\t\treturn owner, \"\", true, true")
	e.p("\t}")
	e.p("\tfor c := cls; c != \"\"; c = parentOf[c] {")
	e.p("\t\tif hasMagic[c][\"__call\"] && target.Kind() == php.KindObject || hasMagic[c][\"__callstatic\"] {")
	e.p("\t\t\treturn owner, \"\", true, true")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn owner, \"class \" + php.DisplayName(cls) + \" does not have a method \\\"\" + m + \"\\\"\", true, true")
	e.p("}")
	e.p("")
	e.p("// deprecateQualifiedCallable says `Callables of the form [\"C\", \"x::m\"]")
	e.p("// are deprecated` for a callable whose method part names a class that")
	e.p("// resolves -- is_callable's and a `callable` parameter's shared step.")
	e.p("func deprecateQualifiedCallable(ctx *php.Ctx, v php.Value) error {")
	e.p("\ta := v.Deref()")
	e.p("\tif a.Kind() != php.KindArray || a.Array().Len() != 2 {")
	e.p("\t\treturn nil")
	e.p("\t}")
	e.p("\tt, _ := a.Array().Get(php.IntKey(0))")
	e.p("\tm, _ := a.Array().Get(php.IntKey(1))")
	e.p("\tif k := t.Deref().Kind(); (k == php.KindObject || k == php.KindString) && m.Deref().Kind() == php.KindString {")
	e.p("\t\tif owner, _, resolved, _ := resolveQualifiedCallable(ctx, t.Deref(), m.Deref().String()); resolved {")
	e.p("\t\t\tctx.Deprecated(`Callables of the form [\"%%s\", \"%%s\"] are deprecated`, php.DisplayName(owner), m.Deref().String())")
	e.p("\t\t\treturn ctx.TakePendingError()")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn nil")
	e.p("}")
	e.p("")
	e.p("// checkUserCallable is call_user_func's callback check. A refused")
	e.p("// `[$o, \"parent::m\"]` whose class part resolved is deprecated **before**")
	e.p("// the TypeError, as the engine does; an accepted one is deprecated by")
	e.p("// the call itself, so only the refusal says it here.")
	e.p("// tickFuncs are what register_tick_function registered, and")
	e.p("// ticksCount the statements since the last tick.")
	e.p("type tickFunc struct {")
	e.p("\tcb   php.Value")
	e.p("\targs []php.Value")
	e.p("}")
	e.p("")
	e.p("var tickFuncs []tickFunc")
	e.p("")
	e.p("// gcCollectCycles runs the bounded top-level object and array collector")
	e.p("// where its roots are proved, and otherwise answers 0 only when")
	e.p("// that is what the engine's collection would amount to as far as the")
	e.p("// program can tell: no collectable cycle, or one whose collection")
	e.p("// would run no destructor, empty no weak reference, close no generator")
	e.p("// or fiber, renumber no object the program prints, and leave a count")
	e.p("// nobody reads (php.CollectWouldBeObserved). Otherwise the gap is")
	e.p("// reported rather than answered.")
	e.p("func gcCollectCycles(ctx *php.Ctx, used, topLevel bool) (php.Value, error) {")
	e.p("\tif topLevel {")
	e.p("\t\tn, err := php.CollectPlainCycles(ctx, php.CycleQuery{")
	e.p("\t\t\tRoots: gcRoots,")
	e.p("\t\t\tTempRoots: gcTempRoots,")
	e.p("\t\t\tHasDestructor: func(o *php.Object) bool { return hasMethod(o.ClassName, \"__destruct\") },")
	e.p("\t\t\tResultUsed: used,")
	e.p("\t\t\tHandlesObserved: %t,", gcHandlesObserved(p))
	e.p("\t\t\tArrayRefs: %t,", gcArrayRefs(p))
	e.p("\t\t})")
	e.p("\t\treturn php.Int(int64(n)), err")
	e.p("\t}")
	e.p("\tif observed, why := php.CollectWouldBeObserved(ctx, php.CycleQuery{")
	e.p("\t\tRoots:           gcRoots,")
	e.p("\t\tHasDestructor:   func(o *php.Object) bool { return hasMethod(o.ClassName, \"__destruct\") },")
	e.p("\t\tResultUsed:      used,")
	e.p("\t\tHandlesObserved: %t,", gcHandlesObserved(p))
	e.p("\t\tArrayRefs:       %t,", gcArrayRefs(p))
	e.p("\t}); observed {")
	e.p("\t\treturn php.Value{}, php.Unsupported(\"%%s\", why)")
	e.p("\t}")
	e.p("\treturn php.Int(0), nil")
	e.p("}")
	e.p("")
	e.p("// gcBoundOwner visits the closure whose capture map a frame shares --")
	e.p("// the closure a generator was made from, which the engine keeps alive")
	e.p("// with it.")
	e.p("func gcBoundOwner(bound map[string]*php.Value, visit func(php.Value)) {")
	e.p("\tif bound == nil {")
	e.p("\t\treturn")
	e.p("\t}")
	e.p("\tkey := fmt.Sprintf(\"%%p\", bound)")
	e.p("\tphp.EachRegistered(func(o *php.Object) {")
	e.p("\t\tif b, ok := o.Internal.(*closureBody); ok && b.bound != nil && fmt.Sprintf(\"%%p\", b.bound) == key {")
	e.p("\t\t\tvisit(php.Obj(o))")
	e.p("\t\t}")
	e.p("\t})")
	e.p("}")
	e.p("")
	e.p("// gcRoots visits what the program certainly still holds: the file")
	e.p("// body's variables, static properties, function statics, and the tick,")
	e.p("// shutdown and autoload callbacks with their arguments. Compiler temporaries are not roots -- one may still hold")
	e.p("// what PHP already let go of -- and the locals of a function on the")
	e.p("// stack are not known here; either only makes gcCollectCycles refuse")
	e.p("// more.")
	e.p("func gcRoots(visit func(php.Value)) {")
	e.p("\tfor name, slot := range globals {")
	e.p("\t\tif slot != nil && !strings.HasPrefix(name, \"__\") {")
	e.p("\t\t\tvisit(*slot)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tfor _, props := range staticProps {")
	e.p("\t\tfor _, slot := range props {")
	e.p("\t\t\tif slot != nil {")
	e.p("\t\t\t\tvisit(*slot)")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tfor _, list := range callableStatics {")
	e.p("\t\tfor _, st := range list {")
	e.p("\t\t\tif st.slot != nil {")
	e.p("\t\t\t\tvisit(*st.slot)")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tfor _, t := range tickFuncs {")
	e.p("\t\tvisit(t.cb)")
	e.p("\t\tfor _, a := range t.args {")
	e.p("\t\t\tvisit(a)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tfor _, s := range shutdownFuncs {")
	e.p("\t\tvisit(s.fn)")
	e.p("\t\tfor _, a := range s.args {")
	e.p("\t\t\tvisit(a)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tfor _, a := range autoloaders {")
	e.p("\t\tvisit(a)")
	e.p("\t}")
	e.p("}")
	e.p("func gcTempRoots(visit func(php.Value)) {")
	e.p("\tfor name, slot := range globals {")
	e.p("\t\tif slot != nil && strings.HasPrefix(name, \"__\") {")
	e.p("\t\t\tvisit(*slot)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("}")
	e.p("var ticksCount uint64")
	e.p("")
	e.p("// runTicks is a `declare(ticks=N)` statement boundary: every Nth one")
	e.p("// calls the tick functions in the order registered, and what one throws")
	e.p("// is thrown at the statement (probed).")
	e.p("func runTicks(ctx *php.Ctx, n uint64) error {")
	e.p("\tticksCount++")
	e.p("\tif ticksCount < n {")
	e.p("\t\treturn nil")
	e.p("\t}")
	e.p("\tticksCount = 0")
	e.p("\t// A tick function may not switch fibers: the engine blocks it for")
	e.p("\t// the duration (fibers/ticks), so a Fiber::suspend() in one throws.")
	e.p("\tdefer ctx.BlockFiberSwitch()()")
	e.p("\tfor _, t := range append([]tickFunc(nil), tickFuncs...) {")
	e.p("\t\targs := make([]php.Value, len(t.args))")
	e.p("\t\tfor i, a := range t.args {")
	e.p("\t\t\targs[i] = a.Copy()")
	e.p("\t\t}")
	e.p("\t\tif _, err := callValue(ctx, t.cb, args); err != nil {")
	e.p("\t\t\treturn err")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn nil")
	e.p("}")
	e.p("")
	e.p("func checkUserCallable(ctx *php.Ctx, function string, v php.Value) error {")
	e.p("\t// **What the check throws becomes the previous of its TypeError**")
	e.p("\t// -- an autoloader's exception, or an error handler's for the")
	e.p("\t// `self::` deprecation -- and the reason is the check's, or")
	e.p("\t// `(null)` when the callable resolved (probed; gh_21699). Only this")
	e.p("\t// family: array_map and usort let the exception through as it is,")
	e.p("\t// which is what ctx.CheckCallable does.")
	e.p("\tgiven := v.Deref()")
	e.p("\treason := \"no array or string given\"")
	e.p("\tswitch given.Kind() {")
	e.p("\tcase php.KindString, php.KindArray, php.KindObject:")
	e.p("\t\treason = callableReason(ctx, given)")
	e.p("\t}")
	e.p("\t// The keyword deprecation is the check's too, so it is said here and")
	e.p("\t// not again by the call (callStaticCallable).")
	e.p("\tif kw := php.CallableKeyword(given); kw != \"\" && reason == \"\" {")
	e.p("\t\tctx.Deprecated(`Use of \"%%s\" in callables is deprecated`, kw)")
	e.p("\t\tkeywordDeprecationSaid = true")
	e.p("\t}")
	e.p("	var err error")
	e.p("\tif perr := ctx.TakePendingError(); perr != nil {")
	e.p("\t\tkeywordDeprecationSaid = false")
	e.p("\t\tprevious, ok := materialise(ctx, perr)")
	e.p("\t\tif !ok {")
	e.p("\t\t\treturn perr")
	e.p("\t\t}")
	e.p("\t\tif reason == \"\" {")
	e.p("\t\t\treason = \"(null)\"")
	e.p("\t\t}")
	e.p("\t\tthrown, ok := materialise(ctx, php.RaiseAt(ctx, \"TypeError\", \"%%s(): Argument #1 ($callback) must be a valid callback, %%s\", function, reason))")
	e.p("\t\tif !ok {")
	e.p("\t\t\treturn perr")
	e.p("\t\t}")
	e.p("\t\tphp.ChainInFlight(thrown.Object(), previous)")
	e.p("\t\treturn php.Throw(thrown.Object())")
	e.p("\t}")
	e.p("\tif reason == \"\" {")
	e.p("\t\treturn nil")
	e.p("\t}")
	e.p("\terr = php.Raise(\"TypeError\", \"%%s(): Argument #1 ($callback) must be a valid callback, %%s\", function, reason)")
	e.p("\tif a := v.Deref(); a.Kind() == php.KindArray && a.Array().Len() == 2 {")
	e.p("\t\tt, _ := a.Array().Get(php.IntKey(0))")
	e.p("\t\tm, _ := a.Array().Get(php.IntKey(1))")
	e.p("\t\tif k := t.Deref().Kind(); (k == php.KindObject || k == php.KindString) && m.Deref().Kind() == php.KindString {")
	e.p("\t\t\tif owner, _, resolved, _ := resolveQualifiedCallable(ctx, t.Deref(), m.Deref().String()); resolved {")
	e.p("\t\t\t\tctx.Deprecated(`Callables of the form [\"%%s\", \"%%s\"] are deprecated`, php.DisplayName(owner), m.Deref().String())")
	e.p("\t\t\t\tif perr := ctx.TakePendingError(); perr != nil {")
	e.p("\t\t\t\t\treturn perr")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn err")
	e.p("}")
	e.p("")
	e.p("func callableReason(ctx *php.Ctx, callable php.Value) string {")
	e.p("\tcallable = callable.Deref()")
	e.p("\t// **A callable over an incomplete object is not decided here.** Its")
	e.p("\t// get_method handler throws, and whether a check surfaces that Error")
	e.p("\t// or its own TypeError differs by caller (call_user_func says the")
	e.p("\t// class has no such method, array_map throws the Error; probed). The")
	e.p("\t// gap is parked, so whichever check asked refuses.")
	e.p("\tif php.IncompleteCallable(callable) {")
	e.p("\t\tctx.ParkError(php.Unsupported(\"a callable over an incomplete object\"))")
	e.p("\t\treturn \"\"")
	e.p("\t}")
	e.p("\tswitch callable.Kind() {")
	e.p("\tcase php.KindObject:")
	e.p("\t\tif _, ok := callable.Object().Internal.(*closureBody); ok {")
	e.p("\t\t\treturn \"\"")
	e.p("\t\t}")
	e.p("\t\tif hasMethod(callable.Object().ClassName, \"__invoke\") {")
	e.p("\t\t\treturn \"\"")
	e.p("\t\t}")
	// A class the program does not declare cannot be judged, and claiming it is
	// uncallable would refuse something that may work.
	// **A plain object is refused for its shape, not by name.** The engine says
	// `no array or string given` for `new stdClass` -- the same words an int
	// gets -- rather than naming the class, which was read back from it rather
	// than assumed. There is no "class I do not know" escape here: an object is
	// callable when it is a Closure or declares `__invoke`, and an engine class
	// this program never declared has neither.
	e.p("\t\treturn \"no array or string given\"")
	e.p("\tcase php.KindArray:")
	e.p("\t\titems := callable.Array()")
	e.p("\t\tif items.Len() != 2 {")
	e.p("\t\t\treturn \"array callback must have exactly two members\"")
	e.p("\t\t}")
	e.p("\t\ttarget, hasTarget := items.Get(php.IntKey(0))")
	e.p("\t\tmethod, hasMethodKey := items.Get(php.IntKey(1))")
	e.p("\t\tif !hasTarget || !hasMethodKey {")
	e.p("\t\t\treturn \"array callback has to contain indices 0 and 1\"")
	e.p("\t\t}")
	// The *first* member decides first: `[1, 2]` is about the class, not the
	// method.
	e.p("\t\tswitch target.Deref().Kind() {")
	e.p("\t\tcase php.KindObject, php.KindString:")
	e.p("\t\tdefault:")
	e.p("\t\t\treturn \"first array member is not a valid class name or object\"")
	e.p("\t\t}")
	e.p("\t\tif method.Deref().Kind() != php.KindString {")
	e.p("\t\t\treturn \"second array member is not a valid method\"")
	e.p("\t\t}")
	e.p("\t\t// `[$closure, \"__invoke\"]` is the Closure's own method.")
	e.p("\t\tif t := target.Deref(); t.Kind() == php.KindObject && strings.EqualFold(method.Deref().String(), \"__invoke\") {")
	e.p("\t\t\tif _, isClosure := t.Object().Internal.(*closureBody); isClosure {")
	e.p("\t\t\t\treturn \"\"")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\t// `[$b, \"parent::m\"]` and `[$b, \"A::m\"]` name a method of a class")
	e.p("\t\t// `$b` is an instance of (resolveQualifiedCallable).")
	e.p("\t\tif _, reason, _, qualified := resolveQualifiedCallable(ctx, target.Deref(), method.Deref().String()); qualified {")
	e.p("\t\t\treturn reason")
	e.p("\t\t}")
	e.p("\t\treturn methodCallableReason(ctx, target.Deref(), method.Deref().String())")
	e.p("\tcase php.KindString:")
	e.p("\t\tname := callable.String()")
	e.p("\t\tif class, method, compound := strings.Cut(name, \"::\"); compound {")
	e.p("\t\t\treturn methodCallableReason(ctx, php.String(class), method)")
	e.p("\t\t}")
	e.p("\t\t// One leading backslash is the fully-qualified spelling.")
	e.p("\t\tlower := strings.ToLower(strings.TrimPrefix(name, \"\\\\\"))")
	e.p("\t\tif _, ok := userFuncs[lower]; ok {")
	e.p("\t\t\treturn \"\"")
	e.p("\t\t}")
	e.p("\t\tif _, ok := php.LookupBuiltin(lower); ok {")
	e.p("\t\t\treturn \"\"")
	e.p("\t\t}")
	// A function the engine has and this program does not implement is a gap,
	// not an invalid callback: saying it is invalid would be a wrong answer.
	e.p("\t\tif engineFuncs[lower] {")
	e.p("\t\t\treturn \"\"")
	e.p("\t\t}")
	e.p("\t\treturn \"function \\\"\" + name + \"\\\" not found or invalid function name\"")
	e.p("\t}")
	e.p("\treturn \"no array or string given\"")
	e.p("}")
	e.p("")
	// methodCallableReason is the array and `Class::method` forms' shared half.
	e.p("// methodCallableReason judges `[$target, \"m\"]` and `\"C::m\"`, which")
	e.p("// differ only in how the class was written. A **string** target names a")
	e.p("// class and so cannot reach a non-static method; an object target can.")
	e.p("func methodCallableReason(ctx *php.Ctx, target php.Value, method string) string {")
	e.p("\tclass := \"\"")
	e.p("\tstatically := false")
	e.p("\tif target.Kind() == php.KindObject {")
	e.p("\t\tclass = target.Object().ClassName")
	e.p("\t} else {")
	e.p("\t\tclass = resolveAlias(target.String())")
	e.p("\t\tstatically = true")
	e.p("\t\t// **A keyword names a class of the calling scope** -- `\"parent::m\"`,")
	e.p("\t\t// `[\"static\", \"m\"]` -- and is judged as that class.")
	e.p("\t\tswitch kw := strings.ToLower(class); kw {")
	e.p("\t\tcase \"self\", \"parent\", \"static\":")
	e.p("\t\t\tscope := callerScope(ctx)")
	e.p("\t\t\tif scope == \"\" {")
	e.p("\t\t\t\treturn \"cannot access \\\"\" + kw + \"\\\" when no class scope is active\"")
	e.p("\t\t\t}")
	e.p("\t\t\tswitch kw {")
	e.p("\t\t\tcase \"parent\":")
	e.p("\t\t\t\tscope = parentOf[realClassOr(scope)]")
	e.p("\t\t\t\tif scope == \"\" {")
	e.p("\t\t\t\t\treturn \"cannot access \\\"parent\\\" when current class scope has no parent\"")
	e.p("\t\t\t\t}")
	e.p("\t\t\tcase \"static\":")
	e.p("\t\t\t\tif l := callerLSB(ctx); l != \"\" {")
	e.p("\t\t\t\t\tscope = l")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\tclass = scope")
	e.p("\t\t}")
	e.p("\t\t// Spelled as declared: `[\"MAGIC\", \"m\"]` names `Magic`.")
	e.p("\t\tdeclared := realClass(class)")
	e.p("\t\tif declared == \"\" && engineClassKind[strings.ToLower(class)] {")
	e.p("\t\t\t// An engine class this program never declared: judged when its")
	e.p("\t\t\t// methods are modelled -- stdClass has none -- and otherwise left")
	e.p("\t\t\t// for the call to report, since refusing it would be a guess.")
	e.p("\t\t\tspelled := engineSpelling(class)")
	e.p("\t\t\tif _, modelled := engineMethodNames[strings.ToLower(spelled)]; !modelled && spelled != \"stdClass\" {")
	e.p("\t\t\t\treturn \"\"")
	e.p("\t\t\t}")
	e.p("\t\t\tdeclared = spelled")
	e.p("\t\t}")
	e.p("\t\t// **Autoloaded first**, as the engine's callable check does: an")
	e.p("\t\t// autoloader that throws makes that exception the answer -- parked")
	e.p("\t\t// here, since a reason is only a string, and preferred by")
	e.p("\t\t// CheckCallable over the TypeError it would otherwise raise.")
	e.p("\t\t// An empty name is never autoloaded -- the engine refuses it")
	e.p("\t\t// outright (call_user_func_002).")
	e.p("\t\tif declared == \"\" && class != \"\" && !engineClassKind[strings.ToLower(class)] {")
	e.p("\t\t\tfound, err := knownClass(ctx, class)")
	e.p("\t\t\tif err != nil {")
	e.p("\t\t\t\tctx.ParkError(err)")
	e.p("\t\t\t\treturn \"class \\\"\" + php.DisplayName(target.String()) + \"\\\" not found\"")
	e.p("\t\t\t}")
	e.p("\t\t\tdeclared = found")
	e.p("\t\t}")
	e.p("\t\tif declared == \"\" {")
	e.p("\t\t\treturn \"class \\\"\" + php.DisplayName(target.String()) + \"\\\" not found\"")
	e.p("\t\t}")
	e.p("\t\tclass = declared")
	e.p("\t}")
	// **The method table is keyed lowercased**, because PHP method names are
	// case-insensitive: `[$this, "EH"]` finds a method declared `EH` only if
	// the lookup folds first. Passing the source spelling made every
	// mixed-case callback report that the class has no such method.
	e.p("\t_, spelling, static, ok := methodOwnerOf(class, strings.ToLower(method))")
	e.p("\t// A date class's own method is the engine's: callable as the")
	e.p("\t// engine's table says, and refused when it is called.")
	e.p("\tif d := dateClassOf(class); !ok && d != \"\" {")
	e.p("\t\tif spelled, has := engineMethodNames[strings.ToLower(d)][strings.ToLower(method)]; has {")
	e.p("\t\t\tif statically && !engineStaticMethods[strings.ToLower(d)][strings.ToLower(method)] && callerThis(ctx, class) == nil {")
	e.p("\t\t\t\treturn \"non-static method \" + php.DisplayName(realClassOr(class)) + \"::\" + spelled + \"() cannot be called statically\"")
	e.p("\t\t\t}")
	e.p("\t\t\treturn \"\"")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\t// An SPL iterator's methods: all public, none static.")
	e.p("\tif !ok && !statically {")
	e.p("\t\tif inner, forwards := splForwardTarget(target.Object(), strings.ToLower(method)); forwards {")
	e.p("\t\t\treturn methodCallableReason(ctx, inner, method)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\t// Generator's and Fiber's methods: all public; on an object they are")
	e.p("\t// callable (probed: `Closure::fromCallable([$gen, 'valid'])`).")
	e.p("\tif !ok && !statically && (engineHasGeneratorMethod(class, method) || engineHasFiberMethod(class, method)) {")
	e.p("\t\treturn \"\"")
	e.p("\t}")
	e.p("\tif !ok && engineHasSplMethod(class, method) {")
	e.p("\t\tif statically && callerThis(ctx, class) == nil {")
	e.p("\t\t\t_, spelled := engineMethodOwner(class, strings.ToLower(method))")
	e.p("\t\t\treturn \"non-static method \" + php.DisplayName(engineSpelling(realClassOr(class))) + \"::\" + spelled + \"() cannot be called statically\"")
	e.p("\t\t}")
	e.p("\t\treturn \"\"")
	e.p("\t}")
	e.p("\tif !ok {")
	e.p("\t\t// Either magic method answers a name the class lacks: `__callStatic`")
	e.p("\t\t// makes `\"Test::Two\"` callable as surely as `__call` does `[$o, \"two\"]`.")
	e.p("\t\t// But **`__call` needs an object**: a class-string callable reaches it")
	e.p("\t\t// only with a compatible `$this` in scope, so `[\"A\", \"foo\"]` on a")
	e.p("\t\t// class with `__call` alone is not callable from outside (bug34678).")
	e.p("\t\tif hasMethod(class, \"__callstatic\") {")
	e.p("\t\t\treturn \"\"")
	e.p("\t\t}")
	e.p("\t\tif hasMethod(class, \"__call\") && (!statically || callerThis(ctx, class) != nil) {")
	e.p("\t\t\treturn \"\"")
	e.p("\t\t}")
	e.p("\t\treturn \"class \" + php.DisplayName(class) + \" does not have a method \\\"\" + method + \"\\\"\"")
	e.p("\t}")
	e.p("\t// **Not when a compatible `$this` is in scope**: `[\"C\", \"m\"]` inside")
	e.p("\t// an instance method of C calls `m` on that object.")
	e.p("\tif statically && !static && callerThis(ctx, class) == nil {")
	e.p("\t\treturn \"non-static method \" + php.DisplayName(realClassOr(class)) + \"::\" + spelling +")
	e.p("\t\t\t\"() cannot be called statically\"")
	e.p("\t}")
	// Visibility is judged from the **calling scope** -- the frame that handed
	// the callable to the builtin -- as the engine's zend_is_callable does:
	// `is_callable('A::prot')` is true inside a subclass of A, and
	// `array_map([$this, "priv"], ...)` works inside the class.
	// The table is keyed by the class's declared spelling and the method's
	// lowercased name, which is how every other reader indexes it.
	e.p("\tif d, found := methodVisibility[realClass(class)][strings.ToLower(method)]; found {")
	e.p("\t\tif d[1] != \"public\" && !methodReachable(d, callerScope(ctx)) {")
	e.p("\t\t\tif hasMethod(class, \"__call\") {")
	e.p("\t\t\t\treturn \"\"")
	e.p("\t\t\t}")
	e.p("\t\t\t// The class the callable named, not the declaring one: the")
	e.p("\t\t\t// engine prints fcc->calling_scope (call_user_func_001).")
	e.p("\t\t\treturn \"cannot access \" + d[1] + \" method \" + php.DisplayName(realClassOr(class)) + \"::\" + spelling + \"()\"")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn \"\"")
	e.p("}")
	e.p("")
	e.p("")
	e.p("func callValue(ctx *php.Ctx, callable php.Value, args []php.Value) (php.Value, error) {")
	e.p("\tkeepRefs := callFunctionRefs")
	e.p("\tcallFunctionRefs = false")
	e.p("\tswitch callable.Kind() {")
	e.p("\tcase php.KindString:")
	e.p("\t\t// `\"Class::method\"` is a callable, and it goes through the static")
	e.p("\t\t// dispatcher rather than the function table -- which is what makes")
	e.p("\t\t// `Non-static method C::m() cannot be called statically` reachable")
	e.p("\t\t// from a callable at all. Looked up as a function first it was")
	e.p("\t\t// `Call to undefined function Class::method()`.")
	e.p("\t\tif class, method, ok := strings.Cut(callable.String(), \"::\"); ok {")
	e.p("\t\t\treturn callStaticCallable(ctx, class, method, args)")
	e.p("\t\t}")
	e.p("\t\tname := strings.ToLower(strings.TrimPrefix(callable.String(), \"\\\\\"))")
	e.p("\t\t// **The frame-reading functions refuse a dynamic call**")
	e.p("\t\t// (zend_forbid_dynamic_call): they would read or write the")
	e.p("\t\t// frame of whatever called them by name (dynamic_call_005..008).")
	e.p("\t\tswitch name {")
	e.p("\t\tcase \"extract\", \"compact\", \"get_defined_vars\", \"func_get_args\", \"func_get_arg\", \"func_num_args\":")
	e.p("\t\t\tif _, own := userFuncs[name]; !own {")
	e.p("\t\t\t\t// Refused **inside its own frame**: the trace opens at")
	e.p("\t\t\t\t// `compact('a')` (probed; bug71221).")
	e.p("\t\t\t\tfile, line := ctx.Location()")
	e.p("\t\t\t\tctx.PushCall(php.StackFrame{Function: name, File: file, Line: line, Args: args})")
	e.p("\t\t\t\tdefer ctx.PopCall()")
	e.p("\t\t\t\tif err := frameReaderParams(ctx, name, args); err != nil {")
	e.p("\t\t\t\t\treturn php.Value{}, err")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\treturn php.Value{}, php.RaiseAt(ctx, \"Error\", \"Cannot call %%s() dynamically\", name)")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\tif fn, ok := userFuncs[name]; ok {")
	e.p("\t\t\t// **A frame, like any other call.** Reached directly, the")
	e.p("\t\t\t// callee was missing from every backtrace taken inside it:")
	e.p("\t\t\t// a callback that threw opened its trace at the builtin that")
	e.p("\t\t\t// invoked it. `PushCall` supplies the location, which is")
	e.p("\t\t\t// `[internal function]` when a library function is what")
	e.p("\t\t\t// reached here.")
	e.p("\t\t\tdeclared := callable.String()")
	e.p("\t\t\tif spelled, ok := userFuncNames[name]; ok {")
	e.p("\t\t\t\tdeclared = spelled")
	e.p("\t\t\t}")
	e.p("\t\t\treturn callUser(ctx, declared, fn, args)")
	e.p("\t\t}")
	e.p("\t\tif _, ok := php.LookupBuiltin(name); ok {")
	e.p("\t\t\t// **Through `callBuiltin`, not straight to the function.** A")
	e.p("\t\t\t// builtin reached as a *callable* -- `array_map(\"strtoupper\",")
	e.p("\t\t\t// ...)`, `usort($a, \"strcmp\")`, an `ob_start` filter -- owes the")
	e.p("\t\t\t// same argument checks as one written as a call. Calling the")
	e.p("\t\t\t// looked-up function directly skipped every one of them, so a")
	e.p("\t\t\t// callback invoked with the wrong count simply ran.")
	e.p("\t\t\tbound, err := bindBuiltinNamed(ctx, name, args)")
	e.p("\t\t\tif err != nil {")
	e.p("\t\t\t\treturn php.Value{}, err")
	e.p("\t\t\t}")
	e.p("\t\t\treturn callBuiltin(ctx, \"\", name, bound, false)")
	e.p("\t\t}")
	e.p("\t\tif engineFuncs[name] {")
	e.p("\t\t\treturn php.Value{}, php.Unsupported(\"library function %%s\", name)")
	e.p("\t\t}")
	e.p("\t\treturn php.Value{}, php.ThrowUndefinedFunction(callable.String())")
	e.p("\tcase php.KindObject:")
	e.p("\t\tif b, ok := callable.Object().Internal.(*closureBody); ok {")
	e.p("\t\t\tif b.meta.function != \"\" {")
	e.p("\t\t\t\treturn b.fn(ctx, b.this, b.bound, b.scope, args)")
	e.p("\t\t\t}")
	e.p("\t\t\tfile, line := ctx.Location()")
	e.p("\t\t\tctx.PushCall(php.StackFrame{Function: closureFrameName(b, b.this, b.scope), File: file, Line: line, Args: args, This: b.this, LSB: b.called})")
	e.p("\t\t\tdefer ctx.PopCall()")
	e.p("\t\t\treturn b.fn(ctx, b.this, b.bound, b.scope, args)")
	e.p("\t\t}")
	e.p("\t\treturn callMethod(ctx, callable, \"__invoke\", args)")
	e.p("\tcase php.KindArray:")
	e.p("\t\t// [$object, \"method\"] -- the other callable form the corpus uses.")
	e.p("\t\ta := callable.Array()")
	e.p("\t\trecv, okr := a.Get(php.IntKey(0))")
	e.p("\t\tm, okm := a.Get(php.IntKey(1))")
	e.p("\t\tif okr && okm {")
	e.p("\t\t\t// `[\"Class\", \"method\"]` is the static form of the same thing:")
	e.p("\t\t\t// element 0 is a class *name*, not a receiver.")
	e.p("\t\t\t// **A keyword-prefixed method name.** `[\"C\", \"parent::func\"]`")
	e.p("\t\t\t// names the parent's method and is deprecated rather than")
	e.p("\t\t\t// refused, and `self::` and `static::` are the same shape. The")
	e.p("\t\t\t// message quotes the **class of element 0** whichever spelling")
	e.p("\t\t\t// it was: `[$this, \"parent::func\"]` still reports")
	e.p("\t\t\t// `[\"C\", \"parent::func\"]`. Without this the whole string was")
	e.p("\t\t\t// taken as a method name and the call was")
	e.p("\t\t\t// `Call to undefined method C::parent::func()`.")
	e.p("\t\t\tif kw, rest, split := strings.Cut(m.Deref().String(), \"::\"); split {")
	e.p("\t\t\t\towner := \"\"")
	e.p("\t\t\t\tif recv.Deref().Kind() == php.KindString {")
	e.p("\t\t\t\t\towner = recv.Deref().String()")
	e.p("\t\t\t\t} else if recv.Deref().Kind() == php.KindObject {")
	e.p("\t\t\t\t\towner = recv.Deref().Object().ClassName")
	e.p("\t\t\t\t}")
	e.p("\t\t\t\tswitch strings.ToLower(kw) {")
	e.p("\t\t\t\tcase \"parent\", \"self\", \"static\":")
	e.p("\t\t\t\t\tif owner != \"\" {")
	e.p("\t\t\t\t\t\tctx.Deprecated(`Callables of the form [\"%%s\", \"%%s\"] are deprecated`, php.DisplayName(owner), m.Deref().String())")
	e.p("\t\t\t\t\t\tif err := ctx.TakePendingError(); err != nil {")
	e.p("\t\t\t\t\t\t\treturn php.Value{}, err")
	e.p("\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t\ttarget := owner")
	e.p("\t\t\t\t\t\tif strings.EqualFold(kw, \"parent\") {")
	e.p("\t\t\t\t\t\t\ttarget = parentOf[realClass(owner)]")
	e.p("\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t\tvar this *php.Object")
	e.p("\t\t\t\t\t\tif recv.Deref().Kind() == php.KindObject {")
	e.p("\t\t\t\t\t\t\tthis = recv.Deref().Object()")
	e.p("\t\t\t\t\t\t} else {")
	e.p("\t\t\t\t\t\t\t// The **caller's** receiver, when the callable names a")
	e.p("\t\t\t\t\t\t\t// class rather than an object: `[\"C\", \"parent::func\"]`")
	e.p("\t\t\t\t\t\t\t// written inside a method of C calls a non-static parent")
	e.p("\t\t\t\t\t\t\t// method on that `$this`. Read off the innermost frame")
	e.p("\t\t\t\t\t\t\t// that has one, since nothing on this path takes a")
	e.p("\t\t\t\t\t\t\t// receiver as an argument.")
	e.p("\t\t\t\t\t\t\tstack := ctx.Stack()")
	e.p("\t\t\t\t\t\t\tfor i := len(stack) - 1; i >= 0; i-- {")
	e.p("\t\t\t\t\t\t\t\tif o := stack[i].This; o != nil {")
	e.p("\t\t\t\t\t\t\t\t\tif strings.EqualFold(o.ClassName, owner) || extendsClass(o.ClassName, owner) {")
	e.p("\t\t\t\t\t\t\t\t\t\tthis = o")
	e.p("\t\t\t\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t\t\t\t\tbreak")
	e.p("\t\t\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t\t// **The calling scope decides accessibility**, not the")
	e.p("\t\t\t\t\t\t// class the callable names: `[$this, \"parent::func2\"]`")
	e.p("\t\t\t\t\t\t// written inside `B::func` reaches B's *private* func2,")
	e.p("\t\t\t\t\t\t// and the object may be a C. Passing the callable's own")
	e.p("\t\t\t\t\t\t// class refused it as `Call to private method B::func2()")
	e.p("\t\t\t\t\t\t// from scope C`.")
	e.p("\t\t\t\t\t\tscope := owner")
	e.p("\t\t\t\t\t\tif s := callerScope(ctx); s != \"\" {")
	e.p("\t\t\t\t\t\t\tscope = s")
	e.p("\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t\treturn callStaticFrom(ctx, target, rest, this, args, scope)")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\tdefault:")
	e.p("\t\t\t\t\t// `[$b, \"A::m\"]` names an ancestor's method to run on `$b`:")
	e.p("\t\t\t\t\t// deprecated the same way, then A's `m` with `$b` as `$this`.")
	e.p("\t\t\t\t\t// `[\"B\", \"A::m\"]` is the same with a class name, running on")
	e.p("\t\t\t\t\t// the caller's compatible `$this` (callable_self_parent_static_")
	e.p("\t\t\t\t\t// deprecation); it was `Call to undefined method B::A::foo()`.")
	e.p("\t\t\t\t\tif named := realClass(kw); owner != \"\" && named != \"\" &&")
	e.p("\t\t\t\t\t\t(strings.EqualFold(owner, named) || extendsClass(owner, named)) {")
	e.p("\t\t\t\t\t\tctx.Deprecated(`Callables of the form [\"%%s\", \"%%s\"] are deprecated`, php.DisplayName(owner), m.Deref().String())")
	e.p("\t\t\t\t\t\tif err := ctx.TakePendingError(); err != nil {")
	e.p("\t\t\t\t\t\t\treturn php.Value{}, err")
	e.p("\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t\tscope := owner")
	e.p("\t\t\t\t\t\tif s := callerScope(ctx); s != \"\" {")
	e.p("\t\t\t\t\t\t\tscope = s")
	e.p("\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t\tthis := recv.Deref().Object()")
	e.p("\t\t\t\t\t\tif this == nil {")
	e.p("\t\t\t\t\t\t\tstack := ctx.Stack()")
	e.p("\t\t\t\t\t\t\tfor i := len(stack) - 1; i >= 0; i-- {")
	e.p("\t\t\t\t\t\t\t\tif o := stack[i].This; o != nil {")
	e.p("\t\t\t\t\t\t\t\t\tif strings.EqualFold(o.ClassName, owner) || extendsClass(o.ClassName, owner) {")
	e.p("\t\t\t\t\t\t\t\t\t\tthis = o")
	e.p("\t\t\t\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t\t\t\t\tbreak")
	e.p("\t\t\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t\t}")
	e.p("\t\t\t\t\t\treturn callStaticFrom(ctx, named, rest, this, args, scope)")
	e.p("\t\t\t\t\t}")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t\tif recv.Deref().Kind() == php.KindString {")
	e.p("\t\t\t\treturn callStaticCallable(ctx, recv.Deref().String(), m.String(), args)")
	e.p("\t\t\t}")
	e.p("\t\t\t// **From the calling scope**, like the method call it stands for:")
	e.p("\t\t\t// `call_user_func([$c, \"prot\"])` from outside C reaches `__call`")
	e.p("\t\t\t// when C has one, and is refused when it does not.")
	e.p("\t\t\tcallFunctionRefs = keepRefs")
	e.p("\t\t\treturn callMethodFrom(ctx, recv, m.String(), args, callerScope(ctx))")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn php.Value{}, fmt.Errorf(\"value of type %%s is not callable\", callable.Kind())")
	e.p("}")
	e.p("")
	// **A by-reference parameter given a value warns and runs.** The engine
	// raises `must be passed by reference, value given` wherever an argument
	// list is built without the caller's slots: `call_user_func` and
	// `call_user_func_array` expanded in place (ZEND_SEND_USER and
	// ZEND_SEND_ARRAY), and every callback an internal function invokes
	// through `zend_call_function`. The callee then gets a reference to a
	// copy, so its writes go nowhere -- which a plain value already is here.
	e.p("// libraryPreferRef are the prefer-reference library functions this")
	e.p("// program links from the userland library, by lowercase name.")
	e.p("var libraryPreferRef = map[string]bool{")
	for _, n := range []string{"array_multisort", "extract"} {
		if e.libraryFile[n] != "" {
			e.p("\t%q: true,", n)
		}
	}
	e.p("}")
	e.p("")
	e.p("// warnByValue raises the complaint of each by-reference parameter of")
	e.p("// `callable` that `args` gives a value rather than a reference.")
	e.p("func warnByValue(ctx *php.Ctx, callable php.Value, args []php.Value) {")
	e.p("\tname, params := byRefTarget(callable)")
	e.p("\t// **A prefer-by-reference parameter takes a value silently.** The")
	e.p("\t// harvest collapses ZEND_SEND_PREFER_REF to by-reference, and the")
	e.p("\t// two library functions declaring it (`@prefer-ref` in the stubs)")
	e.p("\t// are the ones that would otherwise warn here: `array_map('extract',")
	e.p("\t// ...)` goes straight to the dynamic-call refusal.")
	e.p("\t// **Compiled from the userland library is still the library's**:")
	e.p("\t// array_multisort has a compiled body, so being in userFuncs does not")
	e.p("\t// make it the program's own (call_user_func_array_prefer_ref).")
	e.p("\tpreferRef := false")
	e.p("\tif _, own := userFuncs[strings.ToLower(name)]; !own || libraryPreferRef[strings.ToLower(name)] {")
	e.p("\t\tswitch strings.ToLower(name) {")
	e.p("\t\tcase \"extract\", \"array_multisort\":")
	e.p("\t\t\tpreferRef = true")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\t// **At the script's call**, not inside the library function that")
	e.p("\t// invoked the callback: `usort($a, function (&$x, &$y) {})` warns")
	e.p("\t// on the `usort` line. The innermost frame is that call.")
	e.p("\tif file, _ := ctx.Location(); file == php.InternalFrameFile {")
	e.p("\t\tif stack := ctx.Stack(); len(stack) > 0 && stack[len(stack)-1].File != php.InternalFrameFile {")
	e.p("\t\t\tfile, line := ctx.Location()")
	e.p("\t\t\tctx.SetLocation(stack[len(stack)-1].File, stack[len(stack)-1].Line)")
	e.p("\t\t\tdefer ctx.SetLocation(file, line)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\tfor i, a := range args {")
	e.p("\t\tif i >= len(params) {")
	e.p("\t\t\tbreak")
	e.p("\t\t}")
	e.p("\t\tshown, byRef := strings.CutPrefix(params[i].name, \"&\")")
	e.p("\t\tif !byRef {")
	e.p("\t\t\tcontinue")
	e.p("\t\t}")
	e.p("\t\tif _, isRef := a.RefOf(); isRef {")
	e.p("\t\t\tcontinue")
	e.p("\t\t}")
	e.p("\t\t// **The callee gets a reference to a copy**: the value still")
	e.p("\t\t// shares its array with the caller's variable, and binding it")
	e.p("\t\t// as it is let the callee's writes reach that variable")
	e.p("\t\t// (`call_user_func('array_multisort', $a)` sorted `$a`).")
	e.p("\t\targs[i] = a.Deref().Copy()")
	e.p("\t\tif !preferRef {")
	e.p("\t\t\tctx.Warn(\"%%s(): Argument #%%d (%%s) must be passed by reference, value given\", name, i+1, shown)")
	e.p("\t\t}")
	e.p("\t}")
	e.p("}")
	e.p("")
	e.p("// byRefTarget names a callable the way its diagnostics do and lists its")
	e.p("// parameters, or answers nothing for a callable it cannot resolve --")
	e.p("// which the call itself then reports.")
	e.p("func byRefTarget(callable php.Value) (string, []closureParam) {")
	e.p("\tc := callable.Deref()")
	e.p("\tswitch c.Kind() {")
	e.p("\tcase php.KindString:")
	e.p("\t\ttext := strings.TrimPrefix(c.String(), \"\\\\\")")
	e.p("\t\tif class, method, ok := strings.Cut(text, \"::\"); ok {")
	e.p("\t\t\treturn byRefMethod(class, method)")
	e.p("\t\t}")
	e.p("\t\tlow := strings.ToLower(text)")
	e.p("\t\tif spelled, ok := userFuncNames[low]; ok {")
	e.p("\t\t\ttext = spelled")
	e.p("\t\t}")
	e.p("\t\treturn text, namedCallableParams[low]")
	e.p("\tcase php.KindObject:")
	e.p("\t\tif b, ok := c.Object().Internal.(*closureBody); ok {")
	e.p("\t\t\treturn closureFrameName(b, b.this, b.scope), b.meta.params")
	e.p("\t\t}")
	e.p("\t\treturn byRefMethod(c.Object().ClassName, \"__invoke\")")
	e.p("\tcase php.KindArray:")
	e.p("\t\trecv, okr := c.Array().Get(php.IntKey(0))")
	e.p("\t\tm, okm := c.Array().Get(php.IntKey(1))")
	e.p("\t\tif !okr || !okm {")
	e.p("\t\t\treturn \"\", nil")
	e.p("\t\t}")
	e.p("\t\trecv = recv.Deref()")
	e.p("\t\tif recv.Kind() == php.KindObject {")
	e.p("\t\t\t// `[$closure, \"__invoke\"]` is the Closure class's method, and")
	e.p("\t\t\t// is named that way: `Closure::__invoke(): Argument #1`.")
	e.p("\t\t\tif b, ok := recv.Object().Internal.(*closureBody); ok && strings.EqualFold(m.Deref().String(), \"__invoke\") {")
	e.p("\t\t\t\treturn \"Closure::__invoke\", b.meta.params")
	e.p("\t\t\t}")
	e.p("\t\t\treturn byRefMethod(recv.Object().ClassName, m.Deref().String())")
	e.p("\t\t}")
	e.p("\t\treturn byRefMethod(recv.String(), m.Deref().String())")
	e.p("\t}")
	e.p("\treturn \"\", nil")
	e.p("}")
	e.p("")
	e.p("// byRefMethod is byRefTarget for a method: named after the class that")
	e.p("// declares it, spelled as declared.")
	e.p("func byRefMethod(class, method string) (string, []closureParam) {")
	e.p("\towner, spelling, _, ok := methodOwnerOf(realClass(class), strings.ToLower(method))")
	e.p("\tif !ok {")
	e.p("\t\treturn \"\", nil")
	e.p("\t}")
	e.p("\treturn php.DisplayName(owner) + \"::\" + spelling, namedCallableParams[strings.ToLower(owner+\"::\"+method)]")
	e.p("}")
	e.p("")
	e.p("// callDynamic is `$f()`: callValue, except that a callable naming a")
	e.p("// **class** -- `\"C::m\"` or `[\"C\", \"m\"]` -- must reach a static method.")
	e.p("// Probed: from inside an instance method of C, `$f()` refuses a")
	e.p("// non-static `m` with `Non-static method C::m() cannot be called")
	e.p("// statically`, and so it does the `__call` a missing `m` would reach,")
	e.p("// where `call_user_func` runs both on `$this`. `__callStatic` is static")
	e.p("// and answers.")
	e.p("func callDynamic(ctx *php.Ctx, callable php.Value, args []php.Value) (php.Value, error) {")
	e.p("\tclass, method := \"\", \"\"")
	e.p("\t// **What cannot be called is refused in the engine's words**, each")
	e.p("\t// shape its own (probed): a Go error here escaped every `catch`.")
	e.p("\tswitch c := callable.Deref(); c.Kind() {")
	e.p("\tcase php.KindString:")
	e.p("\t\tclass, method, _ = strings.Cut(c.String(), \"::\")")
	e.p("\tcase php.KindArray:")
	e.p("\t\ta := c.Array()")
	e.p("\t\tif a.Len() != 2 {")
	e.p("\t\t\treturn php.Value{}, php.RaiseAt(ctx, \"Error\", \"%%s\", \"Array callback must have exactly two elements\")")
	e.p("\t\t}")
	e.p("\t\tr, okr := a.Get(php.IntKey(0))")
	e.p("\t\tm, okm := a.Get(php.IntKey(1))")
	e.p("\t\t// Two elements under other keys are refused before either is")
	e.p("\t\t// looked at (bug63173: `[1 => 0, 2 => 0]`).")
	e.p("\t\tif !okr || !okm {")
	e.p("\t\t\treturn php.Value{}, php.RaiseAt(ctx, \"Error\", \"%%s\", \"Array callback has to contain indices 0 and 1\")")
	e.p("\t\t}")
	e.p("\t\tif k := r.Deref().Kind(); !okr || k != php.KindString && k != php.KindObject {")
	e.p("\t\t\treturn php.Value{}, php.RaiseAt(ctx, \"Error\", \"%%s\", \"First array member is not a valid class name or object\")")
	e.p("\t\t}")
	e.p("\t\tif !okm || m.Deref().Kind() != php.KindString {")
	e.p("\t\t\treturn php.Value{}, php.RaiseAt(ctx, \"Error\", \"%%s\", \"Second array member is not a valid method\")")
	e.p("\t\t}")
	e.p("\t\tif r.Deref().Kind() == php.KindString {")
	e.p("\t\t\tclass, method = r.Deref().String(), m.Deref().String()")
	e.p("\t\t}")
	e.p("\tcase php.KindObject:")
	e.p("\t\t// Only `__invoke` makes an object callable; `__call` does not.")
	e.p("\t\to := c.Object()")
	e.p("\t\tif _, isClosure := o.Internal.(*closureBody); !isClosure {")
	e.p("\t\t\tif _, _, _, known := methodOwnerOf(o.ClassName, \"__invoke\"); !known {")
	e.p("\t\t\t\treturn php.Value{}, php.RaiseAt(ctx, \"Error\", \"Object of type %%s is not callable\", php.DisplayName(o.ClassName))")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\tdefault:")
	e.p("\t\treturn php.Value{}, php.RaiseAt(ctx, \"Error\", \"Value of type %%s is not callable\", php.TypeName(c))")
	e.p("\t}")
	e.p("\tif declared := realClass(class); declared != \"\" && method != \"\" && !strings.Contains(method, \"::\") {")
	e.p("\t\tif owner, spelled, isStatic, known := methodOwnerOf(declared, strings.ToLower(method)); known {")
	e.p("\t\t\tif !isStatic {")
	e.p("\t\t\t\treturn php.Value{}, php.ThrowNonStaticCall(ctx, owner, spelled)")
	e.p("\t\t\t}")
	e.p("\t\t} else if callerThis(ctx, declared) != nil {")
	e.p("\t\t\tfor c := declared; c != \"\"; c = parentOf[c] {")
	e.p("\t\t\t\tif hasMagic[c][\"__call\"] {")
	e.p("\t\t\t\t\treturn php.Value{}, php.ThrowNonStaticCall(ctx, declared, method)")
	e.p("\t\t\t\t}")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn callValue(ctx, callable, args)")
	e.p("}")
	e.p("")
	e.p("// trampolineName is the method name `__call` and `__callStatic` receive:")
	e.p("// the engine's trampoline keeps it as a C string, so it ends at the first")
	e.p("// NUL byte. Probed: `$a::$b()` with `$b = \"a\\0b\"` hands over \"a\",")
	e.p("// and `\"\\0z\"` hands over \"\" (bug46238).")
	e.p("func trampolineName(name string) php.Value {")
	e.p("\tif i := strings.IndexByte(name, 0); i >= 0 {")
	e.p("\t\tname = name[:i]")
	e.p("\t}")
	e.p("\treturn php.String(name)")
	e.p("}")
	e.p("")
	e.p("// refReturnDefined gives a box a by-reference return hands back a")
	e.p("// defined value: the variable behind it was fetched for writing, which")
	e.p("// creates it as null.")
	e.p("func refReturnDefined(v php.Value) php.Value {")
	e.p("\tif r, ok := v.RefOf(); ok && r.Get().IsUndef() {")
	e.p("\t\tr.Set(php.Null())")
	e.p("\t}")
	e.p("\treturn v")
	e.p("}")
	e.p("")
	e.p("// staticReturnType is a declared return type with `static` replaced by")
	e.p("// the called class; with none -- an unbound closure -- it is left as")
	e.p("// written.")
	e.p("func staticReturnType(declared, called string) string {")
	e.p("\tif called == \"\" {")
	e.p("\t\treturn declared")
	e.p("\t}")
	e.p("\tvar b strings.Builder")
	e.p("\tword := strings.Builder{}")
	e.p("\tflush := func() {")
	e.p("\t\tif strings.EqualFold(word.String(), \"static\") {")
	e.p("\t\t\tb.WriteString(php.DisplayName(called))")
	e.p("\t\t} else {")
	e.p("\t\t\tb.WriteString(word.String())")
	e.p("\t\t}")
	e.p("\t\tword.Reset()")
	e.p("\t}")
	e.p("\tfor _, r := range declared {")
	e.p("\t\tif strings.ContainsRune(\"?|&() \", r) {")
	e.p("\t\t\tflush()")
	e.p("\t\t\tb.WriteRune(r)")
	e.p("\t\t\tcontinue")
	e.p("\t\t}")
	e.p("\t\tword.WriteRune(r)")
	e.p("\t}")
	e.p("\tflush()")
	e.p("\treturn b.String()")
	e.p("}")
	e.p("")
	e.p("// reflectingConsts is set while reflection reads a class's constants,")
	e.p("// which may be a trait's -- the one reader the trait refusal exempts.")
	e.p("var reflectingConsts bool")
	e.p("")
	e.p("// callFunctionRefs marks a call made the way the engine's")
	e.p("// zend_call_function makes one -- a callback, `call_user_func_array` --")
	e.p("// which alone hands `__call` the references it was sent: its `$args`")
	e.p("// holds `&int(1)` for `call_user_func_array([$p, 'm'], [&$a])`, where a")
	e.p("// direct `$p->m($a)` sends a value (\"don't separate references for")
	e.p("// __call\", bug50394). One-shot: each hop takes it, so it cannot reach")
	e.p("// a call nested inside the callee.")
	e.p("var callFunctionRefs bool")
	e.p("")
	e.p("// callbackValue is `callValue` for an argument list built without the")
	e.p("// caller's slots: a callback an internal function invokes, and a")
	e.p("// `call_user_func` the compiler expanded in place. A by-reference")
	e.p("// parameter given a value warns first, and a handler that throws from")
	e.p("// that warning stops the call.")
	e.p("func callbackValue(ctx *php.Ctx, callable php.Value, args []php.Value) (php.Value, error) {")
	e.p("\twarnByValue(ctx, callable, args)")
	e.p("\tif err := ctx.TakePendingError(); err != nil {")
	e.p("\t\treturn php.Value{}, err")
	e.p("\t}")
	e.p("\tcallFunctionRefs = true")
	e.p("\treturn callValue(ctx, callable, args)")
	e.p("}")
	e.p("")
	e.p("// callStaticCallable is the `Class::method` callable, in both its string")
	e.p("// and its two-element-array spelling.")
	e.p("//")
	e.p("// The scope passed is the class itself, which means **visibility is not")
	e.p("// checked here**. PHP does check it, from the scope that built the")
	e.p("// callable, and nothing on this path carries one -- so this keeps the")
	e.p("// behaviour that was already there rather than guessing a scope and")
	e.p("// refusing programs the engine runs. The non-static and abstract rules")
	e.p("// do apply, and those are what the callable tests are about.")
	e.p("// keywordDeprecationSaid is checkUserCallable having raised the")
	e.p("// `self::` deprecation for the call that follows it.")
	e.p("var keywordDeprecationSaid bool")
	e.p("")
	e.p("func callStaticCallable(ctx *php.Ctx, class, method string, args []php.Value) (php.Value, error) {")
	e.p("	// **A keyword as the class is deprecated, not refused.** `'self::s'`")
	e.p("	// and `['self', 's']` are the same callable written two ways, and both")
	e.p("	// reach here -- so the resolution lives in one place. `self` and")
	e.p("	// `parent` come off the calling scope; `static` is late static binding,")
	e.p("	// which the frame's own class stands in for.")
	e.p("	scope := callerScope(ctx)")
	e.p("\tswitch strings.ToLower(class) {")
	e.p("	case \"self\", \"static\", \"parent\":")
	e.p("\t\tif keywordDeprecationSaid {")
	e.p("\t\t\tkeywordDeprecationSaid = false")
	e.p("\t\t} else {")
	e.p("\t\t\tctx.Deprecated(`Use of \"%%s\" in callables is deprecated`, strings.ToLower(class))")
	e.p("\t\t}")
	e.p("\t\tif err := ctx.TakePendingError(); err != nil {")
	e.p("\t\t\treturn php.Value{}, err")
	e.p("\t\t}")
	e.p("		target := scope")
	e.p("		if strings.EqualFold(class, \"parent\") {")
	e.p("			target = parentOf[realClass(scope)]")
	e.p("\t\t}")
	e.p("		if strings.EqualFold(class, \"static\") {")
	e.p("			// **Late static binding**: the class the *call* named, not")
	e.p("			// the one that declared the running body. `Test2::test()` on")
	e.p("			// a `test` declared by Test1 resolves `static` to Test2.")
	e.p("			if l := callerLSB(ctx); l != \"\" {")
	e.p("				target = l")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("		if target == \"\" {")
	e.p("			return php.Value{}, php.RaiseAt(ctx, \"Error\", \"Cannot use \\\"%%s\\\" when no class scope is active\", strings.ToLower(class))")
	e.p("\t\t}")
	e.p("\t\t// The keyword spellings forward the called class, as the written")
	e.p("\t\t// `self::m()` and `parent::m()` do.")
	e.p("\t\tif l := callerLSB(ctx); l != \"\" {")
	e.p("\t\t\tpendingLSB = l")
	e.p("\t\t}")
	e.p("\t\tv, err := callStaticFrom(ctx, target, method, callerThis(ctx, target), args, scope)")
	e.p("\t\tpendingLSB = \"\"")
	e.p("\t\treturn v, err")
	e.p("\t}")
	e.p("\t// **The caller's `$this` comes along** when it is an instance of the")
	e.p("\t// class: `call_user_func([\"A\", \"m\"])` inside a method of A (or of")
	e.p("\t// a subclass) calls a non-static `m` on that object, and reaches")
	e.p("\t// `__call` rather than `__callStatic` for a name A does not declare.")
	e.p("\t// Class names are case-insensitive: `[\"FOO\", \"m\"]` names `foo`.")
	e.p("\tif declared := realClass(class); declared != \"\" {")
	e.p("\t\tclass = declared")
	e.p("\t} else if engineClassKind[strings.ToLower(resolveAlias(class))] {")
	e.p("\t\t// An engine class is spelled as the engine declares it:")
	e.p("\t\t// `Call to undefined method stdClass::b()` for `[\"stdclass\", \"b\"]`.")
	e.p("\t\tclass = engineSpelling(resolveAlias(class))")
	e.p("\t} else {")
	e.p("\t\t// **The class is resolved first**, autoloading it: a callable")
	e.p("\t\t// naming a class nobody declares is `Class \"X\" not found`, not")
	e.p("\t\t// an undefined method of it.")
	e.p("\t\tif found, err := knownClass(ctx, class); err != nil {")
	e.p("\t\t\treturn php.Value{}, err")
	e.p("\t\t} else if found == \"\" {")
	e.p("\t\t\treturn php.Value{}, php.ThrowClassNotFound(class)")
	e.p("\t\t} else {")
	e.p("\t\t\tclass = found")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn callStaticFrom(ctx, class, method, callerThis(ctx, class), args, class)")
	e.p("}")
	e.p("")
	e.p("// errorLevels maps a diagnostic level to the E_* code a handler is passed.")
	e.p("// Values taken from the engine rather than from the headers.")
	e.p("var errorLevels = map[string]int64{")
	e.p("\t\"Warning\": 2, \"Notice\": 8, \"Deprecated\": 8192,")
	e.p("\t\"UserWarning\": 512, \"UserNotice\": 1024, \"UserDeprecated\": 16384,")
	e.p("}")
	e.p("")
	e.p("// installErrorHandler wires diagnostics to whatever set_error_handler put")
	e.p("// on the stack. Consulted for *every* diagnostic, including one that")
	e.p("// error_reporting would hide or @ would suppress: the mask gates the")
	e.p("// default handler, not the callback.")
	e.p("func installErrorHandler(ctx *php.Ctx) {")
	e.p("\tctx.SetErrorHandler(func(level, message, file string, line uint32) (bool, error) {")
	e.p("\t\t// set_error_handler(null) puts *no handler* on the stack rather than")
	e.p("\t\t// clearing it, so an absent entry means default handling and a")
	e.p("\t\t// restore brings the previous one back. The Ctx owns that rule.")
	e.p("\t\thandler, ok := ctx.CurrentErrorHandler()")
	e.p("\t\tif !ok {")
	e.p("\t\t\treturn false, nil")
	e.p("\t\t}")
	e.p("\t\tcode, known := errorLevels[level]")
	e.p("\t\tif !known {")
	e.p("\t\t\tcode = 256")
	e.p("\t\t}")
	e.p("\t\trestore := ctx.EnterErrorHandler()")
	e.p("\t\tanswer, err := callValue(ctx, handler, []php.Value{")
	e.p("\t\t\tphp.Int(code), php.String(message), php.String(file), php.Int(int64(line)),")
	e.p("\t\t})")
	e.p("\t\trestore()")
	e.p("\t\tif err != nil {")
	e.p("\t\t\t// The handler threw. That counts as handling the diagnostic --")
	e.p("\t\t\t// the default text is not printed -- and the exception carries out.")
	e.p("\t\t\treturn true, err")
	e.p("\t\t}")
	e.p("\t\t// Only an explicit false asks for the default handling as well.")
	e.p("\t\treturn !(answer.Kind() == php.KindFalse), nil")
	e.p("\t})")
	e.p("}")
	e.p("")
	e.p("func main() {")
	// Imported unconditionally, so referenced unconditionally: a program with no
	// non-finite literal would otherwise fail to build on an unused import.
	e.p("\tvar _ = math.Inf")
	if gcCalled(p) {
		// Every object is recorded for gcCollectCycles' check.
		e.p("\tphp.TrackObjects()")
	}
	// **Collect less often than Go's default.** The engine frees by
	// reference count and never pauses to trace; a Go heap collected every
	// time it doubles spent up to 40%% of an allocation-heavy PHP loop in the
	// collector, over a heap of a few megabytes. Four times the live heap
	// between collections halved that; an explicit GOGC still wins.
	e.p("\tif os.Getenv(\"GOGC\") == \"\" {")
	e.p("\t\tdebug.SetGCPercent(400)")
	e.p("\t}")
	e.p("\tctx := php.NewCtx(os.Stdout)")
	e.p("\tenumCtx = ctx")
	// **A library function written in PHP is one engine function** to a
	// trace and to the position a failure inside it reports: the frames its
	// body makes are hidden, a callback it makes renders `[internal
	// function]`, and an error raised in it names the caller's line.
	if entries := publicLibraryNames(e.libraryFile); len(entries) > 0 {
		e.p("\tctx.SetLibraryEntries(map[string]bool{")
		for _, n := range entries {
			e.p("\t\t%q: true,", n)
		}
		e.p("\t})")
	}
	// Before anything the program itself prints: the engine emitted these while
	// compiling, which for a script happens before the first statement runs.
	e.p("\tctx.Write(compileDiagnostic)")
	// What an object shows under var_dump needs a class table, which the
	// generated program has: the dispatcher already knows every class's methods,
	// so `__debugInfo` is one lookup away.
	e.p("\t// Making an object: handles belong to this program, so a shared")
	e.p("\t// builtin that needs one asks for it rather than inventing a number.")
	e.p("\tctx.SetObjectMaker(func(_ *php.Ctx, class string) *php.Object {")
	e.p("\t\treturn php.NewObject(class, allocObjectID())")
	e.p("\t})")
	e.p("\tctx.SetObjectToString(objectToString)")
	e.p("\tctx.SetCountObject(countObject)")
	e.p("\tctx.SetObjectProperties(objectProperties)")
	e.p("\tphp.DateClassOf = dateClassOf")
	e.p("\t// What an object shows under `var_export` is a different question:")
	e.p("\t// plain names, duplicates kept, and a get hook **run**.")
	e.p("\tctx.SetExportProperties(exportProperties)")
	e.p("\tctx.SetCallValue(callbackValue)")
	// The other half of the callable hook: whether a value *can* be called.
	// A builtin checks its callback argument before invoking it, and reports
	// something different from what the invocation would.
	e.p("\tctx.SetCallableReason(callableReason)")
	e.p("\t// The hierarchy question the visibility intrinsic cannot answer for")
	e.p("\t// itself: runtime/php has no class table, and this program does.")
	e.p("\tctx.SetSubclassOf(extendsClass)")
	e.p("\t// What a backtrace puts in place of a `#[\\SensitiveParameter]`")
	e.p("\t// argument. Handed over rather than called eagerly: nothing is built")
	e.p("\t// unless a frame actually has one.")
	e.p("\t// The two class-table questions `serialize` asks: whether a method")
	e.p("\t// exists -- asked **without** running `__call` -- and whether the")
	e.p("\t// class is one the engine refuses to write at all. No program this")
	e.p("\t// compiler emits declares one of the latter, so that answer is")
	e.p("\t// constant here rather than absent.")
	e.p("\tctx.SetHasMethod(hasMethod)")
	e.p("\t// And the narrower one an ArrayObject's dimension handler asks: a")
	e.p("\t// program `offsetGet` replaces the engine's storage access.")
	e.p("\tctx.SetProgramMethod(hasCompiledMethod)")
	e.p("\tctx.SetObjectRefWalk(php.ObjectRefWalk{Boxes: plainRefBoxes})")
	e.p("\tctx.SetClassFacts(classFacts)")
	e.p("\tctx.SetPropertyFacts(propertyFacts)")
	e.p("\tctx.SetNewInstance(newInstanceOf)")
	e.p("\tctx.SetEngineClassCheck(func(class string) bool {")
	e.p("\t\tfor _, c := range engineClassList {")
	e.p("\t\t\tif strings.EqualFold(c, strings.TrimPrefix(class, `\\`)) {")
	e.p("\t\t\t\treturn true")
	e.p("\t\t\t}")
	e.p("\t\t}")
	e.p("\t\treturn false")
	e.p("\t})")
	e.p("\tctx.SetClassAutoloader(autoload)")
	e.p("\tctx.SetInstanceConfined(func(class string) bool {")
	e.p("\t\treturn confinedClasses[strings.ToLower(resolveAlias(class))]")
	e.p("\t})")
	e.p("\t// A wrapper the program registered is driven through the hooks above;")
	e.p("\t// so are php://memory and php://temp, whose wrapper is userland.")
	e.p("\tctx.SetUserStreamOpener(stdlib.OpenHookedUserStream)")
	e.p("\tctx.SetResumableMaker(resumableOf)")
	e.p("\tctx.SetParentOf(func(class string) string {")
	e.p("\t\treturn parentOf[realClassOr(class)]")
	e.p("\t})")
	e.p("\tctx.SetDestructorRun(func(c *php.Ctx, o *php.Object) error {")
	e.p("\t\t// **Destroying a suspended generator closes it**: its finally")
	e.p("\t\t// blocks run where the last holder let it go -- an `unset`, an")
	e.p("\t\t// overwrite -- and a throw from one is thrown there")
	e.p("\t\t// (yield_from_force_closed).")
	e.p("\t\tif g, ok := o.Internal.(*php.Generator); ok {")
	e.p("\t\t\treturn g.Close(c)")
	e.p("\t\t}")
	e.p("\t\t// So does destroying a suspended fiber: it is force-closed, its")
	e.p("\t\t// finally blocks run, and a suspend reached on the way is refused")
	e.p("\t\t// (fibers/unfinished-fiber-with-finally).")
	e.p("\t\tif h, ok := o.Internal.(*php.FiberHandle); ok {")
	e.p("\t\t\treturn h.Driver.Close(c)")
	e.p("\t\t}")
	e.p("\t\t// **`__destruct` is never reached through `__call`.** Destroying an")
	e.p("\t\t// object of a class that has a `__call` and no destructor called")
	e.p("\t\t// the accessor with the name `__destruct`, because `callMethod`")
	e.p("\t\t// falls through to it for any name a class does not have. PHP does")
	e.p("\t\t// not: a class with no `__destruct` has nothing to run.")
	e.p("\t\tif !hasMethod(o.ClassName, \"__destruct\") {")
	e.p("\t\t\treturn nil")
	e.p("\t\t}")
	e.p("\t\t// **A destructor that may store `$this` keeps the number**: the")
	e.p("\t\t// object can live on after it (probed: `new R(..);` in a function")
	e.p("\t\t// whose `__destruct` appends `$this` to a static, then")
	e.p("\t\t// `spl_object_id(new stdClass)` is 2, not R's 1). Pinned before")
	e.p("\t\t// it runs, so no release after it hands the number to another.")
	e.p("\t\tif mayResurrect[strings.ToLower(o.ClassName)] {")
	e.p("\t\t\to.PinHandle()")
	e.p("\t\t}")
	e.p("\t\t_, err := callMethod(c, php.Obj(o), \"__destruct\", nil)")
	e.p("\t\treturn err")
	e.p("\t})")
	e.p("\tctx.SetLazyInitCall(func(c *php.Ctx, initializer php.Value, object *php.Object) (php.Value, error) {")
	e.p("\t\treturn c.Call(initializer, []php.Value{php.Obj(object)})")
	e.p("\t})")
	e.p("\tctx.SetProxyCompatible(proxyCompatible)")
	e.p("\tctx.SetClassIsFinal(func(class string) bool {")
	e.p("\t\treturn finalClasses[strings.ToLower(resolveAlias(class))]")
	e.p("\t})")
	e.p("\tctx.SetDeclaredProperties(func(class string) []php.PropertyDesc {")
	e.p("\t\treturn declaredProps[strings.ToLower(resolveAlias(class))]")
	e.p("\t})")
	e.p("\t// Initialising a lazy object for a **library function** that has to")
	e.p("\t// see its state -- `serialize` and `json_encode` both call")
	e.p("\t// `Materialize` before they look. The hook has existed all along and")
	e.p("\t// nothing installed it, so `Materialize` was the identity here and")
	e.p("\t// those functions saw an empty shell. Its own comment says the")
	e.p("\t// identity holds \"until ReflectionClass reaches\" the compiled")
	e.p("\t// back-end, which it now has.")
	e.p("\tctx.SetLazyResolver(func(c *php.Ctx, v php.Value) (php.Value, error) {")
	e.p("\t\to := v.Deref().Object()")
