	e.p("\t// dead in compiled output -- invisible until something started")
	e.p("\t// resolving on unset at all.")
	e.p("\tctx.SetMagicAvailable(func(o *php.Object, method, prop string) bool {")
	e.p("\t\tif o == nil || !hasMethod(o.ClassName, strings.ToLower(method)) {")
