	e.p("\t\t// whether the class has the method makes a lazy proxy dispatch")
	e.p("\t\t// magic that the real instance is already running -- the")
	e.p("\t\t// accessor fires twice.")
	e.p("\t\treturn !magicInFlight[[3]any{php.GuardOf(o), strings.ToLower(method), prop}]")
	e.p("\t})")
	e.p("\tctx.SetEnumCase(enumCaseOf)")
	e.p("\tctx.SetSensitiveHider(func(held php.Value) php.Value {")
