	e.p("")
	e.p("// callCtor runs a constructor and, if it succeeded, registers the object")
	e.p("// for script-end teardown.")
	e.p("//")
	e.p("// **A constructor that throws means no destructor.** Measured: `new A()`")
	e.p("// whose `__construct` throws never runs `A::__destruct`, even though the")
	e.p("// object was allocated. So registration happens here, after construction")
	e.p("// succeeds -- not in the constructor helper, which runs before")
	e.p("// `__construct` does and would register an object PHP never destroys.")
	e.p("// ctorAccess refuses a constructor `scope` cannot reach.")
	e.p("func ctorAccess(ctx *php.Ctx, recv php.Value, scope string) error {")
	e.p("\to := recv.Object()")
	e.p("\tif o == nil {")
	e.p("\t\treturn nil")
	e.p("\t}")
	e.p("\td, restricted := methodVisibility[o.ClassName][\"__construct\"]")
	e.p("\t// **Measured against the constructor's own class**, not an ancestor")
	e.p("\t// prototype: a constructor overriding its parent's has none, so")
	e.p("\t// `new C4` from B4 -- both extending A4, C4 redeclaring a protected")
	e.p("\t// constructor -- is refused (bug37632), where a method would pass.")
	e.p("\td[2] = d[0]")
	e.p("\tif !restricted || methodReachable(d, scope) {")
	e.p("\t\treturn nil")
	e.p("\t}")
	e.p("\tfrom := \"global scope\"")
	e.p("\tif scope != \"\" {")
	e.p("\t\tfrom = \"scope \" + php.DisplayName(scope)")
	e.p("\t}")
	e.p("\treturn php.RaiseAt(ctx, \"Error\", \"Call to %%s %%s::__construct() from %%s\", d[1], php.DisplayName(d[0]), from)")
	e.p("}")
	e.p("")
	e.p("func callCtor(ctx *php.Ctx, recv php.Value, args []php.Value) (php.Value, error) {")
	e.p("\tv, err := runCtor(ctx, recv, args)")
	e.p("\tif err == nil && recv.Kind() == php.KindObject &&")
	e.p("\t\thasCompiledMethod(recv.Object().ClassName, \"__destruct\") {")
	e.p("\t\tctx.RegisterDestructible(recv.Object())")
	e.p("\t}")
	e.p("\treturn v, err")
	e.p("}")
	e.p("")
	e.p("func runCtor(ctx *php.Ctx, recv php.Value, args []php.Value) (php.Value, error) {")
	e.p("\tif recv.Kind() != php.KindObject {")
	e.p("\t\treturn php.Value{}, fmt.Errorf(\"construction of a non-object\")")
	e.p("\t}")
	e.p("\tswitch recv.Object().ClassName {")
	for _, c := range classes {
		owner, ok := effective[strings.ToLower(c.Name)]["__construct"]
		if !ok {
			continue
		}
		// A constructor is an ordinary frame in a trace -- `#1 file(23):
		// c->__construct()` -- and without one every throw inside a
		// constructor came out a frame short.
		//
		// Pushed only here, in the user-class arm. The engine exception arm
		// below captures the new throwable's trace from this same stack, and
		// PHP captures that trace at `new`, *before* entering the constructor:
		// a frame pushed for the whole function would put `__construct` into
		// every exception's own trace.
		e.p("\tcase %q:", c.Name)
		// **An exception is an exception before its constructor runs**: the
		// engine gives it its message, code, file, line and trace when the
		// object is created, so a constructor that never calls the parent's
		// still has them, and one that does writes over them
		// (bug64821.2). Asked at run time, since the root may be an engine
		// class reached through an alias.
		e.p("\t\tif php.IsThrowableClass(rootOf(%q)) {", c.Name)
		e.p("\t\t\tif err := throwableCtor(ctx, recv.Object(), nil, true); err != nil {")
		e.p("\t\t\t\treturn php.Value{}, err")
		e.p("\t\t\t}")
		e.p("\t\t}")
		e.p("\t\tfile, line := ctx.Location()")
		e.p("\t\tctx.PushCall(php.StackFrame{Function: %q, File: file, Line: line, Args: args, This: recv.Object()})",
			owner+"->__construct")
		e.p("\t\tdefer ctx.PopCall()")
		e.p("\t\treturn %s(ctx, recv.Object(), args)", methodName(owner, "__construct"))
	}
	e.p("\t}")
	e.p("\t// **An engine class's constructor gets a frame too**, and the same")
	e.p("\t// one `engineFramed` gives its methods: the declaring engine class")
	e.p("\t// and that declaration's spelling. `new ReflectionClass(\"Nope\")`")
	e.p("\t// and `new WeakReference()` both raise, and both opened their trace")
	e.p("\t// at the `new` with the constructor missing from it.")
	e.p("\t//")
	e.p("\t// The exception classes below are **not** reached by this: they are")
	e.p("\t// not in the modelled engine set, so nothing claims their")
	e.p("\t// `__construct`. That matters -- their arm captures the new")
	e.p("\t// throwable's trace from this same stack, and PHP captures it at")
	e.p("\t// `new`, before entering the constructor, so a frame here would put")
	e.p("\t// `__construct` into every exception's own trace.")
	e.p("\t// Refused at `new`, before a constructor frame exists.")
	e.p("\tif o := recv.Object(); strings.EqualFold(o.ClassName, \"FilterIterator\") && splClassOf(o.ClassName) != \"\" {")
	e.p("\t\treturn php.Value{}, php.RaiseAt(ctx, \"Error\", \"%%s\", \"Cannot instantiate abstract class FilterIterator\")")
	e.p("\t}")
	e.p("\tif o := recv.Object(); strings.EqualFold(o.ClassName, \"SplHeap\") && splClassOf(o.ClassName) != \"\" {")
	e.p("\t\treturn php.Value{}, php.RaiseAt(ctx, \"Error\", \"%%s\", \"Cannot instantiate abstract class SplHeap\")")
	e.p("\t}")
	e.p("\tif o := recv.Object(); engineClaimsCtor(o.ClassName) {")
	e.p("\t\treturn engineFramed(ctx, o, \"__construct\", args, func() (php.Value, error) {")
	e.p("\t\t\treturn runEngineCtor(ctx, recv, args)")
	e.p("\t\t})")
	e.p("\t}")
	e.p("\treturn runEngineCtor(ctx, recv, args)")
	e.p("}")
	e.p("")
	e.p("// engineClaimsCtor reports whether an engine class declares the")
	e.p("// constructor this object's class reaches, which is also the question of")
	e.p("// whether there is a declaration to name a frame after.")
	e.p("func engineClaimsCtor(class string) bool {")
	e.p("\towner, _ := engineMethodOwner(class, \"__construct\")")
	e.p("\treturn owner != \"\"")
	e.p("}")
	e.p("")
	e.p("// throwableSlot is where an exception's protected property lives in")
	e.p("// compiled code: under its plain name, as every compiled protected")
	e.p("// property is, so `$this->line = 0` in a subclass writes the same slot")
	e.p("// the engine's accessors read. A property InitThrowable left under the")
	e.p("// engine's mangled key -- one no fresh construction has moved -- is")
