	e.p("func throwableSlot(o *php.Object, name string) php.Key {")
	e.p("\tif _, own := o.PropRaw(php.StringKey(name)); !own {")
	e.p("\t\tif _, engine := o.PropRaw(php.StringKey(php.MangleProperty(\"*\", name))); engine {")
	e.p("\t\t\treturn php.StringKey(php.MangleProperty(\"*\", name))")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\treturn php.StringKey(name)")
	e.p("}")
	e.p("")
	e.p("// setThrowableTrace records the stack an exception was made on, and")
