	e.p("\tkey := php.StringKey(php.MangleProperty(php.ObjectThrowableRoot(o), \"trace\"))")
	e.p("\tif _, ok := o.PropRaw(key); ok {")
	e.p("\t\to.PropSet(key, php.Arr(stdlib.TraceArray(ctx, stack, false)))")
	e.p("\t}")
	e.p("}")
	e.p("")
	e.p("// throwableCtor is the engine's constructor for an exception class the")
	e.p("// program did not define, coercing as it declares its parameters.")
	e.p("// fresh is construction by `new`; otherwise it is `$e->__construct()`")
	e.p("// called on a live exception.")
	e.p("func throwableCtor(ctx *php.Ctx, o *php.Object, args []php.Value, fresh bool) error {")
