	e.p("\tfile, line := ctx.Location()")
	e.p("\tctx.PushCall(php.StackFrame{Function: owner + \"->__construct\", File: file, Line: line, Args: args, This: o})")
	e.p("\tcoerced := make([]php.Value, len(args))")
