	e.p("\t\t}")
	e.p("\t\tcoerced[i] = v")
	e.p("\t}")
	e.p("\tctx.PopCall()")
	e.p("\tmsg, code, prev := \"\", int64(0), php.Null()")
	e.p("\tif len(coerced) > 0 {")
	e.p("\t\tmsg = coerced[0].String()")
	e.p("\t}")
	e.p("\tif len(coerced) > 1 {")
	e.p("\t\tcode = coerced[1].Int()")
	e.p("\t}")
	e.p("\tif at := len(params) - 1; len(coerced) > at {")
