	e.p("\t\town := map[string]php.Value{}")
	e.p("\t\tfor _, name := range []string{\"message\", \"code\", \"file\", \"line\"} {")
	e.p("\t\t\tif v, ok := o.PropRaw(php.StringKey(name)); ok {")
