	e.p("\t\t}")
	e.p("\t\t// **The trace is the creation's**, not the constructor's: `new`")
	e.p("\t\t// already built it (setThrowableTrace), and building a second")
	e.p("\t\t// one here made its hidden arguments' wrappers twice, the first")
	e.p("\t\t// set holding numbers nothing freed.")
	e.p("\t\ttraceKey := php.StringKey(php.MangleProperty(php.ObjectThrowableRoot(o), \"trace\"))")
	e.p("\t\tbuilt, hadTrace := o.PropRaw(traceKey)")
