	e.p("\t\t// `line` beside it and the accessors read the first (bug64821.2).")
	e.p("\t\tmoved := php.NewArray()")
	e.p("\t\to.Table().EachRaw(func(k php.Key, v php.Value) bool {")
	e.p("\t\t\tif plain, owner, mangled := php.UnmangleProperty(k.String()); !k.IsInt && mangled && owner == \"*\" {")
	e.p("\t\t\t\tif _, declared := own[plain]; declared && (plain == \"message\" && len(coerced) < 1 || plain == \"code\" && len(coerced) < 2) {")
	e.p("\t\t\t\t\treturn true")
	e.p("\t\t\t\t}")
