	e.p("\tif at := len(params) - 1; !fresh && len(coerced) > at && prev.Kind() != php.KindNull {")
	e.p("\t\to.PropSet(php.StringKey(php.MangleProperty(root, \"previous\")), prev)")
	e.p("\t}")
	e.p("\t// **ErrorException's own three**, probed: `$severity` defaults to")
	e.p("\t// E_ERROR; a `$filename` replaces the file and resets the line to")
	e.p("\t// `$line` or 0; a `$line` with no filename sets only the line.")
	e.p("\tif owner == \"ErrorException\" {")
	e.p("\t\tsev := int64(1)")
	e.p("\t\tif len(coerced) > 2 {")
	e.p("\t\t\tsev = coerced[2].Int()")
	e.p("\t\t}")
	e.p("\t\tsetProtected := func(name string, v php.Value) {")
