	e.p("\t\t\tif hasLine {")
	e.p("\t\t\t\tsetProtected(\"line\", php.Int(lineArg.Int()))")
	e.p("\t\t\t} else {")
	e.p("\t\t\t\tsetProtected(\"line\", php.Int(0))")
	e.p("\t\t\t}")
	e.p("\t\t} else if hasLine {")
	e.p("\t\t\tsetProtected(\"line\", php.Int(lineArg.Int()))")
	e.p("\t\t}")
	e.p("\t}")
	e.p("\t// **The engine's properties come first**, in the engine's order,")
	e.p("\t// then the subclass's own: the parent's table precedes the child's.")
	e.p("\t// A compiled subclass's declared slots were laid out ahead of what")
	e.p("\t// InitThrowable added, so `class MyEx extends Exception { public")
	e.p("\t// $extra; }` dumped `extra` first -- and a redeclared `$code`, sharing")
	e.p("\t// the engine's slot, would sit among the subclass's.")
	e.p("\tif fresh {")
	e.p("\t\ttable := o.Table()")
	e.p("\t\tordered := php.NewArray()")
	e.p("\t\ttaken := map[php.Key]bool{}")
	e.p("\t\tfor _, name := range []string{\"message\", \"string\", \"code\", \"file\", \"line\", \"trace\", \"previous\", \"severity\"} {")
	e.p("\t\t\tfor _, k := range []string{php.MangleProperty(\"*\", name), php.MangleProperty(root, name), name} {")
	e.p("\t\t\t\tif v, ok := table.Raw(php.StringKey(k)); ok && !taken[php.StringKey(k)] {")
	e.p("\t\t\t\t\tordered.Bind(php.StringKey(k), v)")
