	e.p("")
	e.p("// runEngineCtor is runCtor's remainder: the classes whose construction")
	e.p("// this output supplies rather than compiles.")
	e.p("func runEngineCtor(ctx *php.Ctx, recv php.Value, args []php.Value) (php.Value, error) {")
	e.p("\tif d := dateClassOf(recv.Object().ClassName); d != \"\" {")
	e.p("\t\treturn php.Null(), php.DateConstructObject(ctx, d, recv.Object(), args)")
	e.p("\t}")
